/* =========================================
   New Hero / Empty State Design (Luxury Edition)
   ========================================= */

.empty-state-hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 70vh;
  text-align: center;
  padding: 40px 20px;
  animation: heroFadeIn 0.8s ease-out;
  position: relative;
  z-index: 1;
}

@keyframes heroFadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Hero Logo */
.hero-logo-container {
  position: relative;
  width: 120px;
  height: 120px;
  margin-bottom: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-logo-glow {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 160%;
  height: 160%;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle, var(--accent-glow) 0%, transparent 70%);
  opacity: 0.3;
  /* Subtle luxury glow */
  animation: pulseGlow 5s infinite alternate;
  pointer-events: none;
}

.hero-logo-content {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, rgba(240, 185, 11, 0.05), rgba(0, 0, 0, 0.4));
  border-radius: 28px;
  border: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  z-index: 2;
  box-shadow: 0 20px 70px rgba(0, 0, 0, 0.4);
  transition: all 0.3s ease;
}

.hero-logo-container:hover .hero-logo-content {
  transform: translateY(-2px) scale(1.02);
  border-color: var(--accent-primary);
  box-shadow: 0 26px 90px rgba(240, 185, 11, 0.15);
}

.hero-logo-text {
  font-size: 42px;
  font-weight: 900;
  color: var(--text-primary);
  letter-spacing: -2px;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.5);
}

.hero-logo-text span:not(.logo-letter-yellow) {
  background: var(--brand-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* Hero Typography */
.hero-title {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 16px;
  line-height: 1.1;
}

.hero-title-main {
  font-size: 48px;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -1px;
}

.hero-title-sub {
  font-size: 48px;
  font-weight: 800;
  background: var(--brand-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  letter-spacing: -1px;
}

.hero-subtitle {
  font-size: 18px;
  color: var(--text-secondary);
  max-width: 600px;
  margin-bottom: 48px;
  line-height: 1.6;
}

/* Hero Suggestions Grid */
.hero-suggestions {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  width: 100%;
  max-width: 800px;
}

@media (max-width: 768px) {
  .hero-suggestions {
    grid-template-columns: 1fr;
  }

  .hero-title-main,
  .hero-title-sub {
    font-size: 36px;
  }
}

.hero-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  padding: 20px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  gap: 16px;
  text-align: left;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  position: relative;
  overflow: hidden;
}

.hero-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, transparent 0%, rgba(240, 185, 11, 0.05) 100%);
  opacity: 0;
  transition: opacity 0.3s ease;
}

.hero-card:hover {
  transform: translateY(-3px);
  border-color: var(--accent-primary);
  box-shadow: 0 10px 40px -10px rgba(240, 185, 11, 0.1);
}

.hero-card:hover::before {
  opacity: 1;
}

.hero-card-icon {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  background: rgba(240, 185, 11, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-primary);
  flex-shrink: 0;
  border: 1px solid rgba(240, 185, 11, 0.1);
  transition: all 0.3s ease;
}

.hero-card:hover .hero-card-icon {
  background: var(--accent-primary);
  color: #000;
  border-color: transparent;
  box-shadow: 0 0 15px var(--accent-glow);
}

.hero-card-content h3 {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 4px;
}

.hero-card-content p {
  font-size: 13px;
  color: var(--text-muted);
  line-height: 1.4;
}

