                    <Suspense fallback={<div className="route-loading">Loading...</div>}>
                      <WorkspaceSettings />
                    </Suspense>
                  </RequireAuth>
                }
              />
            </Route>
          </Routes>
        </BrowserRouter>
      );

      if (GOOGLE_CLIENT_ID) {
        return <GoogleOAuthProvider clientId={GOOGLE_CLIENT_ID}>{appTree}</GoogleOAuthProvider>;
      }
      return appTree;
    })()}
  </React.StrictMode>
);

