/**
 * Analyzes request complexity to determine the best AI provider
 */

export type Complexity = 'simple' | 'medium' | 'complex';

interface ComplexityScore {
    level: Complexity;
    confidence: number;
    reasoning: string;
}

/**
 * Analyze message complexity
 */
export function analyzeComplexity(message: string): ComplexityScore {
    const msg = message.toLowerCase();
    const length = message.length;

    // Simple patterns (greetings, basic questions)
    const simplePatterns = [
        /^(hi|hello|hey|مرحبا|السلام|اهلا)\b/i,
        /^(how are you|كيف حالك|شلونك)/i,
        /^(thanks|شكرا|thank you)/i,
        /^(yes|no|نعم|لا|ok|okay|حسنا)\s*$/i,
    ];

    // Complex patterns (architecture, analysis, planning)
    const complexPatterns = [
        /\b(architect|design|structure|معمارية|تصميم|هيكل)\b/i,
        /\b(analyze|analysis|تحليل|audit|review|مراجعة)\b/i,
        /\b(implement|build|create.*system|إنشاء.*نظام|بناء)\b/i,
        /\b(optimize|performance|أداء|تحسين|تطوير)\b/i,
        /\b(database|schema|migration|قاعدة\s+بيانات)\b/i,
        /\b(security|authentication|أمان|مصادقة)\b/i,
    ];

    // Medium patterns (coding, translation, moderate tasks)
    const mediumPatterns = [
        /\b(write.*function|اكتب.*دالة|code|كود|برمجة)\b/i,
        /\b(translate|ترجم|convert|حول)\b/i,
        /\b(explain|اشرح|وضح|describe)\b/i,
        /\b(fix|repair|أصلح|debug)\b/i,
    ];

    // Check for simple first
    if (simplePatterns.some(p => p.test(msg)) && length < 50) {
        return {
            level: 'simple',
            confidence: 0.9,
            reasoning: 'Short greeting or basic question'
        };
    }

    // Check for complex
    const complexMatches = complexPatterns.filter(p => p.test(msg)).length;
    if (complexMatches >= 2 || (complexMatches >= 1 && length > 200)) {
        return {
            level: 'complex',
            confidence: 0.85,
            reasoning: 'Multiple complex keywords or long detailed request'
        };
    }

    // Check for medium
    const mediumMatches = mediumPatterns.filter(p => p.test(msg)).length;
    if (mediumMatches >= 1 || length > 100) {
        return {
            level: 'medium',
            confidence: 0.75,
            reasoning: 'Coding task or moderate complexity request'
        };
    }

    // Default to simple for very short messages
    if (length < 30) {
        return {
            level: 'simple',
            confidence: 0.6,
            reasoning: 'Very short message, likely simple'
        };
    }

    // Default to medium
    return {
        level: 'medium',
        confidence: 0.5,
        reasoning: 'Default classification for moderate length'
    };
}

/**
 * Select the best provider based on complexity and available providers
 */
export function selectAutoProvider(
    message: string,
    availableProviders: {
        pollinations: boolean;
        openrouter: boolean;
        openrouterHasKey: boolean;
        openai: boolean;
        anthropic: boolean;
    }
): string {
    const analysis = analyzeComplexity(message);

    // Simple tasks: Use OpenRouter free or OpenAI
    if (analysis.level === 'simple') {
        if (availableProviders.openrouter) return 'openrouter';
        if (availableProviders.openai) return 'openai';
        return 'auto';
    }

    // Medium tasks: Use OpenRouter free
    if (analysis.level === 'medium') {
        if (availableProviders.openrouter) {
            return 'openrouter';
        }
    }

    // Complex tasks: Use best available paid provider
    if (analysis.level === 'complex') {
        if (availableProviders.openrouter && availableProviders.openrouterHasKey) {
            return 'openrouter'; // Will use premium model
        }
        if (availableProviders.anthropic) {
            return 'anthropic';
        }
        if (availableProviders.openai) {
            return 'openai';
        }
        // Fallback to OpenRouter free
        if (availableProviders.openrouter) {
            return 'openrouter';
        }
    }

    // Ultimate fallback
    return 'auto';
}

import { WebSocketServer, WebSocket } from 'ws';
import type { Server } from 'http';
import { attachBrowserWss } from './browser/wsHub';

let liveWssRef: WebSocketServer | null = null;
let browserWssRef: WebSocketServer | null = null;
let liveSeq = 0;

export type LiveEventType =
  | 'step_started'
  | 'step_progress'
  | 'step_done'
  | 'step_failed'
  | 'evidence_added'
  | 'artifact_created'
  | 'approval_required'
  | 'approval_result'
  | 'run_finished'
  | 'run_completed'
  | 'text'
  | 'thought'       // NEW: AI reasoning step
  | 'diff'          // NEW: File diff for viewer
  | 'preview_ready' // NEW: Preview URL available
  | 'screenshot'    // NEW: Screenshot captured
  | (string & {});

export interface LiveEvent {
  type: LiveEventType;
  data: any;
  id?: string;
  runId?: string;
  seq?: number;
  ts?: number;
}

export function attachWebSocket(server: Server) {
  liveWssRef = new WebSocketServer({ noServer: true });
  browserWssRef = new WebSocketServer({ noServer: true });
  attachBrowserWss(browserWssRef);

  liveWssRef.on('connection', (ws) => {
    console.log('[WS] Client connected to liveWss');
    (ws as any).isAlive = true;
    ws.on('pong', () => {
      (ws as any).isAlive = true;
    });
    const pingTimer = setInterval(() => {
      if (ws.readyState !== WebSocket.OPEN) {
        clearInterval(pingTimer);
        return;
      }
      if ((ws as any).isAlive === false) {
        clearInterval(pingTimer);
        try { ws.terminate(); } catch { }
        return;
      }
      (ws as any).isAlive = false;
      try { ws.ping(); } catch { }
    }, 30000);
    ws.on('message', (data) => {
      try {
        const msg = JSON.parse(data.toString());
        console.log('[WS] Received message:', msg);
        if (msg.type === 'ping') ws.send(JSON.stringify({ type: 'pong' }));

        // Terminal Streaming Handlers
        if (msg.type === 'terminal_input') {
          const { id, data, serverId } = msg;
          if (serverId) {
            Promise.resolve(require('./terminal/ssh-manager')).then(({ sshManager }) => {
              if (!sshManager.isConnected(serverId)) {
                // Trigger shell creation if not connected? 
                // Usually connected via REST call first, but we ensure shell exists
              }
              sshManager.requestShell(serverId, id).then(() => {
                sshManager.sendInput(id, data);
              });
            });
          } else {
            Promise.resolve(require('./tools/definitions/TaskInteractionTools')).then(({ terminals }) => {
              const term = terminals.get(id);
              if (term) term.pty.write(data);
            });
          }
        }
        if (msg.type === 'terminal_resize') {
          const { id, cols, rows, serverId } = msg;
          if (serverId) {
            Promise.resolve(require('./terminal/ssh-manager')).then(({ sshManager }) => {
              sshManager.resizeShell(id, cols, rows);
            });
          } else {
            Promise.resolve(require('./tools/definitions/TaskInteractionTools')).then(({ terminals }) => {
              const term = terminals.get(id);
              if (term) term.pty.resize(cols, rows);
            });
          }
        }
      } catch (e) {
        // ignore non-json
      }
    });
    ws.on('close', () => {
      clearInterval(pingTimer);
    });
  });

  server.on('upgrade', (req: any, socket: any, head: any) => {
    const reject = (status: number, message: string) => {
      try {
        socket.write(
          `HTTP/1.1 ${status} ${message}\r\n` +
          'Connection: close\r\n' +
          'Content-Type: text/plain\r\n' +
          `Content-Length: ${Buffer.byteLength(message)}\r\n` +
          '\r\n' +
          message
        );
      } catch { }
      try { socket.destroy(); } catch { }
    };

    let url: URL;
    try {
      url = new URL(req.url, `http://${req.headers.host}`);
    } catch {
      return reject(400, 'Bad Request');
    }

    if (url.pathname === '/ws' || url.pathname === '/ws/' || url.pathname === '/api/ws' || url.pathname === '/api/ws/') {
      console.log('[WS] Upgrading ws connection at:', url.pathname);
      if (!liveWssRef) return reject(503, 'Service Unavailable');
      liveWssRef.handleUpgrade(req, socket, head, (ws) => {
        console.log('[WS] Connection established');
        liveWssRef?.emit('connection', ws, req);
      });
      return;
    }
    if (url.pathname === '/ws/browser') {
      if (!browserWssRef) return reject(503, 'Service Unavailable');
      browserWssRef.handleUpgrade(req, socket, head, (ws) => {
        browserWssRef?.emit('connection', ws, req);
      });
      return;
    }

    return reject(404, 'Not Found');
  });
}

export function broadcast(
  event: LiveEvent | { type: string; data: any; id?: string; runId?: string; seq?: number; ts?: number }
) {
  if (!liveWssRef) return;
  const normalized: LiveEvent = {
    ...(event as any),
    ts: typeof (event as any)?.ts === 'number' ? (event as any).ts : Date.now(),
    seq: typeof (event as any)?.seq === 'number' ? (event as any).seq : (liveSeq += 1),
    runId:
      typeof (event as any)?.runId === 'string'
        ? (event as any).runId
        : typeof (event as any)?.data?.runId === 'string'
          ? (event as any).data.runId
          : undefined,
  };
  const payload = JSON.stringify(normalized);
  liveWssRef.clients.forEach((client: WebSocket) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(payload);
    }
  });
}

