/**
 * Analyzes request complexity to determine the best AI provider
 */

export type Complexity = 'simple' | 'medium' | 'complex';

interface ComplexityScore {
    level: Complexity;
    confidence: number;
    reasoning: string;
}

/**
 * Analyze message complexity
 */
export function analyzeComplexity(message: string): ComplexityScore {
    const msg = message.toLowerCase();
    const length = message.length;

    // Simple patterns (greetings, basic questions)
    const simplePatterns = [
        /^(hi|hello|hey|مرحبا|السلام|اهلا)\b/i,
        /^(how are you|كيف حالك|شلونك)/i,
        /^(thanks|شكرا|thank you)/i,
        /^(yes|no|نعم|لا|ok|okay|حسنا)\s*$/i,
    ];

    // Complex patterns (architecture, analysis, planning)
    const complexPatterns = [
        /\b(architect|design|structure|معمارية|تصميم|هيكل)\b/i,
        /\b(analyze|analysis|تحليل|audit|review|مراجعة)\b/i,
        /\b(implement|build|create.*system|إنشاء.*نظام|بناء)\b/i,
        /\b(optimize|performance|أداء|تحسين|تطوير)\b/i,
        /\b(database|schema|migration|قاعدة\s+بيانات)\b/i,
        /\b(security|authentication|أمان|مصادقة)\b/i,
    ];

    // Medium patterns (coding, translation, moderate tasks)
    const mediumPatterns = [
        /\b(write.*function|اكتب.*دالة|code|كود|برمجة)\b/i,
        /\b(translate|ترجم|convert|حول)\b/i,
        /\b(explain|اشرح|وضح|describe)\b/i,
        /\b(fix|repair|أصلح|debug)\b/i,
    ];

    // Check for simple first
    if (simplePatterns.some(p => p.test(msg)) && length < 50) {
        return {
            level: 'simple',
            confidence: 0.9,
            reasoning: 'Short greeting or basic question'
        };
    }

    // Check for complex
    const complexMatches = complexPatterns.filter(p => p.test(msg)).length;
    if (complexMatches >= 2 || (complexMatches >= 1 && length > 200)) {
        return {
            level: 'complex',
            confidence: 0.85,
            reasoning: 'Multiple complex keywords or long detailed request'
        };
    }

    // Check for medium
    const mediumMatches = mediumPatterns.filter(p => p.test(msg)).length;
    if (mediumMatches >= 1 || length > 100) {
        return {
            level: 'medium',
            confidence: 0.75,
            reasoning: 'Coding task or moderate complexity request'
        };
    }

    // Default to simple for very short messages
    if (length < 30) {
        return {
            level: 'simple',
            confidence: 0.6,
            reasoning: 'Very short message, likely simple'
        };
    }

    // Default to medium
    return {
        level: 'medium',
        confidence: 0.5,
        reasoning: 'Default classification for moderate length'
    };
}

/**
 * Select the best provider based on complexity and available providers
 */
export function selectAutoProvider(
    message: string,
    availableProviders: {
        pollinations: boolean;
        openrouter: boolean;
        openrouterHasKey: boolean;
        openai: boolean;
        anthropic: boolean;
    }
): string {
    const analysis = analyzeComplexity(message);

    // Simple tasks: Use OpenRouter free or OpenAI
    if (analysis.level === 'simple') {
        if (availableProviders.openrouter) return 'openrouter';
        if (availableProviders.openai) return 'openai';
        return 'auto';
    }

    // Medium tasks: Use OpenRouter free
    if (analysis.level === 'medium') {
        if (availableProviders.openrouter) {
            return 'openrouter';
        }
    }

    // Complex tasks: Use best available paid provider
    if (analysis.level === 'complex') {
        if (availableProviders.openrouter && availableProviders.openrouterHasKey) {
            return 'openrouter'; // Will use premium model
        }
        if (availableProviders.anthropic) {
            return 'anthropic';
        }
        if (availableProviders.openai) {
            return 'openai';
        }
        // Fallback to OpenRouter free
        if (availableProviders.openrouter) {
            return 'openrouter';
        }
    }

    // Ultimate fallback
    return 'auto';
}

/**
 * Formats a number using Euro-style formatting (dots for thousands, commas for decimals).
 * Example: 125867.45 -> 125.867,45
 */
export const formatNumber = (value: number | string): string => {
    const num = typeof value === 'string' ? parseFloat(value) : value;
    if (isNaN(num)) return '0';

    return num.toLocaleString('de-DE', {
        minimumFractionDigits: 0,
        maximumFractionDigits: 2,
    });
};

/**
 * Formats a number as Euro-style currency.
 */
export const formatCurrency = (value: number | string, currency = 'USD'): string => {
    const num = typeof value === 'string' ? parseFloat(value) : value;
    if (isNaN(num)) return '$0';

    const formatted = formatNumber(num);
    return currency === 'USD' ? `$${formatted}` : `${formatted} €`; // Simple implementation for this use case
};

import { create } from 'zustand';
import { api } from '../services/apiClient';

export interface Session {
  id: string;
  title: string;
  lastSnippet?: string;
  isPinned?: boolean;
  folderId?: string;
  terminalState?: string;
}

export interface Folder {
  _id: string;
  name: string;
}

// Helper to ensure token exists (for dev environment auto-creation)
// We keep this specific logic here or move to auth service? 
// For now, keep it local or use apiClient helper if extended.
// But apiClient uses localStorage. 
// This ensureToken logic actually *fetches* a dev token if none exists.
async function ensureToken() {
  const existing = localStorage.getItem('token');
  if (existing) return existing;

  const isLocal = /localhost|127\.0\.0\.1/.test(window.location.hostname);
  if (!isLocal) return null;

  try {
    // We use raw fetch here because api.post would fail with 401/no token logic loop?
    // Actually api.post handles headers. If we call a public endpoint it's fine.
    // But /auth/dev might need special handling. Let's stick to simple fetch for this bootstrap.
    const API_URL = (import.meta as any).env?.VITE_API_URL || 'http://localhost:3000/api';
    const res = await fetch(`${API_URL}/auth/dev`, { method: 'POST' });
    if (!res.ok) return null;
    const data = await res.json().catch(() => ({}));
    const token = typeof data?.token === 'string' ? data.token : '';
    if (token) localStorage.setItem('token', token);
    return token;
  } catch {
    return null;
  }
}

interface SessionState {
  sessions: Session[];
  agentSessions: Session[];
  folders: Folder[];
  selected: string | null;
  agentSelected: string | null;
  loadingStates: Record<string, boolean>;
  loadAllSessions: () => Promise<void>;
  loadFolders: () => Promise<void>;
  createFolder: (name: string) => Promise<void>;
  deleteFolder: (id: string) => Promise<void>;
  deleteSession: (id: string) => Promise<void>;
  setSelected: (id: string | null) => void;
  setAgentSelected: (id: string | null) => void;
}

export const useSessionStore = create<SessionState>((set) => ({
  sessions: [],
  agentSessions: [],
  folders: [],
  selected: null,
  agentSelected: null,
  loadingStates: {},
  setSelected: (id: string | null) => set({ selected: id }),
  setAgentSelected: (id: string | null) => set({ agentSelected: id }),

  loadAllSessions: async () => {
    try {
      const token = await ensureToken();
      if (!token) {
        set({ sessions: [], agentSessions: [] });
        return;
      }
      const data: any = await api.get('/sessions', { kind: 'chat,agent' });
      const rawList = Array.isArray(data) ? data : (data.sessions || []);
      const allSessions = rawList.map((s: any) => ({ ...s, id: s.id || s._id }));

      const chatSessions = allSessions.filter((s: any) => s.kind === 'chat' || !s.kind);
      const agentSessions = allSessions.filter((s: any) => s.kind === 'agent');

      set(state => ({
        sessions: chatSessions,
        agentSessions: agentSessions,
        selected: state.selected || chatSessions[0]?.id || null,
        agentSelected: state.agentSelected || agentSessions[0]?.id || null,
      }));
    } catch (e) {
      console.error('Failed to load sessions', e);
    }
  },

  loadFolders: async () => {
    try {
      const folders: any = await api.get('/folders');
      set({ folders });
    } catch (e) {
      console.error('Failed to load folders', e);
      set({ folders: [] });
    }
  },

  createFolder: async (name: string) => {
    set(state => ({ loadingStates: { ...state.loadingStates, creatingFolder: true } }));
    try {
      await api.post('/folders', { name });
      await useSessionStore.getState().loadFolders();
    } catch (e) {
      console.error(e);
    } finally {
      set(state => ({ loadingStates: { ...state.loadingStates, creatingFolder: false } }));
    }
  },

  deleteFolder: async (id: string) => {
    set(state => ({ loadingStates: { ...state.loadingStates, [`deleting-folder-${id}`]: true } }));
    try {
      await api.delete(`/folders/${id}`);
      await useSessionStore.getState().loadFolders();
      await useSessionStore.getState().loadAllSessions();
    } catch (e) {
      console.error(e);
    } finally {
      set(state => ({ loadingStates: { ...state.loadingStates, [`deleting-folder-${id}`]: false } }));
    }
  },

  deleteSession: async (id: string) => {
    set(state => ({ loadingStates: { ...state.loadingStates, [`deleting-session-${id}`]: true } }));
    try {
      await api.delete(`/sessions/${id}`);
      await useSessionStore.getState().loadAllSessions();
    } catch (e) {
      console.error(e);
    } finally {
      set(state => ({ loadingStates: { ...state.loadingStates, [`deleting-session-${id}`]: false } }));
    }
  },

  deleteAllSessions: async () => {
    set(state => ({ loadingStates: { ...state.loadingStates, deletingAll: true } }));
    try {
      await api.delete('/sessions');
      set({ sessions: [], agentSessions: [], selected: null, agentSelected: null });
    } catch (e) {
      console.error(e);
    } finally {
      set(state => ({ loadingStates: { ...state.loadingStates, deletingAll: false } }));
    }
  },
}));

