                                    type="email"
                                    required
                                    placeholder="Enter email to invite..."
                                    className="flex-1 bg-transparent border-none outline-none text-white placeholder-white/30"
                                    value={inviteEmail}
                                    onChange={e => setInviteEmail(e.target.value)}
                                />
                                <select
