                            </form>

                            {/* Member List */}
                            <div className="space-y-2">
                                {members.map(m => (
                                    <div key={m._id} className="flex items-center justify-between p-3 rounded-lg hover:bg-white/5 transition-colors border border-transparent hover:border-white/10">
