export default function Login() {
    const { t, i18n } = useTranslation();
    const nav = useNavigate();

    const emailRef = useRef<HTMLInputElement>(null);
    const passRef = useRef<HTMLInputElement>(null);

    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [showPassword, setShowPassword] = useState(false);
    const [health, setHealth] = useState<{ status: string, db: number } | null>(null);

    // Health Check on mount
    useEffect(() => {
        const check = async () => {
            try {
                const pureApi = API.replace(/\/api$/, '');
                const res = await fetch(`${pureApi}/health`);
                const data = await res.json();
                setHealth(data);
            } catch (e) {
                setHealth({ status: 'FAIL', db: 0 });
            }
        };
        check();
    }, []);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        const email = emailRef.current?.value || '';
        const password = passRef.current?.value || '';

        if (!email || !password) {
            setError(t('login_error_missing'));
            return;
        }

        setError(null);
        setLoading(true);

        try {
            const res = await fetch(`${API}/auth/login`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept-Language': i18n.language || 'en'
                },
                body: JSON.stringify({ email, password }),
            });

            const data = await res.json().catch(() => ({}));

            if (!res.ok) {
                throw new Error(data.error || t('login_error_auth'));
            }

            localStorage.setItem('token', data.token);
            nav('/joe');
        } catch (err: any) {
            setError(err.message);
            setLoading(false);
