import React, { useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { useTranslation } from 'react-i18next';

interface ThinkingProcessProps {
    thought: {
        title?: string;
        content: string;
        active: boolean; // Is it currently streaming?
    };
}

export function ThinkingProcess({ thought }: ThinkingProcessProps) {
    const { t } = useTranslation();
    const contentRef = useRef<HTMLDivElement>(null);
    const [displayedContent, setDisplayedContent] = useState('');

    // High-speed word-by-word streaming for Elite 6.0 (Ghost Mode)
    useEffect(() => {
        if (!thought.content || !thought.active) {
            setDisplayedContent(thought.content || '');
            return;
        }

        const words = (thought.content || '').split(' ');
        let current = '';
        let i = 0;

        const interval = setInterval(() => {
            if (i >= words.length) {
                clearInterval(interval);
                setDisplayedContent(thought.content || '');
                return;
            }
            current += (i === 0 ? '' : ' ') + words[i];
            setDisplayedContent(current);
            i++;
        }, 5); // HYPER-SPEED: 5ms for Ghost/Whisper effect

        return () => clearInterval(interval);
    }, [thought.content, thought.active]);

    // Auto-scroll to bottom of thought when active
    useEffect(() => {
        if (thought.active && contentRef.current) {
            contentRef.current.scrollTop = contentRef.current.scrollHeight;
        }
    }, [displayedContent, thought.active]);

    // Extract title (kept for internal logic but visually hidden in Ghost Mode)
    const displayTitle = thought.title || (() => {
        const content = thought.content || '';
        const match = content.match(/\*\*([^*]+)\*\*/);
        return match ? match[1].trim() : t('thinkingDefaultTitle');
    })();

    // Remove title from content for display
    const cleanContent = thought.title
        ? displayedContent
        : (displayedContent || '').replace(/\*\*([^*]+)\*\*/, '').trim();

    return (
        <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            style={{
                background: 'transparent',
                border: 'none',
                borderRadius: '8px',
                overflow: 'hidden',
                marginTop: '8px',
                marginBottom: '4px',
                position: 'relative'
            }}
        >
            <div
                ref={contentRef}
                style={{
                    padding: '4px 12px',
                    maxHeight: '120px',
                    overflowY: 'auto',
                    fontSize: '11px',
                    fontWeight: 300,
                    fontStyle: 'italic',
                    lineHeight: '1.5',
                    color: 'rgba(255, 255, 255, 0.45)', // Ghostly white
                    fontFamily: 'var(--font-sans)',
                    whiteSpace: 'pre-wrap',
                    scrollbarWidth: 'none',
                    filter: 'blur(0.4px)', // The Phantom Blur
                    transition: 'all 0.3s ease'
                }}
            >
                {cleanContent}
            </div>
        </motion.div>
    );
}

import { useEffect, useRef, useState } from 'react';
import { Terminal } from 'xterm';
import { FitAddon } from 'xterm-addon-fit';
import 'xterm/css/xterm.css';
import { SocketService } from '../services/socket';
import { API_URL } from '../config';
import { Maximize2, Minimize2, Plus, Terminal as TerminalIcon, X } from 'lucide-react';

interface TerminalPanelProps {
    onClose?: () => void;
}

export default function TerminalPanel({ onClose }: TerminalPanelProps) {
    const containerRef = useRef<HTMLDivElement>(null);
    const termRef = useRef<Terminal | null>(null);
    const fitAddonRef = useRef<FitAddon | null>(null);
    const [terminalId, setTerminalId] = useState<string>('default');
    const [isReady, setIsReady] = useState(false);
    const [isMinimized, setIsMinimized] = useState(false);

    // Initialize Terminal
    useEffect(() => {
        if (!containerRef.current) return;

        const term = new Terminal({
            cursorBlink: true,
            fontFamily: '"JetBrains Mono", "Fira Code", monospace',
            fontSize: 14,
            theme: {
                background: '#0f172a', // Slate-900
                foreground: '#e2e8f0', // Slate-200
                cursor: '#38bdf8',
                selectionBackground: 'rgba(56, 189, 248, 0.3)',
            },
            allowProposedApi: true
        });

        const fitAddon = new FitAddon();
        term.loadAddon(fitAddon);
        term.open(containerRef.current);
        fitAddon.fit();

        termRef.current = term;
        fitAddonRef.current = fitAddon;

        // Initialize connection
        const initTerminal = async () => {
            const token = localStorage.getItem('token');
            try {
                await fetch(`${API_URL}/tools/terminal_manager/execute`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Bearer ${token}`
                    },
                    body: JSON.stringify({
                        action: 'create',
                        id: terminalId,
                        shell: 'bash',
                        cols: 80,
                        rows: 30
                    })
                });
                setIsReady(true);
                term.writeln('\x1b[1;32m✓ Joe Shell Ready\x1b[0m');
            } catch (e) {
                term.writeln('\x1b[1;31m✗ Connection Failed\x1b[0m');
            }
        };
        initTerminal();

        // Handle Input
        term.onData((data) => {
            SocketService.send({
                type: 'terminal_input',
                id: terminalId,
                data
            });
        });

        // Handle Resize with Debounce and Observer (Flattened)
        if (containerRef.current && termRef.current && fitAddonRef.current) {
            const performFit = () => {
                if (!fitAddonRef.current) return;
                try {
                    fitAddonRef.current.fit();
                    const dims = fitAddonRef.current.proposeDimensions();
                    if (dims && dims.cols && dims.rows) {
                        SocketService.send({
                            type: 'terminal_resize',
                            id: terminalId,
                            cols: dims.cols,
                            rows: dims.rows
                        });
                    }
                } catch (e) {
                    console.error('Terminal fit error:', e);
                }
            };

            const resizeObserver = new ResizeObserver(() => {
                requestAnimationFrame(() => performFit());
            });

            resizeObserver.observe(containerRef.current);

            // Also fit after transition ends
            const transitionTimeout = setTimeout(performFit, 350);

            // Add cleanup to the main effect's return
            const originalCleanup = () => {
                term.dispose();
            };

            // Override return to include observer cleanup
            return () => {
                resizeObserver.disconnect();
                clearTimeout(transitionTimeout);
                originalCleanup();
            };
        }

        return () => {
            term.dispose();
        };
    }, [terminalId]);

    // Handle Incoming Data
    useEffect(() => {
        const unsub = SocketService.subscribe((msg: any) => {
            if (msg.type === 'terminal_output' && msg.id === terminalId) {
                termRef.current?.write(msg.data);
            }
        });
        return () => { unsub(); };
    }, [terminalId]);

    // Ensure fit on visibility change
    useEffect(() => {
        if (!isMinimized && fitAddonRef.current && isReady) {
            const t = setTimeout(() => fitAddonRef.current?.fit(), 100);
            return () => clearTimeout(t);
        }
    }, [isMinimized, isReady]);

    return (
        <div className={`fixed bottom-4 right-4 bg-slate-900 border border-slate-700 rounded-lg shadow-2xl overflow-hidden transition-all duration-300 flex flex-col ${isMinimized ? 'w-64 h-12' : 'w-[800px] h-[500px]'}`} style={{ zIndex: 50 }}>
            {/* Header */}
            <div className="flex items-center justify-between px-4 py-2 bg-slate-800 border-b border-slate-700 select-none cursor-move">
                <div className="flex items-center gap-2 text-slate-300">
                    <TerminalIcon size={16} className="text-blue-400" />
                    <span className="text-sm font-medium">System Terminal</span>
                    <span className={`w-2 h-2 rounded-full ${isReady ? 'bg-green-500' : 'bg-yellow-500'}`} />
                </div>
                <div className="flex items-center gap-2">
                    {!isMinimized && (
                        <button
                            onClick={() => {
                                const id = prompt('Enter Terminal ID:', terminalId);
                                if (id && id !== terminalId) {
                                    termRef.current?.reset();
                                    setTerminalId(id);
                                }
                            }}
                            className="p-1 hover:bg-slate-700 rounded text-slate-400"
                            title="New Session"
                        >
                            <Plus size={14} />
                        </button>
                    )}
                    <button
                        onClick={() => setIsMinimized(!isMinimized)}
                        className="p-1 hover:bg-slate-700 rounded text-slate-400"
                    >
                        {isMinimized ? <Maximize2 size={14} /> : <Minimize2 size={14} />}
                    </button>
                    <button
                        onClick={onClose}
                        className="p-1 hover:bg-red-900/50 hover:text-red-400 rounded text-slate-400"
                    >
                        <X size={14} />
                    </button>
                </div>
            </div>

            {/* Terminal Container */}
            {!isMinimized && (
                <div className="flex-1 p-2 bg-[#0f172a] overflow-hidden relative">
                    <div ref={containerRef} className="h-full w-full" />
                </div>
            )}
        </div>
    );
}

import { X, Play, Clock } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

interface QueuedTask {
    id: string;
    message: string;
    timestamp: Date;
    priority: 'high' | 'normal';
    relatedToCurrentTask: boolean;
}

interface TaskQueueProps {
    tasks: QueuedTask[];
    onRemove: (id: string) => void;
    onExecute: (id: string) => void;
}

export default function TaskQueue({ tasks, onRemove, onExecute }: TaskQueueProps) {
    if (tasks.length === 0) return null;

    return (
        <motion.div
            initial={{ y: 100, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: 100, opacity: 0 }}
            className="fixed bottom-0 left-0 right-0 z-50 bg-gradient-to-t from-slate-950 via-slate-900/95 to-transparent backdrop-blur-xl border-t border-white/10 shadow-[0_-8px_32px_rgba(0,0,0,0.4)]"
            style={{ maxHeight: '200px' }}
        >
            <div className="max-w-7xl mx-auto px-4 py-3">
                {/* Header */}
                <div className="flex items-center gap-2 mb-2">
                    <Clock size={16} className="text-yellow-500" />
                    <span className="text-xs font-bold text-slate-300 uppercase tracking-wider">
                        Queued Tasks ({tasks.length})
                    </span>
                </div>

                {/* Tasks List */}
                <div className="flex flex-col gap-2 overflow-y-auto" style={{ maxHeight: '140px' }}>
                    <AnimatePresence>
                        {tasks.map((task, index) => (
                            <motion.div
                                key={task.id}
                                initial={{ x: -20, opacity: 0 }}
                                animate={{ x: 0, opacity: 1 }}
                                exit={{ x: 20, opacity: 0 }}
                                transition={{ delay: index * 0.05 }}
                                className="flex items-center gap-3 px-4 py-2.5 rounded-xl bg-gradient-to-r from-slate-800/60 to-slate-800/40 border border-white/5 hover:border-yellow-500/30 transition-all group"
                            >
                                {/* Priority Indicator */}
                                <div
                                    className={`w-2 h-2 rounded-full shrink-0 ${task.priority === 'high'
                                            ? 'bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.6)]'
                                            : 'bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.6)]'
                                        }`}
                                />

                                {/* Task Message */}
                                <div className="flex-1 min-w-0">
                                    <p className="text-sm text-slate-200 truncate font-medium">
                                        {task.message}
                                    </p>
                                    <p className="text-[10px] text-slate-500 mt-0.5">
                                        {new Date(task.timestamp).toLocaleTimeString('ar-SA', {
                                            hour: '2-digit',
                                            minute: '2-digit',
                                        })}
                                    </p>
                                </div>

                                {/* Actions */}
                                <div className="flex items-center gap-1 shrink-0">
                                    {/* Execute Button */}
                                    <button
                                        onClick={() => onExecute(task.id)}
                                        className="p-2 rounded-lg bg-yellow-500/10 hover:bg-yellow-500/20 text-yellow-500 border border-yellow-500/20 hover:border-yellow-500/40 transition-all active:scale-90"
                                        title="تنفيذ الآن"
                                    >
                                        <Play size={14} fill="currentColor" />
                                    </button>

                                    {/* Remove Button */}
                                    <button
                                        onClick={() => onRemove(task.id)}
                                        className="p-2 rounded-lg bg-red-500/10 hover:bg-red-500/20 text-red-500 border border-red-500/20 hover:border-red-500/40 transition-all active:scale-90"
                                        title="حذف"
                                    >
                                        <X size={14} />
                                    </button>
                                </div>
                            </motion.div>
                        ))}
                    </AnimatePresence>
                </div>
            </div>
        </motion.div>
    );
}

import { useState, useEffect } from 'react';
import { Heart, MessageCircle, Send, Camera, MoreHorizontal, Loader2, Image as ImageIcon, Share2 } from 'lucide-react';
import { API_URL } from '../config';

interface Comment {
    userId: string;
    text: string;
    ts: number;
}

interface Post {
    id: string;
    userId: string;
    caption?: string;
    imageHref?: string;
    likes: number;
    comments: Comment[];
    ts: number;
}

export default function SocialPanel() {
    const [posts, setPosts] = useState<Post[]>([]);
    const [loading, setLoading] = useState(false);
    const [uploading, setUploading] = useState(false);
    const [commentText, setCommentText] = useState<Record<string, string>>({});

    const loadFeed = async () => {
        setLoading(true);
        const token = localStorage.getItem('token');
        try {
            const res = await fetch(`${API_URL}/insta/feed?limit=50`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            if (res.ok) {
                const data = await res.json();
                setPosts(data.posts || []);
            }
        } catch { }
        setLoading(false);
    };

    useEffect(() => {
        loadFeed();
    }, []);

    const handleCreatePost = async () => {
        const fileInput = document.createElement('input');
        fileInput.type = 'file';
        fileInput.accept = 'image/*';
        fileInput.onchange = async (e) => {
            const file = (e.target as HTMLInputElement).files?.[0];
            if (!file) return;

            const caption = prompt('Write a caption...');
            if (caption === null) return;

            setUploading(true);
            const formData = new FormData();
            formData.append('image', file);
            formData.append('caption', caption);

            const token = localStorage.getItem('token');
            try {
                await fetch(`${API_URL}/insta/post`, {
                    method: 'POST',
                    headers: { Authorization: `Bearer ${token}` },
                    body: formData
                });
                loadFeed();
            } catch {
                alert('Failed to upload');
            }
            setUploading(false);
        };
        fileInput.click();
    };

    const handleLike = async (postId: string) => {
        const token = localStorage.getItem('token');
        try {
            await fetch(`${API_URL}/insta/like`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
                body: JSON.stringify({ postId })
            });
            // Optimistic update
            setPosts(posts.map(p => p.id === postId ? { ...p, likes: p.likes + 1 } : p));
        } catch { }
    };

    const handleComment = async (postId: string) => {
        const text = commentText[postId]?.trim();
        if (!text) return;

        const token = localStorage.getItem('token');
        try {
            await fetch(`${API_URL}/insta/comment`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
                body: JSON.stringify({ postId, text })
            });
            loadFeed();
            setCommentText(prev => ({ ...prev, [postId]: '' }));
        } catch { }
    };

    return (
        <div className="flex flex-col h-full bg-[#0f1117] text-white overflow-hidden">
            {/* Header */}
            <div className="p-4 border-b border-white/5 flex items-center justify-between sticky top-0 bg-[#0f1117]/80 backdrop-blur z-10 glass-panel border-r-0">
                <h2 className="font-bold text-xl tracking-tight bg-gradient-to-r from-pink-500 to-purple-500 bg-clip-text text-transparent">InstaJoe</h2>
                <button
                    onClick={handleCreatePost}
                    disabled={uploading}
                    className="premium-btn"
                >
                    {uploading ? <Loader2 size={18} className="animate-spin" /> : <Camera size={18} />}
                    <span className="text-sm">New Post</span>
                </button>
            </div>

            {/* Feed */}
            <div className="flex-1 overflow-y-auto p-4 space-y-6">
                {loading && posts.length === 0 && (
                    <div className="flex justify-center p-10"><Loader2 className="animate-spin opacity-50 text-pink-500" size={32} /></div>
                )}

                {!loading && posts.length === 0 && (
                    <div className="text-center py-20 opacity-50">
                        <div className="w-16 h-16 bg-white/5 rounded-full flex items-center justify-center mx-auto mb-4">
                            <Camera size={24} className="opacity-50" />
                        </div>
                        <p>No posts yet.<br />Be the first to share!</p>
                    </div>
                )}

                {posts.map(post => (
                    <div key={post.id} className="social-card">
                        <div className="p-3 flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-yellow-400 via-pink-500 to-purple-600 p-[2px]">
                                    <div className="w-full h-full rounded-full bg-[#0f1117] flex items-center justify-center text-sm font-bold border border-white/10">
                                        {post.userId.substring(0, 2).toUpperCase()}
                                    </div>
                                </div>
                                <div>
                                    <div className="font-semibold text-sm">{post.userId}</div>
                                    <div className="text-[10px] opacity-40">{new Date(post.ts).toLocaleDateString()}</div>
                                </div>
                            </div>
                            <button className="text-white/30 hover:text-white transition-colors">
                                <MoreHorizontal size={20} />
                            </button>
                        </div>

                        {post.imageHref ? (
                            <div className="aspect-square bg-white/5 relative overflow-hidden group">
                                <img
                                    src={`${API_URL}${post.imageHref}`}
                                    alt={post.caption}
                                    className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                                    onError={(e) => (e.currentTarget.src = 'https://via.placeholder.com/400?text=Error+Loading+Image')}
                                />
                            </div>
                        ) : (
                            <div className="aspect-video bg-white/5 flex items-center justify-center text-white/20">
                                <ImageIcon size={48} />
                            </div>
                        )}

                        <div className="p-4">
                            <div className="flex items-center gap-4 mb-4">
                                <button onClick={() => handleLike(post.id)} className="social-action-btn hover:text-pink-500 hover:bg-pink-500/10">
                                    <Heart size={22} className={post.likes > 0 ? "fill-pink-500 text-pink-500" : ""} />
                                    {post.likes > 0 && <span className="text-sm font-semibold">{post.likes}</span>}
                                </button>
                                <button className="social-action-btn hover:text-blue-500 hover:bg-blue-500/10">
                                    <MessageCircle size={22} />
                                    <span className="text-sm font-semibold">{post.comments.length}</span>
                                </button>
                                <button className="social-action-btn hover:text-green-500 hover:bg-green-500/10 ml-auto">
                                    <Share2 size={22} />
                                </button>
                            </div>

                            {post.caption && (
                                <div className="text-sm mb-3">
                                    <span className="font-semibold mr-2">{post.userId}</span>
                                    <span className="opacity-80 leading-relaxed">{post.caption}</span>
                                </div>
                            )}

                            {post.comments.length > 0 && (
                                <div className="space-y-2 mb-4 pl-3 border-l-2 border-white/10">
                                    {post.comments.slice(-3).map((c, i) => (
                                        <div key={i} className="text-xs opacity-70">
                                            <span className="font-semibold mr-2 text-white/90">{c.userId}</span>
                                            {c.text}
                                        </div>
                                    ))}
                                    {post.comments.length > 3 && (
                                        <div className="text-xs opacity-50 cursor-pointer hover:opacity-100 mt-1">
                                            View all {post.comments.length} comments
                                        </div>
                                    )}
                                </div>
                            )}

                            <div className="flex items-center gap-2 mt-4">
                                <div className="flex-1 relative">
                                    <input
                                        type="text"
                                        placeholder="Add a comment..."
                                        value={commentText[post.id] || ''}
                                        onChange={(e) => setCommentText({ ...commentText, [post.id]: e.target.value })}
                                        onKeyDown={(e) => e.key === 'Enter' && handleComment(post.id)}
                                        className="w-full bg-white/5 border border-white/10 rounded-full px-4 py-2 text-sm focus:outline-none focus:border-white/30 transition-colors placeholder:text-white/20"
                                    />
                                    <button
                                        className={`absolute right-2 top-1/2 -translate-y-1/2 p-1.5 rounded-full transition-all ${commentText[post.id] ? 'text-blue-500 bg-blue-500/10 hover:bg-blue-500/20' : 'text-white/10'}`}
                                        onClick={() => handleComment(post.id)}
                                        disabled={!commentText[post.id]}
                                    >
                                        <Send size={14} />
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

