import { useState, useEffect } from 'react';
import { Package, Download, Trash2, Search, ExternalLink, Loader2, Layers, CheckCircle, AlertCircle } from 'lucide-react';
import { API_URL } from '../config';

interface Pkg {
    name: string;
    version: string;
    description?: string;
}

export default function PackageManager() {
    const [installed, setInstalled] = useState<Pkg[]>([]);
    const [searchResults, setSearchResults] = useState<Pkg[]>([]);
    const [query, setQuery] = useState('');
    const [loading, setLoading] = useState(false);
    const [searching, setSearching] = useState(false);
    const [installing, setInstalling] = useState<string | null>(null);
    const [activeTab, setActiveTab] = useState<'installed' | 'browse'>('installed');

    const loadInstalled = async () => {
        setLoading(true);
        const token = localStorage.getItem('token');
        try {
            const res = await fetch(`${API_URL}/packages/installed`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            if (res.ok) {
                const data = await res.json();
                setInstalled(data.packages || []);
            }
        } catch { }
        setLoading(false);
    };

    useEffect(() => {
        loadInstalled();
    }, []);

    const searchPackages = async () => {
        if (!query.trim()) return;
        setSearching(true);
        const token = localStorage.getItem('token');
        try {
            const res = await fetch(`${API_URL}/packages/search?q=${encodeURIComponent(query)}`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            if (res.ok) {
                const data = await res.json();
                setSearchResults(data.results || []);
            }
        } catch { }
        setSearching(false);
    };

    const handleAction = async (name: string, action: 'install' | 'uninstall') => {
        setInstalling(name);
        const token = localStorage.getItem('token');
        try {
            await fetch(`${API_URL}/packages/${action}`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
                body: JSON.stringify({ name })
            });
            await loadInstalled();
            if (action === 'install') setActiveTab('installed');
            alert(`Successfully ${action}ed ${name}`);
        } catch {
            alert(`Failed to ${action} ${name}`);
        }
        setInstalling(null);
    };

    useEffect(() => {
        const timer = setTimeout(() => {
            if (query && activeTab === 'browse') searchPackages();
        }, 600);
        return () => clearTimeout(timer);
    }, [query, activeTab]);

    return (
        <div className="flex flex-col h-full bg-[#0f1117] text-white font-sans">
            {/* Header */}
            <div className="p-4 border-b border-white/5 sticky top-0 bg-[#0f1117]/80 backdrop-blur z-10 glass-panel border-r-0">
                <div className="flex items-center gap-3 mb-4">
                    <div className="w-8 h-8 rounded-lg bg-blue-500/20 text-blue-500 flex items-center justify-center border border-blue-500/20">
                        <Package size={18} />
                    </div>
                    <div>
                        <h2 className="font-bold text-sm tracking-wide">PACKAGE MANAGER</h2>
                    </div>
                </div>

                <div className="flex p-1 bg-white/5 rounded-xl border border-white/5">
                    <button
                        onClick={() => setActiveTab('installed')}
                        className={`flex-1 py-2 text-xs font-semibold rounded-lg transition-all ${activeTab === 'installed' ? 'bg-white/10 text-white shadow-sm' : 'text-white/40 hover:text-white/70'}`}
                    >
                        Installed ({installed.length})
                    </button>
                    <button
                        onClick={() => setActiveTab('browse')}
                        className={`flex-1 py-2 text-xs font-semibold rounded-lg transition-all ${activeTab === 'browse' ? 'bg-white/10 text-white shadow-sm' : 'text-white/40 hover:text-white/70'}`}
                    >
                        Browse Registry
                    </button>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4">
                {activeTab === 'browse' && (
                    <div className="mb-6 relative">
                        <input
                            type="text"
                            placeholder="Search npm..."
                            value={query}
                            onChange={(e) => setQuery(e.target.value)}
                            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 pl-10 text-sm focus:outline-none focus:border-blue-500/50 focus:bg-white/10 transition-colors"
                        />
                        <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-white/30" />
                        {searching && <Loader2 size={16} className="absolute right-3 top-1/2 -translate-y-1/2 animate-spin text-blue-500" />}
                    </div>
                )}

                <div className="space-y-3">
                    {activeTab === 'installed' ? (
                        <>
                            {loading ? (
                                <div className="flex justify-center py-10"><Loader2 className="animate-spin opacity-50" /></div>
                            ) : installed.length === 0 ? (
                                <div className="text-center py-10 opacity-50">No packages installed</div>
                            ) : (
                                installed.map((pkg, i) => (
                                    <div key={i} className="group bg-white/5 hover:bg-white/[0.07] border border-white/5 hover:border-white/10 rounded-xl p-4 transition-all">
                                        <div className="flex justify-between items-start mb-2">
                                            <div>
                                                <div className="font-bold text-sm text-white/90 flex items-center gap-2">
                                                    {pkg.name}
                                                    <span className="text-[10px] bg-blue-500/10 text-blue-400 px-1.5 py-0.5 rounded border border-blue-500/20">{pkg.version}</span>
                                                </div>
                                                {pkg.description && <div className="text-xs text-white/50 mt-1 line-clamp-1">{pkg.description}</div>}
                                            </div>
                                            <button
                                                onClick={() => { if (confirm(`Uninstall ${pkg.name}?`)) handleAction(pkg.name, 'uninstall'); }}
                                                disabled={!!installing}
                                                className="p-2 bg-red-500/10 text-red-400 rounded-lg hover:bg-red-500 hover:text-white transition-colors opacity-0 group-hover:opacity-100"
                                                title="Uninstall"
                                            >
                                                {installing === pkg.name ? <Loader2 size={14} className="animate-spin" /> : <Trash2 size={14} />}
                                            </button>
                                        </div>
                                    </div>
                                ))
                            )}
                        </>
                    ) : (
                        <>
                            {query && searchResults.length === 0 && !searching && (
                                <div className="text-center py-10 opacity-50">No results found</div>
                            )}

                            {!query && (
                                <div className="flex flex-col items-center justify-center py-12 text-white/30 gap-3">
                                    <Search size={48} className="opacity-20" />
                                    <p className="text-sm">Search the npm registry...</p>
                                </div>
                            )}

                            {searchResults.map((pkg, i) => {
                                const installedVer = installed.find(p => p.name === pkg.name)?.version;
                                return (
                                    <div key={i} className="group bg-white/5 hover:bg-white/[0.07] border border-white/5 hover:border-white/10 rounded-xl p-4 transition-all">
                                        <div className="flex justify-between items-start gap-4">
                                            <div className="flex-1 min-w-0">
                                                <div className="flex items-center gap-2 mb-1">
                                                    <span className="font-bold text-sm text-white/90 truncate">{pkg.name}</span>
                                                    {installedVer && <CheckCircle size={12} className="text-green-500" />}
                                                </div>
                                                {pkg.description && <div className="text-xs text-white/50 line-clamp-2">{pkg.description}</div>}
                                                <div className="flex items-center gap-3 mt-3 text-xs text-white/30">
                                                    <span className="flex items-center gap-1"><Layers size={10} /> {pkg.version}</span>
                                                </div>
                                            </div>
                                            <button
                                                onClick={() => handleAction(pkg.name, 'install')}
                                                disabled={!!installing || !!installedVer}
                                                className={`px-3 py-1.5 rounded-lg text-xs font-semibold flex items-center gap-2 transition-all ${installedVer
                                                        ? 'bg-green-500/10 text-green-500 cursor-default'
                                                        : 'bg-white/10 hover:bg-blue-500 hover:text-white text-white/70'
                                                    }`}
                                            >
                                                {installing === pkg.name ? (
                                                    <Loader2 size={12} className="animate-spin" />
                                                ) : installedVer ? (
                                                    'Installed'
                                                ) : (
                                                    <>
                                                        <Download size={12} /> Install
                                                    </>
                                                )}
                                            </button>
                                        </div>
                                    </div>
                                );
                            })}
                        </>
                    )}
                </div>
            </div>
        </div>
    );
}

import { useEffect, useMemo, useRef, useState } from 'react';
import { API_URL } from '../config';

type WsEvent =
  | { type: 'stream_frame'; ts: number; jpegBase64: string; w: number; h: number }
  | { type: 'cursor_move'; ts: number; x: number; y: number }
  | { type: 'highlight_boxes'; ts: number; boxes: Array<{ x: number; y: number; width: number; height: number; label?: string }> }
  | { type: 'action_sent' | 'action_ack' | 'action_done' | 'action_error'; ts: number; actionId: string; actionType: string; summary?: string; reason?: string; error?: string }
  | { type: 'step_start'; stepId: string; name: string; ts: number }
  | { type: 'step_done'; stepId: string; name: string; ts: number; data?: any }
  | { type: 'step_error'; stepId: string; name: string; ts: number; reason: string; message: string; data?: any }
  | { type: 'goto_blocked'; stepId: string; ts: number; url: string; reason: string; message: string }
  | { type: 'final_report'; ts: number; ok: boolean; summary: string; steps: any[]; evidence: any[] }
  | { type: 'final_success'; ts: number; summary: string }
  | { type: 'final_failed'; ts: number; summary: string; reason: string }
  | { type: 'debug_snapshot'; ts: number; compiledPlanJson: any; actionsJson: any; actionCount: number; stopReason: string };

type Props = { sessionId: string; showBoxes?: boolean };

export default function ModernBrowserStream({ sessionId, showBoxes = true }: Props) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const cursorElRef = useRef<HTMLDivElement>(null);
  const [status, setStatus] = useState<'connecting' | 'connected' | 'error'>('connecting');
  const [w, setW] = useState(1280);
  const [h, setH] = useState(720);
  const [boxes, setBoxes] = useState<Array<{ x: number; y: number; width: number; height: number; label?: string }>>([]);
  const [lastStep, setLastStep] = useState<string>('');
  const [final, setFinal] = useState<{ ok: boolean; summary: string } | null>(null);
  const [debug, setDebug] = useState<{ compiledPlanJson: any; actionsJson: any; actionCount: number; stopReason: string } | null>(null);
  const [busy, setBusy] = useState(false);
  const [queueLen, setQueueLen] = useState(0);
  const [detailsOpen, setDetailsOpen] = useState(false);
  const [actions, setActions] = useState<
    Array<{ ts: number; type: 'action_sent' | 'action_ack' | 'action_done' | 'action_error'; actionId: string; actionType: string; summary?: string; reason?: string; error?: string }>
  >([]);

  const boxesRef = useRef(boxes);
  const actionsRef = useRef(actions);
  const pendingTypeRef = useRef('');
  const flushTimerRef = useRef<number | null>(null);
  const lastSendAtRef = useRef(0);
  const sendQueueRef = useRef<any[][]>([]);
  const inFlightRef = useRef(false);
  const abortRef = useRef<AbortController | null>(null);
  const cancelSeqRef = useRef(0);
  const viewSizeRef = useRef({ w: 1, h: 1 });
  const frameSizeRef = useRef({ w: 1280, h: 720 });
  const cursorTargetNormRef = useRef<{ x: number; y: number } | null>(null);
  const cursorPosPxRef = useRef<{ x: number; y: number } | null>(null);
  const rafRef = useRef<number | null>(null);
  const lastRafTsRef = useRef<number>(0);
  const cursorVisibleRef = useRef(false);
  const scrollAccRef = useRef(0);
  const scrollTimerRef = useRef<number | null>(null);

  useEffect(() => {
    boxesRef.current = boxes;
  }, [boxes]);
  useEffect(() => {
    actionsRef.current = actions;
  }, [actions]);
  useEffect(() => {
    frameSizeRef.current = { w, h };
  }, [w, h]);

  useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const update = () => {
      const rect = el.getBoundingClientRect();
      viewSizeRef.current = { w: Math.max(1, rect.width), h: Math.max(1, rect.height) };
    };
    update();
    const ro = new ResizeObserver(() => update());
    ro.observe(el);
    return () => {
      try {
        ro.disconnect();
      } catch { }
    };
  }, []);

  useEffect(() => {
    const tick = (ts: number) => {
      const el = cursorElRef.current;
      const targetNorm = cursorTargetNormRef.current;
      if (!el || !targetNorm) {
        if (el && cursorVisibleRef.current) {
          el.style.opacity = '0';
          cursorVisibleRef.current = false;
        }
        rafRef.current = window.requestAnimationFrame(tick);
        return;
      }

      const dtMs = lastRafTsRef.current ? ts - lastRafTsRef.current : 16;
      lastRafTsRef.current = ts;
      const dt = Math.max(0.001, Math.min(0.06, dtMs / 1000));
      const view = viewSizeRef.current;

      const tx = targetNorm.x * view.w;
      const ty = targetNorm.y * view.h;
      const cur = cursorPosPxRef.current || { x: tx, y: ty };

      const follow = 1 - Math.pow(0.0001, dt);
      const nx = cur.x + (tx - cur.x) * follow;
      const ny = cur.y + (ty - cur.y) * follow;
      cursorPosPxRef.current = { x: nx, y: ny };

      el.style.transform = `translate3d(${nx}px, ${ny}px, 0) translate(-2px, -2px)`;
      if (!cursorVisibleRef.current) {
        el.style.opacity = '1';
        cursorVisibleRef.current = true;
      }

      rafRef.current = window.requestAnimationFrame(tick);
    };
    rafRef.current = window.requestAnimationFrame(tick);
    return () => {
      if (rafRef.current) {
        try {
          window.cancelAnimationFrame(rafRef.current);
        } catch { }
      }
      rafRef.current = null;
    };
  }, []);

  const sendActionsNow = async (acts: any[], signal: AbortSignal) => {
    const sid = String(sessionId || '').trim();
    if (!sid) return;
    const token = (() => {
      try {
        return localStorage.getItem('token');
      } catch {
        return null;
      }
    })();
    try {
      await fetch(`${API_URL}/tools/browser_run/execute`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify({ sessionId: sid, actions: acts }),
        signal,
      });
    } catch { }
  };

  const syncQueueLen = () => {
    setQueueLen(sendQueueRef.current.length);
  };

  const cancelPending = () => {
    cancelSeqRef.current += 1;
    if (flushTimerRef.current) {
      window.clearTimeout(flushTimerRef.current);
      flushTimerRef.current = null;
    }
    pendingTypeRef.current = '';
    sendQueueRef.current.length = 0;
    syncQueueLen();
    try {
      abortRef.current?.abort();
    } catch { }
  };

  useEffect(() => {
    const toggleDetails = (ev: Event) => {
      const detail = (ev as CustomEvent)?.detail || {};
      const open = (detail as any)?.open;
      if (typeof open === 'boolean') {
        setDetailsOpen(open);
        return;
      }
      setDetailsOpen((v) => !v);
    };
    const openDetails = () => setDetailsOpen(true);
    const closeDetails = () => setDetailsOpen(false);
    const cancel = () => cancelPending();

    window.addEventListener('browser:details_toggle', toggleDetails as any);
    window.addEventListener('browser:details_open', openDetails as any);
    window.addEventListener('browser:details_close', closeDetails as any);
    window.addEventListener('browser:cancel_pending', cancel as any);
    return () => {
      window.removeEventListener('browser:details_toggle', toggleDetails as any);
      window.removeEventListener('browser:details_open', openDetails as any);
      window.removeEventListener('browser:details_close', closeDetails as any);
      window.removeEventListener('browser:cancel_pending', cancel as any);
    };
  }, []);

  const drainQueue = async () => {
    if (inFlightRef.current) return;
    inFlightRef.current = true;
    setBusy(true);
    const mySeq = cancelSeqRef.current;
    try {
      while (sendQueueRef.current.length) {
        if (cancelSeqRef.current !== mySeq) break;
        const next = sendQueueRef.current.shift();
        syncQueueLen();
        if (!next) continue;
        const controller = new AbortController();
        abortRef.current = controller;
        try {
          lastSendAtRef.current = Date.now();
          await sendActionsNow(next, controller.signal);
        } catch {
          if (controller.signal.aborted) break;
        } finally {
          if (abortRef.current === controller) abortRef.current = null;
        }
      }
    } finally {
      inFlightRef.current = false;
      setBusy(false);
      syncQueueLen();
    }
  };

  const enqueueActions = (acts: any[]) => {
    if (!Array.isArray(acts) || acts.length === 0) return;
    sendQueueRef.current.push(acts);
    syncQueueLen();
    void drainQueue();
  };

  const flushType = async () => {
    if (flushTimerRef.current) {
      window.clearTimeout(flushTimerRef.current);
      flushTimerRef.current = null;
    }
    const text = pendingTypeRef.current;
    pendingTypeRef.current = '';
    if (!text) return;
    enqueueActions([{ type: 'type', text }]);
  };

  const wsUrl = useMemo(() => {
    const base = API_URL.replace(/^http/i, 'ws');
    const u = new URL('/ws/browser', base);
    u.searchParams.set('sessionId', sessionId);
    if (window.location.protocol === 'https:' && u.protocol === 'ws:') u.protocol = 'wss:';
    return u.toString();
  }, [sessionId]);

  useEffect(() => {
    const ws = new WebSocket(wsUrl);
    setStatus('connecting');
    ws.onopen = () => setStatus('connected');
    ws.onerror = () => setStatus('error');
    ws.onmessage = (ev) => {
      let msg: WsEvent | null = null;
      try {
        const parsed = JSON.parse(String(ev.data || ''));
        const candidate =
          parsed && typeof parsed === 'object'
            ? (typeof (parsed as any)?.type === 'string'
              ? parsed
              : typeof (parsed as any)?.event?.type === 'string'
                ? (parsed as any).event
                : typeof (parsed as any)?.data?.type === 'string'
                  ? (parsed as any).data
                  : null)
            : null;
        msg = candidate as any;
      } catch {
        msg = null;
      }
      if (!msg) return;
      if (msg.type === 'stream_frame') {
        setW(msg.w);
        setH(msg.h);
        const img = new Image();
        img.onload = () => {
          const canvas = canvasRef.current;
          if (!canvas) return;
          const ctx = canvas.getContext('2d');
          if (!ctx) return;
          canvas.width = msg.w;
          canvas.height = msg.h;
          ctx.drawImage(img, 0, 0, msg.w, msg.h);
          const curBoxes = showBoxes ? (boxesRef.current || []) : [];
          if (showBoxes && curBoxes.length) {
            ctx.save();
            ctx.strokeStyle = 'rgba(239, 68, 68, 0.9)';
            ctx.lineWidth = 2;
            for (const b of curBoxes) {
              ctx.strokeRect(b.x, b.y, b.width, b.height);
            }
            ctx.restore();
          }
        };
        img.src = `data:image/jpeg;base64,${msg.jpegBase64}`;
        return;
      }
      if (msg.type === 'cursor_move') {
        const fs = frameSizeRef.current;
        const nx = fs.w ? msg.x / fs.w : 0;
        const ny = fs.h ? msg.y / fs.h : 0;
        cursorTargetNormRef.current = { x: Math.max(0, Math.min(1, nx)), y: Math.max(0, Math.min(1, ny)) };
        return;
      }
      if (msg.type === 'highlight_boxes') {
        setBoxes(showBoxes ? (msg.boxes || []) : []);
        return;
      }
      if (msg.type === 'action_sent' || msg.type === 'action_ack' || msg.type === 'action_done' || msg.type === 'action_error') {
        setActions((prev) => {
          const next = prev.concat([
            {
              ts: msg.ts,
              type: msg.type,
              actionId: msg.actionId,
              actionType: msg.actionType,
              summary: msg.summary,
              reason: msg.reason,
              error: msg.error,
            },
          ]);
          return next.length > 60 ? next.slice(next.length - 60) : next;
        });
        return;
      }
      if (msg.type === 'step_start') {
        setLastStep(`${msg.stepId}: ${msg.name}`);
        return;
      }
      if (msg.type === 'final_report') {
        setFinal({ ok: msg.ok, summary: msg.summary });
        return;
      }
      if (msg.type === 'final_success') {
        setFinal({ ok: true, summary: msg.summary });
        return;
      }
      if (msg.type === 'final_failed') {
        const reason = String(msg.reason || '').trim();
        const s = reason ? `${msg.summary}\n${reason}` : msg.summary;
        setFinal({ ok: false, summary: s });
        return;
      }
      if ((msg as any).type === 'session_status') {
        try {
          const d = (msg as any);
          const det = { url: String(d?.url || ''), sessionId: String(d?.sessionId || '') };
          window.dispatchEvent(new CustomEvent('browser:session_status', { detail: det }));
        } catch { }
        return;
      }
      if (msg.type === 'debug_snapshot') {
        setDebug({
          compiledPlanJson: (msg as any).compiledPlanJson,
          actionsJson: (msg as any).actionsJson,
          actionCount: Number((msg as any).actionCount || 0),
          stopReason: String((msg as any).stopReason || ''),
        });
        return;
      }
    };
    return () => {
      try { ws.close(); } catch { }
    };
  }, [wsUrl]);

  return (
    <div style={{ width: '100%', height: '100%', overflow: 'hidden', background: '#0b0b0b', display: 'flex', flexDirection: 'column' }}>
      <div ref={rootRef} style={{ flex: 1, minHeight: 0, position: 'relative', overflow: 'hidden' }}>
        <style>{`
        .browser-cursor {
          width: 26px;
          height: 26px;
          position: absolute;
          top: 0;
          left: 0;
          opacity: 0;
          pointer-events: none;
          z-index: 6;
          will-change: transform, opacity;
        }
        .browser-cursor-svg {
          width: 100%;
          height: 100%;
          display: block;
          filter: drop-shadow(0 2px 6px rgba(0, 0, 0, 0.38)) drop-shadow(0 0 1px rgba(255, 255, 255, 0.22));
        }
        .browser-cursor-path {
          fill: rgba(255, 255, 255, 0.98);
          stroke: rgba(0, 0, 0, 0.9);
          stroke-width: 2.25;
          stroke-linejoin: round;
          stroke-linecap: round;
        }
      `}</style>
        <canvas
          ref={canvasRef}
          tabIndex={0}
          onMouseDown={(e) => {
            const canvas = canvasRef.current;
            if (!canvas) return;
            try {
              canvas.focus();
            } catch { }
            const rect = canvas.getBoundingClientRect();
            const rx = (e.clientX - rect.left) / Math.max(1, rect.width);
            const ry = (e.clientY - rect.top) / Math.max(1, rect.height);
            const x = Math.max(0, Math.min(w - 1, Math.round(rx * w)));
            const y = Math.max(0, Math.min(h - 1, Math.round(ry * h)));
            void flushType().finally(() => {
              enqueueActions([{ type: 'click', x, y }]);
            });
          }}
          onKeyDown={(e) => {
            const key = String((e as any)?.key || '');
            if (key === 'Escape') {
              e.preventDefault();
              cancelPending();
              return;
            }
            if (key === 'Enter') {
              e.preventDefault();
              void flushType().finally(() => {
                enqueueActions([{ type: 'type', text: '\n' }]);
              });
              return;
            }
            if (key === 'Tab') {
              e.preventDefault();
              void flushType().finally(() => {
                enqueueActions([{ type: 'type', text: '\t' }]);
              });
              return;
            }
            if (key.length === 1) {
              e.preventDefault();
              pendingTypeRef.current += key;
              const dt = Date.now() - lastSendAtRef.current;
              const delay = dt > 700 ? 30 : 90;
              if (flushTimerRef.current) window.clearTimeout(flushTimerRef.current);
              flushTimerRef.current = window.setTimeout(() => void flushType(), delay);
            }
          }}
          onWheel={(e) => {
            // Check if we are scrolling vertically
            const dy = e.deltaY;
            if (!dy) return;

            // Accumulate delta
            scrollAccRef.current += dy;

            // Schedule flush if not scheduled
            if (!scrollTimerRef.current) {
              scrollTimerRef.current = window.setTimeout(() => {
                const total = scrollAccRef.current;
                scrollAccRef.current = 0;
                scrollTimerRef.current = null;

                if (Math.abs(total) < 20) return; // Minimum threshold
                const direction = total > 0 ? 'down' : 'up';
                // Apply a multiplier for better feel, or use raw pixels if browser matches mapping
                const amount = Math.min(2000, Math.floor(Math.abs(total)));

                enqueueActions([{ type: 'scroll', direction, amount }]);
              }, 150); // 150ms throttle window
            }
          }}
          style={{ width: '100%', height: '100%', display: 'block', outline: 'none' }}
        />
        <div ref={cursorElRef} className="browser-cursor" aria-hidden="true">
          <svg className="browser-cursor-svg" viewBox="0 0 24 24">
            <path className="browser-cursor-path" d="M3.5 2.2 L3.5 19.6 L8.6 15.4 L11.5 22.1 L14.3 20.8 L11.3 14.0 L18.7 14.0 Z" />
          </svg>
        </div>
      </div>
      <div style={{ padding: 10, borderTop: '1px solid rgba(255,255,255,0.08)', background: 'rgba(0,0,0,0.35)' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10 }}>
          <div style={{ color: '#fff', fontSize: 12, opacity: 0.95, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
            {status} · {w}×{h} {lastStep ? `· ${lastStep}` : ''} {busy ? `· busy` : ''} {queueLen ? `· queue=${queueLen}` : ''}
          </div>
          <div style={{ display: 'flex', gap: 8, alignItems: 'center', flex: '0 0 auto' }}>
            {busy || queueLen ? (
              <button
                onClick={() => cancelPending()}
                style={{
                  padding: '6px 10px',
                  borderRadius: 10,
                  border: '1px solid rgba(255,255,255,0.15)',
                  background: 'rgba(239,68,68,0.25)',
                  color: '#fff',
                  fontSize: 12,
                  cursor: 'pointer',
                }}
              >
                إلغاء
              </button>
            ) : null}
            {actions.length || final || debug ? (
              <button
                onClick={() => setDetailsOpen((v) => !v)}
                style={{
                  padding: '6px 10px',
                  borderRadius: 10,
                  border: '1px solid rgba(255,255,255,0.15)',
                  background: detailsOpen ? 'rgba(37, 99, 235, 0.22)' : 'rgba(255,255,255,0.06)',
                  color: '#fff',
                  fontSize: 12,
                  cursor: 'pointer',
                }}
              >
                {detailsOpen ? 'إخفاء السجل' : 'عرض السجل'}
              </button>
            ) : null}
          </div>
        </div>
        {detailsOpen ? (
          <div style={{ marginTop: 10, display: 'flex', gap: 10, alignItems: 'stretch', flexWrap: 'wrap' }}>
            {final ? (
              <div style={{ flex: '1 1 320px', minWidth: 260, padding: '8px 10px', borderRadius: 10, border: '1px solid rgba(255,255,255,0.12)', background: final.ok ? 'rgba(16,185,129,0.16)' : 'rgba(239,68,68,0.16)', color: '#fff', fontSize: 12, whiteSpace: 'pre-wrap' }}>
                {final.summary}
              </div>
            ) : null}
            {actions.length ? (
              <div style={{ flex: '2 1 520px', minWidth: 320, maxHeight: 220, overflow: 'auto', padding: '8px 10px', borderRadius: 10, border: '1px solid rgba(255,255,255,0.12)', background: 'rgba(0,0,0,0.35)', color: '#fff', fontSize: 12, lineHeight: 1.35, whiteSpace: 'pre-wrap' }}>
                {actions
                  .slice(-30)
                  .map((a) => {
                    const label = a.summary ? `${a.actionType} · ${a.summary}` : a.actionType;
                    const tail = a.type === 'action_error' ? ` · ${String(a.reason || a.error || '').slice(0, 160)}` : '';
                    return `${a.type} · ${a.actionId} · ${label}${tail}`;
                  })
                  .join('\n')}
              </div>
            ) : null}
            {debug ? (
              <div style={{ flex: '2 1 520px', minWidth: 320, maxHeight: 220, overflow: 'auto', padding: '8px 10px', borderRadius: 10, border: '1px solid rgba(255,255,255,0.12)', background: 'rgba(0,0,0,0.35)', color: '#fff', fontSize: 12, lineHeight: 1.35, whiteSpace: 'pre-wrap' }}>
                {(() => {
                  const safe = (v: any) => {
                    try {
                      return JSON.stringify(v, null, 2);
                    } catch {
                      return '"[unserializable]"';
                    }
                  };
                  const parts = [
                    `stop_reason=${String(debug.stopReason || '')}`,
                    `action_count=${String(debug.actionCount || 0)}`,
                    `compiled_plan_json=${safe(debug.compiledPlanJson)}`,
                    `actions_json=${safe(debug.actionsJson)}`,
                  ];
                  return parts.join('\n');
                })()}
              </div>
            ) : null}
          </div>
        ) : null}
      </div>
    </div>
  );
}

import { useState, useEffect, useMemo, useRef, Suspense, lazy } from 'react';
import { useTranslation } from 'react-i18next';
import { Search, Brain, Trash2, Edit2, Clock, Share2, Grid, Box } from 'lucide-react';
import { API_URL } from '../config';

// Lazy load the 3D graph to improve initial performance
const ForceGraph3D = lazy(() => import('react-force-graph-3d'));

export default function MemoryPanel({ sessionId }: { sessionId?: string }) {
    const { t } = useTranslation();
    const [items, setItems] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const [search, setSearch] = useState('');
    const [viewMode, setViewMode] = useState<'list' | 'graph'>('list');
    const graphRef = useRef<any>(null);

    const loadMemories = async () => {
        const token = localStorage.getItem('token');
        if (!token) return;
        setLoading(true);
        try {
            const res = await fetch(`${API_URL}/memory`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            if (res.ok) {
                const data = await res.json();
                setItems(data.memories || []);
            } else {
                setItems([]);
            }
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        loadMemories();
    }, [sessionId]);

    const handleDelete = async (id: string) => {
        if (!confirm('Are you sure you want to delete this memory?')) return;
        const token = localStorage.getItem('token');
        try {
            await fetch(`${API_URL}/memory/${id}`, {
                method: 'DELETE',
                headers: { Authorization: `Bearer ${token}` }
            });
            loadMemories();
        } catch { }
    };

    // Prepare Graph Data
    const graphData = useMemo(() => {
        const nodes: any[] = [];
        const links: any[] = [];

        // Central Nodes
        nodes.push({ id: 'ROOT', name: 'Brain', val: 20, color: '#ef4444' });
        nodes.push({ id: 'SESSION', name: 'Current Session', val: 10, color: '#3b82f6' });
        nodes.push({ id: 'PROJECT', name: 'Project', val: 10, color: '#10b981' });

        links.push({ source: 'ROOT', target: 'SESSION' });
        links.push({ source: 'ROOT', target: 'PROJECT' });

        items.forEach(item => {
            const id = item._id;
            const scope = item.scope || 'user';
            const label = item.key || 'Memory';
            const val = 5;

            nodes.push({ id, name: label, val, color: scope === 'session' ? '#60a5fa' : scope === 'project' ? '#34d399' : '#a78bfa', data: item });

            // Link to Scope Hub
            if (scope === 'session') links.push({ source: 'SESSION', target: id });
            else if (scope === 'project') links.push({ source: 'PROJECT', target: id });
            else links.push({ source: 'ROOT', target: id });
        });

        return { nodes, links };
    }, [items]);

    return (
        <div className="memory-panel h-full flex flex-col bg-[#0f1117] text-white/90">
            <div className="p-4 border-b border-white/5 flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <Brain className="text-red-500" size={20} />
                    <h2 className="font-bold text-lg">{t('memory.title', 'Active Memory')}</h2>
                </div>
                <div className="flex bg-white/5 rounded-lg p-1">
                    <button
                        onClick={() => setViewMode('list')}
                        className={`p-1.5 rounded transition-colors ${viewMode === 'list' ? 'bg-white/10 text-white' : 'text-white/40 hover:text-white'}`}
                        title="List View"
                    >
                        <Grid size={16} />
                    </button>
                    <button
                        onClick={() => setViewMode('graph')}
                        className={`p-1.5 rounded transition-colors ${viewMode === 'graph' ? 'bg-white/10 text-white' : 'text-white/40 hover:text-white'}`}
                        title="3D Graph View"
                    >
                        <Box size={16} />
                    </button>
                </div>
            </div>

            {viewMode === 'list' && (
                <div className="p-4 border-b border-white/5">
                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-white/30" size={14} />
                        <input
                            type="text"
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            placeholder={t('memory.searchPlaceholder', 'Search memory...')}
                            className="w-full bg-black/20 text-white border border-white/10 rounded-lg pl-9 pr-3 py-2 text-sm focus:border-red-500/50 outline-none"
                        />
                    </div>
                </div>
            )}

            <div className="flex-1 overflow-hidden relative">
                {viewMode === 'list' ? (
                    <div className="h-full overflow-y-auto p-4 space-y-3">
                        {loading && <div className="text-center py-8 opacity-50">Loading memories...</div>}
                        {!loading && items.length === 0 && (
                            <div className="text-center py-12 text-white/30 text-sm">
                                {t('memory.empty', 'No memories stored yet.')}
                            </div>
                        )}
                        {items
                            .filter(i => !search || JSON.stringify(i).toLowerCase().includes(search.toLowerCase()))
                            .map((item) => (
                                <div key={item._id} className="bg-white/5 p-3 rounded-lg border border-white/5 hover:border-white/10 transition-all group">
                                    <div className="flex justify-between items-start gap-2">
                                        <div>
                                            <div className="flex items-center gap-2 mb-1">
                                                <span className={`w-2 h-2 rounded-full ${item.scope === 'session' ? 'bg-blue-500' : item.scope === 'project' ? 'bg-green-500' : 'bg-purple-500'}`} />
                                                <span className="font-bold text-sm text-white/90">{item.key}</span>
                                            </div>
                                            <p className="text-xs text-white/60 line-clamp-3 font-mono bg-black/20 p-1.5 rounded">
                                                {typeof item.value === 'object' ? JSON.stringify(item.value) : String(item.value)}
                                            </p>
                                        </div>
                                        <button onClick={() => handleDelete(item._id)} className="p-1 text-white/20 hover:text-red-400 transition-colors opacity-0 group-hover:opacity-100">
                                            <Trash2 size={14} />
                                        </button>
                                    </div>
                                    <div className="mt-2 flex items-center gap-2 text-[10px] text-white/30">
                                        <Clock size={10} />
                                        <span>{new Date(item.createdAt).toLocaleDateString()}</span>
                                        <span className="bg-white/10 px-1.5 py-0.5 rounded text-white/50 uppercase">{item.scope}</span>
                                    </div>
                                </div>
                            ))}
                    </div>
                ) : (
                    <div className="h-full w-full bg-black">
                        <Suspense fallback={<div className="flex items-center justify-center h-full text-white/30">Loading 3D Engine...</div>}>
                            <ForceGraph3D
                                ref={graphRef}
                                graphData={graphData}
                                nodeLabel="name"
                                nodeColor="color"
                                nodeVal="val"
                                linkColor={() => '#ffffff20'}
                                linkWidth={1}
                                backgroundColor="#000000"
                                showNavInfo={false}
                                onNodeClick={(node: any) => {
                                    // Focus on node
                                    if (graphRef.current) {
                                        const distance = 40;
                                        const distRatio = 1 + distance / Math.hypot(node.x, node.y, node.z);
                                        graphRef.current.cameraPosition(
                                            { x: node.x * distRatio, y: node.y * distRatio, z: node.z * distRatio },
                                            node,
                                            3000
                                        );
                                    }
                                }}
                            />
                        </Suspense>
                        <div className="absolute bottom-4 right-4 bg-black/80 p-2 rounded text-[10px] text-white/40 pointer-events-none">
                            Left Click: Rotate • Right Click: Pan • Scroll: Zoom • Click Node: Focus
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

