import express from 'express';
import cors from 'cors';
import { chromium, BrowserServer } from 'playwright';

const app = express();
app.use(cors());
app.use(express.json());

const PORT = process.env.PORT || 7070;
const API_KEY = process.env.WORKER_API_KEY;

let browserServer: BrowserServer | null = null;

// Health check
app.get('/health', (req, res) => {
    res.json({ status: 'OK', worker: 'joe-browser-worker', hasServer: !!browserServer });
});

// Start Browser Server
app.post('/browser/start', async (req, res) => {
    // Auth check
    if (API_KEY && req.headers['authorization'] !== `Bearer ${API_KEY}`) {
        return res.status(401).json({ error: 'Unauthorized' });
    }

    try {
        if (browserServer) {
            return res.json({ wsEndpoint: browserServer.wsEndpoint() });
        }

        browserServer = await chromium.launchServer({
            headless: process.env.BROWSER_HEADLESS === 'false' ? false : true,
            port: 5050,
            wsPath: 'ws',
            args: ['--no-sandbox', '--disable-setuid-sandbox']
        });

        console.log('Browser Server started at', browserServer.wsEndpoint());
        res.json({ wsEndpoint: browserServer.wsEndpoint() });
    } catch (e: any) {
        console.error('Failed to start browser server:', e);
        res.status(500).json({ error: e.message });
    }
});

// Stop Browser Server
app.post('/browser/stop', async (req, res) => {
    if (API_KEY && req.headers['authorization'] !== `Bearer ${API_KEY}`) {
        return res.status(401).json({ error: 'Unauthorized' });
    }

    if (browserServer) {
        await browserServer.close();
        browserServer = null;
    }
    res.json({ status: 'stopped' });
});

app.listen(PORT, async () => {
    console.log(`Browser Worker listening on port ${PORT}`);
    // Auto-start browser server
    try {
        browserServer = await chromium.launchServer({
            headless: process.env.BROWSER_HEADLESS === 'false' ? false : true,
            port: 5050,
            wsPath: 'ws',
            host: '0.0.0.0', // Critical for Docker visibility
            args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
        });
        console.log('Browser Server auto-started at', browserServer.wsEndpoint());
    } catch (e) {
        console.error('Failed to auto-start browser server:', e);
    }
});

import { useState, useEffect, useCallback } from 'react';
import { api } from '../services/apiClient';

interface QueuedTask {
    id: string;
    message: string;
    timestamp: Date;
    priority: 'high' | 'normal';
    relatedToCurrentTask: boolean;
    sessionId?: string;
}

interface ContextAnalysis {
    action: 'merge' | 'queue' | 'execute';
    isCorrection: boolean;
    confidence: number;
    reason: string;
}

export function useTaskQueue(sessionId: string | undefined) {
    const [tasks, setTasks] = useState<QueuedTask[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    // Fetch queued tasks
    const fetchTasks = useCallback(async () => {
        if (!sessionId) return;

        try {
            const data: any = await api.get(`/queue/${sessionId}`);
            if (data && data.tasks) {
                setTasks(data.tasks);
            }
        } catch (error) {
            console.error('Error fetching tasks:', error);
        }
    }, [sessionId]);

    // Analyze a new message
    const analyzeMessage = useCallback(async (message: string): Promise<ContextAnalysis | null> => {
        if (!sessionId) return null;

        try {
            const data: any = await api.post('/queue/analyze', { message, sessionId });
            return data as ContextAnalysis;
        } catch (error) {
            console.error('Error analyzing message:', error);
        }

        return null;
    }, [sessionId]);

    // Add task to queue
    const addTask = useCallback(async (
        message: string,
        priority: 'high' | 'normal' = 'normal',
        relatedToCurrentTask = false
    ): Promise<QueuedTask | null> => {
        if (!sessionId) return null;

        try {
            const data: any = await api.post('/queue', {
                message,
                sessionId,
                priority,
                relatedToCurrentTask
            });

            if (data && data.task) {
                await fetchTasks(); // Refresh the list
                return data.task;
            }
        } catch (error) {
            console.error('Error adding task:', error);
        }

        return null;
    }, [sessionId, fetchTasks]);

    // Remove task from queue
    const removeTask = useCallback(async (taskId: string): Promise<boolean> => {
        if (!sessionId) return false;

        try {
            await api.delete(`/queue/${sessionId}/${taskId}`);
            await fetchTasks(); // Refresh the list
            return true;
        } catch (error) {
            console.error('Error removing task:', error);
        }

        return false;
    }, [sessionId, fetchTasks]);

    // Start a queued task
    const startTask = useCallback(async (taskId: string): Promise<boolean> => {
        if (!sessionId) return false;

        try {
            await api.post(`/queue/${sessionId}/start/${taskId}`);
            await fetchTasks(); // Refresh the list
            return true;
        } catch (error) {
            console.error('Error starting task:', error);
        }

        return false;
    }, [sessionId, fetchTasks]);

    // Set current task description
    const setCurrentTask = useCallback(async (description: string): Promise<boolean> => {
        if (!sessionId) return false;

        try {
            await api.post(`/queue/${sessionId}/current`, { description });
            return true;
        } catch (error) {
            console.error('Error setting current task:', error);
            return false;
        }
    }, [sessionId]);

    // Clear current task
    const clearCurrentTask = useCallback(async (): Promise<boolean> => {
        if (!sessionId) return false;

        try {
            await api.delete(`/queue/${sessionId}/current`);
            return true;
        } catch (error) {
            console.error('Error clearing current task:', error);
            return false;
        }
    }, [sessionId]);

    // Auto-fetch tasks on mount and when sessionId changes
    useEffect(() => {
        fetchTasks();
    }, [fetchTasks]);

    return {
        tasks,
        isLoading,
        fetchTasks,
        analyzeMessage,
        addTask,
        removeTask,
        startTask,
        setCurrentTask,
        clearCurrentTask,
    };
}

import { useState } from 'react';
import { api } from '../services/apiClient';
import { useSessionStore } from '../store/sessionStore';
import { useTranslation } from 'react-i18next';

export function useSessionActions() {
    const { loadAllSessions, setSelected, selected } = useSessionStore();
    const { t } = useTranslation();
    const [isCreatingChatSession, setIsCreatingChatSession] = useState(false);

    async function createSession(onSuccess?: () => void) {
        setIsCreatingChatSession(true);
        try {
            const data: any = await api.post('/sessions', { title: t('sidebar.newChat', 'New Chat') });
            const id = String(data?.id || data?._id || '').trim();
            if (!id) return;

            setSelected(id);
            await loadAllSessions();
            onSuccess?.();

        } catch (e) {
            console.error(e);
        } finally {
            setIsCreatingChatSession(false);
        }
    }

    async function moveSessionToFolder(sessionId: string, folderId: string | null) {
        try {
            await api.patch(`/sessions/${sessionId}/move`, { folderId });
            await loadAllSessions();
        } catch (e) { console.error(e); }
    }

    async function mergeSessions(sourceId: string, targetId: string) {
        if (sourceId === targetId) return;
        if (!confirm('Are you sure you want to merge these sessions? This cannot be undone.')) return;
        try {
            const res: any = await api.post('/sessions/merge', { sourceId, targetId });
            if (res.ok) {
                await loadAllSessions();
                if (selected === sourceId) setSelected(targetId);
            }
        } catch (e) { console.error(e); }
    }

    async function deleteAllSessions() {
        if (!confirm('هل أنت متأكد من حذف جميع الجلسات؟ لا يمكن التراجع عن هذا الإجراء.')) return;
        try {
            await api.delete('/sessions');
            await loadAllSessions();
            setSelected(null);
        } catch (e) { console.error(e); }
    }

    async function togglePin(id: string, currentPinned: boolean) {
        try {
            await api.patch(`/sessions/${id}/pin`, { isPinned: !currentPinned });
            await loadAllSessions();
        } catch (e) { console.error(e); }
    }

    return {
        createSession,
        isCreatingChatSession,
        moveSessionToFolder,
        mergeSessions,
        deleteAllSessions,
        togglePin
    };
}

