        run: npm ci
      - name: Start API
        run: |
          node apps/api/src/index.js & echo $! > api.pid
          sleep 2
      - name: Wait for /api/status
        run: |
          ATTEMPTS=0
          until curl -sSf http://localhost:4000/api/status >/tmp/status.json 2>/dev/null || [ $ATTEMPTS -ge 30 ]; do
            ATTEMPTS=$((ATTEMPTS+1))
            echo "waiting ($ATTEMPTS)..."
            sleep 1
          done
          cat /tmp/status.json || true
      - name: Print service status
        run: |
          echo "Service Status:"
          cat /tmp/status.json || echo '{"ok":false}'
      - name: Stop API
        if: always()
        run: |
          PID="$(cat api.pid || echo '')"
          if [ -n "$PID" ]; then
            kill $PID || true
          fi
`.trim());
  }
}

import fs from 'fs';
import path from 'path';

export class Analyst {
  static analyze(rootPath: string) {
    if (!fs.existsSync(rootPath)) {
      return { status: 'error', message: 'Path does not exist' };
    }

    const pkgPath = path.join(rootPath, 'package.json');
    const isNode = fs.existsSync(pkgPath);
    const hasDocker = fs.existsSync(path.join(rootPath, 'Dockerfile')) || fs.existsSync(path.join(rootPath, 'docker-compose.yml'));

    let techStack = [];
    let dependencies: Record<string, string> = {};

    if (isNode) {
      try {
        const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
        dependencies = { ...pkg.dependencies, ...pkg.devDependencies };
        if (dependencies['react']) techStack.push('React');
        if (dependencies['next']) techStack.push('Next.js');
        if (dependencies['express']) techStack.push('Express');
        if (dependencies['vue']) techStack.push('Vue');
        if (dependencies['tailwindcss']) techStack.push('TailwindCSS');
        if (dependencies['typescript']) techStack.push('TypeScript');
      } catch (e) {}
    }

    // Deep structure scan
    const structure = this.scanDir(rootPath, 0, 3);

    return {
      status: 'success',
      type: isNode ? 'Node.js Project' : 'Unknown',
      techStack,
      hasDocker,
      structure,
      suggestions: this.generateSuggestions(techStack, hasDocker)
    };
  }

  private static scanDir(dir: string, depth: number, maxDepth: number): any {
    if (depth > maxDepth) return '...';
    const items = fs.readdirSync(dir, { withFileTypes: true });
    const result: any = {};

    for (const item of items) {
      if (item.name === 'node_modules' || item.name === '.git') continue;
      if (item.isDirectory()) {
        result[item.name] = this.scanDir(path.join(dir, item.name), depth + 1, maxDepth);
      } else {
        result[item.name] = 'file';
      }
    }
    return result;
  }

  private static generateSuggestions(stack: string[], hasDocker: boolean) {
    const suggs = [];
    if (!hasDocker) suggs.push('Consider adding Docker for containerization.');
    if (stack.includes('React') && !stack.includes('tailwindcss')) suggs.push('Consider TailwindCSS for styling.');
    if (!stack.includes('typescript')) suggs.push('Migrating to TypeScript is recommended for better maintainability.');
    return suggs;
  }
}

import fs from 'fs';
import path from 'path';

// A lightweight Vector Store for Deep Memory
// Uses a hybrid TF-IDF + Keyword matching approach for speed and zero-dependency on Python/Heavy Models

interface Document {
    id: string;
    content: string;
    metadata: Record<string, any>;
    embedding?: number[]; // Placeholder if we add real embeddings later
    tokens?: Set<string>; // For TF-IDF/Jaccard
}

export class VectorDbService {
    private documents: Document[] = [];
    private storagePath: string;

    constructor(storageDir: string = '.gemini/memory') {
        this.storagePath = path.resolve(process.cwd(), storageDir);
        if (!fs.existsSync(this.storagePath)) {
            fs.mkdirSync(this.storagePath, { recursive: true });
        }
        this.load();
    }

    private load() {
        const file = path.join(this.storagePath, 'index.json');
        if (fs.existsSync(file)) {
            try {
                const raw = fs.readFileSync(file, 'utf-8');
                this.documents = JSON.parse(raw).map((d: any) => ({
                    ...d,
                    tokens: new Set(d.tokens || [])
                }));
                console.log(`[VectorDB] Loaded ${this.documents.length} documents from memory.`);
            } catch (e) {
                console.error('[VectorDB] Failed to load index:', e);
            }
        }
    }

    private save() {
        const file = path.join(this.storagePath, 'index.json');
        const serializable = this.documents.map(d => ({
            ...d,
            tokens: Array.from(d.tokens || [])
        }));
        fs.writeFileSync(file, JSON.stringify(serializable, null, 2));
    }

    private tokenize(text: string): Set<string> {
        const normalized = text.toLowerCase()
            .replace(/[^a-z0-9_]+/g, ' ')
            .trim();
        const words = normalized.split(/\s+/).filter(w => w.length > 2);
        return new Set(words);
    }

    async addDocument(content: string, metadata: Record<string, any>) {
        // Basic chunking (if content is huge, we should split it, but we assume caller chunks it)
        const doc: Document = {
            id: Math.random().toString(36).substring(7),
            content,
            metadata,
            tokens: this.tokenize(content + ' ' + (metadata.filePath || ''))
        };
        this.documents.push(doc);
        // Auto-save every 50 docs or so? For now, save immediately for safety
        this.save();
    }

    async clear() {
        this.documents = [];
        this.save();
    }

    async search(query: string, limit: number = 5): Promise<{ doc: Document, score: number }[]> {
        const queryTokens = this.tokenize(query);
        if (queryTokens.size === 0) return [];

        const scored = this.documents.map(doc => {
            // Jaccard similarity / Keyword Overlap
            let intersection = 0;
            queryTokens.forEach(t => {
                if (doc.tokens?.has(t)) intersection++;
            });

            const union = (queryTokens.size + (doc.tokens?.size || 0)) - intersection;
            const score = union > 0 ? intersection / union : 0;

            // Bonus for filename matches (if present in metadata)
            const filenameMatch = doc.metadata.filePath &&
                queryTokens.has(path.basename(doc.metadata.filePath).toLowerCase().split('.')[0]);

            return { doc, score: score + (filenameMatch ? 0.3 : 0) };
        });

        return scored
            .filter(s => s.score > 0.05) // Minimum relevance
            .sort((a, b) => b.score - a.score)
            .slice(0, limit);
    }

    getStats() {
        return {
            documentCount: this.documents.length,
            storagePath: this.storagePath
        };
    }
}

export const vectorDb = new VectorDbService();

type PendingToolContext = {
  runId: string;
  name: string;
  input: any;
};

type SecretEntry = {
  value: string;
  expiresAt?: number;
  enc?: {
    alg: 'aes-256-gcm';
    ivB64: string;
    tagB64: string;
  };
};

const sessionSecrets = new Map<string, Map<string, SecretEntry>>();
const pendingToolBySession = new Map<string, PendingToolContext>();
const runConfigBySession = new Map<
  string,
  {
    provider?: string;
    apiKey?: string;
    baseUrl?: string;
    model?: string;
    kind?: 'chat' | 'agent';
    browserSessionId?: string;
    autoApproveAll?: boolean;
    autoApproveSafe?: boolean;
    expiresAt: number;
  }
>();

function nowMs() {
  return Date.now();
}

function getMasterKeyBytes(): Buffer | null {
  const raw = String(process.env.SECRETS_MASTER_KEY || process.env.JWT_SECRET || '').trim();
  if (!raw) return null;
  const crypto = require('crypto') as typeof import('crypto');
  return crypto.createHash('sha256').update(raw, 'utf8').digest();
}

function encrypt(value: string) {
  const key = getMasterKeyBytes();
  if (!key) return null;
  const crypto = require('crypto') as typeof import('crypto');
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
  const c1 = cipher.update(value, 'utf8');
  const c2 = cipher.final();
  const tag = cipher.getAuthTag();
  const buf = Buffer.concat([c1, c2]);
  return { value: buf.toString('base64'), ivB64: iv.toString('base64'), tagB64: tag.toString('base64') };
}

function decrypt(entry: SecretEntry): string | null {
  if (!entry.enc) return entry.value;
  const key = getMasterKeyBytes();
  if (!key) return null;
  const crypto = require('crypto') as typeof import('crypto');
  const iv = Buffer.from(entry.enc.ivB64, 'base64');
  const tag = Buffer.from(entry.enc.tagB64, 'base64');
  const decipher = crypto.createDecipheriv(entry.enc.alg, key, iv);
  decipher.setAuthTag(tag);
  const c1 = decipher.update(Buffer.from(entry.value, 'base64'));
  const c2 = decipher.final();
  return Buffer.concat([c1, c2]).toString('utf8');
}

export async function setUserSecretEncrypted(
  userId: string,
  provider: string,
  key: string,
  value: string
) {
  const uid = String(userId || '').trim();
  const p = String(provider || '').trim();
  const k = String(key || '').trim();
  if (!uid || !p || !k) return;

  const { UserSecret } = require('../models/userSecret');
  const enc = encrypt(String(value ?? ''));
  const doc: any = {
    userId: uid,
    provider: p,
    key: k,
  };
  if (enc) {
    doc.value = enc.value;
    doc.enc = { alg: 'aes-256-gcm', ivB64: enc.ivB64, tagB64: enc.tagB64 };
  } else {
    doc.value = String(value ?? '');
    doc.enc = undefined;
  }
  await UserSecret.findOneAndUpdate({ userId: uid, provider: p, key: k }, { $set: doc }, { upsert: true, new: true });
}

export async function getUserSecret(
  userId: string,
  provider: string,
  key: string
): Promise<string | null> {
  const uid = String(userId || '').trim();
  const p = String(provider || '').trim();
  const k = String(key || '').trim();
  if (!uid || !p || !k) return null;
  const { UserSecret } = require('../models/userSecret');
  const doc: any = await UserSecret.findOne({ userId: uid, provider: p, key: k })
    .select({ value: 1, enc: 1 })
    .lean();
  if (!doc || typeof doc.value !== 'string') return null;
  const entry: any = { value: doc.value };
  if (doc.enc && typeof doc.enc === 'object') {
    entry.enc = {
      alg: doc.enc.alg,
      ivB64: doc.enc.ivB64,
      tagB64: doc.enc.tagB64,
    };
  }
  const plain = decrypt(entry);
  return plain ?? null;
}

function purgeExpired(bucket: Map<string, SecretEntry>) {
  const now = nowMs();
  for (const [k, v] of bucket.entries()) {
    if (typeof v.expiresAt === 'number' && v.expiresAt > 0 && v.expiresAt <= now) bucket.delete(k);
  }
}

export function setSessionSecret(sessionId: string, key: string, value: string) {
  const sid = String(sessionId || '').trim();
  const k = String(key || '').trim();
  if (!sid || !k) return;
  let bucket = sessionSecrets.get(sid);
  if (!bucket) {
    bucket = new Map<string, SecretEntry>();
    sessionSecrets.set(sid, bucket);
  }
  purgeExpired(bucket);
  bucket.set(k, { value });
}

export function getSessionSecret(sessionId: string, key: string): string | null {
  const sid = String(sessionId || '').trim();
  const k = String(key || '').trim();
  if (!sid || !k) return null;
  const bucket = sessionSecrets.get(sid);
  if (!bucket) return null;
  purgeExpired(bucket);
  const entry = bucket.get(k);
  if (!entry) return null;
  if (typeof entry.expiresAt === 'number' && entry.expiresAt > 0 && entry.expiresAt <= nowMs()) {
    bucket.delete(k);
    return null;
  }
  const plain = decrypt(entry);
  return plain ?? null;
}

export function clearSessionSecrets(sessionId: string) {
  const sid = String(sessionId || '').trim();
  if (!sid) return;
  sessionSecrets.delete(sid);
}

export function setSessionSecretEncrypted(sessionId: string, key: string, value: string, ttlSeconds?: number) {
  const sid = String(sessionId || '').trim();
  const k = String(key || '').trim();
  if (!sid || !k) return null;
  let bucket = sessionSecrets.get(sid);
  if (!bucket) {
    bucket = new Map<string, any>();
    sessionSecrets.set(sid, bucket);
  }
  purgeExpired(bucket as any);

  const ttl = typeof ttlSeconds === 'number' && Number.isFinite(ttlSeconds) && ttlSeconds > 0 ? ttlSeconds : undefined;
  const expiresAt = ttl ? nowMs() + ttl * 1000 : undefined;

  const enc = encrypt(String(value ?? ''));
  if (enc) {
    bucket.set(k, { value: enc.value, expiresAt, enc: { alg: 'aes-256-gcm', ivB64: enc.ivB64, tagB64: enc.tagB64 } });
  } else {
    bucket.set(k, { value: String(value ?? ''), expiresAt });
  }
  return expiresAt ?? null;
}

export function setPendingTool(sessionId: string, ctx: PendingToolContext) {
  const sid = String(sessionId || '').trim();
  if (!sid) return;
  pendingToolBySession.set(sid, ctx);
}

export function popPendingTool(sessionId: string): PendingToolContext | null {
  const sid = String(sessionId || '').trim();
  if (!sid) return null;
  const ctx = pendingToolBySession.get(sid) || null;
  pendingToolBySession.delete(sid);
  return ctx;
}

export function setSessionRunConfig(
  sessionId: string,
  cfg: {
    provider?: string;
    apiKey?: string;
    baseUrl?: string;
    model?: string;
    kind?: 'chat' | 'agent';
    browserSessionId?: string;
    autoApproveAll?: boolean;
    autoApproveSafe?: boolean;
    ttlSeconds?: number;
  }
) {
  const sid = String(sessionId || '').trim();
  if (!sid) return;
  const ttlSeconds =
    typeof cfg.ttlSeconds === 'number' && Number.isFinite(cfg.ttlSeconds) && cfg.ttlSeconds > 0
      ? cfg.ttlSeconds
      : 15 * 60;
  runConfigBySession.set(sid, {
    provider: cfg.provider,
    apiKey: cfg.apiKey,
    baseUrl: cfg.baseUrl,
    model: cfg.model,
    kind: cfg.kind,
    browserSessionId: cfg.browserSessionId,
    autoApproveAll: cfg.autoApproveAll,
    autoApproveSafe: cfg.autoApproveSafe,
    expiresAt: nowMs() + ttlSeconds * 1000,
  });
}

export function getSessionRunConfig(sessionId: string) {
  const sid = String(sessionId || '').trim();
  if (!sid) return null;
  const cur = runConfigBySession.get(sid) || null;
  if (!cur) return null;
  if (typeof cur.expiresAt === 'number' && cur.expiresAt > 0 && cur.expiresAt <= nowMs()) {
    runConfigBySession.delete(sid);
    return null;
  }
  return cur;
}

import { MemoryItem } from '../models/memoryItem';
import { ConversationSummary } from '../models/conversationSummary';
import OpenAI from 'openai';

const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY || 'dummy',
  baseURL: process.env.OPENAI_BASE_URL,
});

// In-memory message buffer per user (for summarization)
const userMessageBuffers: Map<string, { messages: string[], sessionId?: string }> = new Map();
const SUMMARY_THRESHOLD = 10; // Summarize every 10 messages

export class MemoryService {
  /**
   * Track a message for later summarization
   * Each user has their own isolated buffer
   */
  static async trackMessage(userId: string, message: string, role: 'user' | 'assistant', sessionId?: string, options?: any) {
    if (!userId || !message) return;

    // Initialize buffer for this user if not exists
    if (!userMessageBuffers.has(userId)) {
      userMessageBuffers.set(userId, { messages: [], sessionId });
    }

    const buffer = userMessageBuffers.get(userId)!;
    buffer.messages.push(`${role === 'user' ? '👤' : '🤖'}: ${message.substring(0, 500)}`);
    buffer.sessionId = sessionId;

    // Check if we should summarize
    if (buffer.messages.length >= SUMMARY_THRESHOLD) {
      await this.summarizeAndSave(userId, buffer.messages, sessionId, options);
      buffer.messages = []; // Clear buffer after summarization
    }
  }

  /**
   * Summarize messages and save to database
   * Completely isolated per userId
   */
  static async summarizeAndSave(userId: string, messages: string[], sessionId?: string, options?: any) {
    if (!userId || messages.length === 0) return;

    try {
      let client = openai;
      if (options?.apiKey) {
        client = new OpenAI({
          apiKey: options.apiKey,
          baseURL: options.baseUrl || process.env.OPENAI_BASE_URL,
        });
      }

      const conversationText = messages.join('\n');

      const completion = await client.chat.completions.create({
        model: options?.model || 'gpt-4o-mini', // Use cheaper model for summaries
        messages: [
          {
            role: 'system',
            content: `أنت ملخص محادثات. قم بتلخيص المحادثة التالية في 2-3 جمل قصيرة.
استخرج أيضاً المواضيع الرئيسية (3-5 كلمات).
أجب بصيغة JSON: { "summary": "...", "topics": ["...", "..."] }`
          },
          { role: 'user', content: conversationText }
        ],
        response_format: { type: 'json_object' },
        max_tokens: 300
      });

      const content = completion.choices[0].message.content;
      if (!content) return;

      const result = JSON.parse(content);

      // Save summary - completely isolated by userId
      await ConversationSummary.create({
        userId,
        sessionId,
        summary: result.summary || 'ملخص غير متوفر',
        messageCount: messages.length,
        topics: result.topics || []
      });

      console.log(`[Memory] 📝 Saved summary for user ${userId}: ${messages.length} messages`);

    } catch (err) {
      console.error('[Memory] Summarization failed:', err);
    }
  }

  /**
   * Get persistent context for a user
   * Returns last 3 summaries - completely isolated per user
   */
  static async getPersistentContext(userId: string, limit = 3): Promise<string> {
    if (!userId) return '';

    try {
      const summaries = await ConversationSummary.find({ userId })
        .sort({ createdAt: -1 })
        .limit(limit)
        .lean();

      if (summaries.length === 0) return '';

      const contextParts = summaries.reverse().map((s, i) =>
        `[جلسة سابقة ${i + 1}]: ${s.summary}`
      );

      return '\n\n📚 **ذاكرة المحادثات السابقة:**\n' + contextParts.join('\n');
    } catch (err) {
      console.error('[Memory] Context retrieval failed:', err);
      return '';
    }
  }

  /**
   * Force flush any pending messages for a user
   * Useful when session ends
   */
  static async flushUserBuffer(userId: string, options?: any) {
    const buffer = userMessageBuffers.get(userId);
    if (buffer && buffer.messages.length > 0) {
      await this.summarizeAndSave(userId, buffer.messages, buffer.sessionId, options);
      userMessageBuffers.delete(userId);
    }
  }

  static async searchMemories(userId: string, text: string, limit = 5): Promise<string[]> {
    if (!userId) return [];

    const normalized = String(text || '')
      .normalize('NFKC')
      .toLowerCase()
      .replace(/[^\p{L}\p{N}\s]/gu, ' ');

    const keywords = normalized
      .split(/\s+/)
      .map(w => w.trim())
      .filter(w => w.length >= 2)
      .slice(0, 12);

    if (keywords.length === 0) {
      const items = await MemoryItem.find({ userId, scope: 'user' })
        .sort({ updatedAt: -1 })
        .limit(limit);
      return items.map(item => `${item.key}: ${typeof item.value === 'string' ? item.value : JSON.stringify(item.value)}`);
    }

    const escaped = keywords.map(k => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
    const regex = new RegExp(escaped.join('|'), 'i');

    const items = await MemoryItem.find({
      userId,
      scope: 'user',
      $or: [
        { key: { $regex: regex } },
        { value: { $regex: regex } }
      ]
    })
      .sort({ updatedAt: -1 })
      .limit(limit);

    if (items.length === 0) {
      const fallback = await MemoryItem.find({ userId, scope: 'user' })
        .sort({ updatedAt: -1 })
        .limit(limit);
      return fallback.map(item => `${item.key}: ${typeof item.value === 'string' ? item.value : JSON.stringify(item.value)}`);
    }

    return items.map(item => `${item.key}: ${typeof item.value === 'string' ? item.value : JSON.stringify(item.value)}`);
  }

  static async extractAndSaveMemories(userId: string, userText: string, options?: any) {
    if (!userId || !userText) return;

    // Also track for summarization
    await this.trackMessage(userId, userText, 'user', options?.sessionId, options);

    try {
      let client = openai;
      if (options?.apiKey) {
        client = new OpenAI({
          apiKey: options.apiKey,
          baseURL: options.baseUrl || process.env.OPENAI_BASE_URL,
        });
      }

      const completion = await client.chat.completions.create({
        model: options?.model || 'gpt-4o',
        messages: [
          {
            role: 'system',
            content: `You are a Memory Extractor. Your job is to extract permanent user facts from the conversation.

Rules:
- Extract ONLY facts that are useful to remember for future conversations (e.g., name, preferences, tech stack, job, specific instructions).
- Ignore transient info (e.g., "write a function", "fix this bug").
- Output a JSON object with a "facts" array. Each fact has "key" (short category) and "value" (the fact).
- If no relevant facts, return empty array.

Example:
User: "I am a React developer and I hate TypeScript."
Output: { "facts": [{ "key": "role", "value": "React Developer" }, { "key": "preference", "value": "Dislikes TypeScript" }] }
`
          },
          { role: 'user', content: userText }
        ],
        response_format: { type: 'json_object' }
      });

      const content = completion.choices[0].message.content;
      if (!content) return;

      const result = JSON.parse(content);
      if (result.facts && Array.isArray(result.facts)) {
        for (const fact of result.facts) {
          // Check if fact already exists to avoid dupes (naive check)
          const exists = await MemoryItem.findOne({
            userId,
            scope: 'user',
            key: fact.key,
            value: fact.value
          });

          if (!exists) {
            await MemoryItem.create({
              scope: 'user',
              userId,
              key: fact.key,
              value: fact.value,
              sessionId: options?.sessionId // Optional link to origin session
            });
            // console.info(`[Memory] Saved fact: ${fact.key} = ${fact.value}`);
          }
        }
      }

    } catch (err) {
      console.error('[Memory] Extraction failed:', err);
    }
  }

  /**
   * Track assistant response for summarization
   */
  static async trackAssistantResponse(userId: string, response: string, sessionId?: string, options?: any) {
    if (!userId || !response) return;
    await this.trackMessage(userId, response, 'assistant', sessionId, options);
  }
}

import fs from 'fs';
import path from 'path';
import { v4 as uuidv4 } from 'uuid';
import pdf from 'pdf-parse';

const DATA_DIR = process.env.DATA_DIR || path.join(process.cwd(), 'data');
const KNOWLEDGE_FILE = path.join(DATA_DIR, 'knowledge.json');

// Ensure directory exists (sync is fine at startup, or make it async if called later)
if (!fs.existsSync(DATA_DIR)) {
    try { fs.mkdirSync(DATA_DIR, { recursive: true }); } catch { }
}

export interface Document {
    id: string;
    filename: string;
    content: string;
    tags: string[];
    createdAt: number;
    embedding?: number[]; // Placeholder for future
}

// Load knowledge base
async function loadKnowledge(): Promise<Document[]> {
    try {
        await fs.promises.access(KNOWLEDGE_FILE);
        const data = await fs.promises.readFile(KNOWLEDGE_FILE, 'utf-8');
        return JSON.parse(data);
    } catch {
        return [];
    }
}

// Save knowledge base
async function saveKnowledge(docs: Document[]) {
    await fs.promises.writeFile(KNOWLEDGE_FILE, JSON.stringify(docs, null, 2));
}

export const KnowledgeService = {
    getAll: async () => await loadKnowledge(),

    add: async (filename: string, content: string, tags: string[] = []) => {
        console.log(`[KnowledgeService] Adding: ${filename}`);
        const docs = await loadKnowledge();
        const newDoc: Document = {
            id: uuidv4(),
            filename,
            content,
            tags,
            createdAt: Date.now()
        };
        docs.push(newDoc);
        try {
            await saveKnowledge(docs);
            console.log(`[KnowledgeService] Saved ${docs.length} docs.`);
        } catch (e) {
            console.error('[KnowledgeService] Save failed', e);
        }
        return newDoc;
    },

    delete: async (id: string) => {
        const docs = await loadKnowledge();
        const filtered = docs.filter(d => d.id !== id);
        await saveKnowledge(filtered);
    },

    search: async (query: string): Promise<{ document: Document, score: number, snippet: string }[]> => {
        console.log(`[KnowledgeService] Searching: ${query}`);
        const docs = await loadKnowledge();
        console.log(`[KnowledgeService] Docs in DB: ${docs.length}`);
        const q = query.toLowerCase();

        // Simple keyword scoring
        const results = docs.map(doc => {
            const text = doc.content.toLowerCase();
            const filename = doc.filename.toLowerCase();
            let score = 0;

            // Exact phrase match
            if (text.includes(q)) score += 10;
            if (filename.includes(q)) score += 5;

            // Token match
            const tokens = q.split(/\s+/);
            let matches = 0;
            tokens.forEach(t => {
                if (text.includes(t)) matches++;
            });

            score += matches;

            // Find snippet
            const idx = text.indexOf(q.split(' ')[0]);
            const start = Math.max(0, idx - 50);
            const snippet = doc.content.substring(start, start + 300) + '...';

            return { document: doc, score, snippet };
        });

        // Normalize scores roughly 0-1
        return results
            .filter(r => r.score > 0)
            .sort((a, b) => b.score - a.score)
            .map(r => ({ ...r, score: Math.min(r.score / 10, 1) })); // Simple normalization assumption
    },

    parsePDF: async (buffer: Buffer): Promise<string> => {
        try {
            const data = await pdf(buffer);
            return data.text;
        } catch (e) {
            console.error('PDF Parse Error', e);
            throw new Error('Failed to parse PDF');
        }
    }
};

import { Workspace, IWorkspace } from '../models/workspace';
import { WorkspaceMember, IWorkspaceMember } from '../models/workspaceMember';
import { User } from '../models/user';
import { Types } from 'mongoose';

export class WorkspaceService {

    /**
     * Create a new workspace and assign the creator as OWNER
     */
    async createWorkspace(userId: string, name: string, slug?: string): Promise<IWorkspace> {
        const finalSlug = slug || name.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');

        // Limits based on FREE plan default
        const defaults = {
            plan: 'free',
            limits: {
                maxAgents: 2,
                maxTokensPerDay: 100000,
                maxConcurrentJobs: 1,
                storageGB: 1
            }
        };

        const workspace = await Workspace.create({
            name,
            slug: finalSlug,
            ownerId: new Types.ObjectId(userId),
            ...defaults
        });

        // Add creator as OWNER
        await WorkspaceMember.create({
            workspaceId: workspace._id,
            userId: new Types.ObjectId(userId),
            role: 'OWNER'
        });

        return workspace;
    }

    /**
     * Get workspace by ID with member check
     */
    async getWorkspace(workspaceId: string, userId: string): Promise<IWorkspace | null> {
        const member = await WorkspaceMember.findOne({
            workspaceId: new Types.ObjectId(workspaceId),
            userId: new Types.ObjectId(userId)
        });

        if (!member) return null; // Access Denied or Not Found

        return await Workspace.findById(workspaceId);
    }

    /**
     * Get all workspaces for a user
     */
    async getUserWorkspaces(userId: string) {
        const memberships = await WorkspaceMember.find({ userId: new Types.ObjectId(userId) }).populate('workspaceId');
        return memberships.map(m => m.workspaceId);
    }

    /**
     * Add a member to the workspace
     */
    async addMember(adminUserId: string, workspaceId: string, targetEmail: string, role: 'ADMIN' | 'DEVELOPER' | 'VIEWER') {
        // 1. Verify Admin permissions
        const admin = await WorkspaceMember.findOne({
            workspaceId: new Types.ObjectId(workspaceId),
            userId: new Types.ObjectId(adminUserId),
            role: { $in: ['OWNER', 'ADMIN'] }
        });
        if (!admin) throw new Error('Unauthorized: Only Admins can add members');

        // 2. Find target user
        const targetUser = await User.findOne({ email: targetEmail.toLowerCase() });
        if (!targetUser) throw new Error('User not found');

        // 3. Add membership
        try {
            await WorkspaceMember.create({
                workspaceId: new Types.ObjectId(workspaceId),
                userId: targetUser._id,
                role
            });
        } catch (e: any) {
            if (e.code === 11000) throw new Error('User is already a member');
            throw e;
        }
    }

    /**
     * Update workspace details (Name, Provider Config)
     */
    async updateWorkspace(adminUserId: string, workspaceId: string, updates: { name?: string, providerConfig?: any }) {
        // 1. Verify Admin permissions
        const admin = await WorkspaceMember.findOne({
            workspaceId: new Types.ObjectId(workspaceId),
            userId: new Types.ObjectId(adminUserId),
            role: { $in: ['OWNER', 'ADMIN'] }
        });
        if (!admin) throw new Error('Unauthorized: Only Admins can update workspace');

        // 2. Update
        const workspace = await Workspace.findById(workspaceId);
        if (!workspace) throw new Error('Workspace not found');

        if (updates.name) workspace.name = updates.name;
        if (updates.providerConfig) {
            // Merge or overwrite provider config
            workspace.providerConfig = { ...workspace.providerConfig, ...updates.providerConfig };
        }

        await workspace.save();
        return workspace;
    }

    /**
     * Remove a member from the workspace
     */
    async removeMember(adminUserId: string, workspaceId: string, targetMemberId: string) {
        // 1. Verify Admin permissions
        const admin = await WorkspaceMember.findOne({
            workspaceId: new Types.ObjectId(workspaceId),
            userId: new Types.ObjectId(adminUserId),
            role: { $in: ['OWNER', 'ADMIN'] }
        });
        if (!admin) throw new Error('Unauthorized: Only Admins can remove members');

        // Prevent removing self if Owner (optional safety, but let's just do basic check)
        // Ideally, Owner cannot be removed by anyone.
        const target = await WorkspaceMember.findById(targetMemberId);
        if (!target) return; // Already gone

        if (target.role === 'OWNER') {
            throw new Error('Cannot remove the Workspace Owner');
        }

        await WorkspaceMember.findByIdAndDelete(targetMemberId);
    }

    /**
     * Get all members of a workspace
     */
    async getWorkspaceMembers(userId: string, workspaceId: string) {
        // Verify membership first
        const member = await WorkspaceMember.findOne({
            workspaceId: new Types.ObjectId(workspaceId),
            userId: new Types.ObjectId(userId)
        });
        if (!member) throw new Error('Unauthorized');

        return await WorkspaceMember.find({ workspaceId: new Types.ObjectId(workspaceId) })
            .populate('userId', 'name email picture');
    }

    /**
     * Migrate legacy user to have a default workspace
     */
    async ensurePersonalWorkspace(userId: string) {
        const existing = await this.getUserWorkspaces(userId);
        if (existing.length > 0) return existing[0];

        const user = await User.findById(userId);
        if (!user) throw new Error('User not found');

        const name = user.name ? `${user.name}'s Workspace` : 'Personal Workspace';
        return await this.createWorkspace(userId, name);
    }
}

