// Rate Limiting Logic (Ported)
const toolRateBuckets = new Map<string, { minute: number; count: number }>();

function rateLimitBucketKey(name: string, input: any) {
    if (name === 'browser_run' || name === 'browser_open' || name === 'visual_qa') {
        return `${name}:${input?.sessionId || 'global'} `;
    }
    return name;
}

function checkToolRateLimit(bucketKey: string, limitPerMinute?: number): { allowed: boolean; retryAfterMs?: number } {
    if (!limitPerMinute || limitPerMinute <= 0) return { allowed: true };
    const now = Date.now();
    const minute = Math.floor(now / 60000);
    const bucket = toolRateBuckets.get(bucketKey);

    if (bucket && bucket.minute === minute) {
        if (bucket.count >= limitPerMinute) {
            return { allowed: false, retryAfterMs: (minute + 1) * 60000 - now };
        }
        bucket.count++;
    } else {
        toolRateBuckets.set(bucketKey, { minute, count: 1 });
    }
    return { allowed: true };
}

export interface ToolContext {
    sessionId?: string;
    workspaceId?: string; // New: Strict Isolation Context
    userId?: string;
    language?: string;
}

export async function executeTool(name: string, input: any, context?: ToolContext) {
    const logs: string[] = [];
    const t0 = Date.now();
    let effectiveName = name;
    let effectiveInput = { ...input };

    // --- Aliasing & Compatibility Layer ---
    const contextSessionId = context?.sessionId;
    const contextWorkspaceId = context?.workspaceId;

    if (!contextWorkspaceId) {
        console.warn(`[ToolService] ⚠️ SECURITY WARNING: Tool '${name}' executed without Workspace Context! Defaults to global/shared.`);
    }

    if (name === 'browser_open') {
        effectiveName = 'browser_run';
        const url = effectiveInput.url || effectiveInput.input || '';
        if (!Array.isArray(effectiveInput.actions)) effectiveInput.actions = [];
        if (url) {
            effectiveInput.actions.unshift({ type: 'goto', url });
        } else if (effectiveInput.actions.length === 0) {
            effectiveInput.actions.push({ type: 'goto', url: 'https://www.google.com' });
        }
    }
    if (name === 'browser_get_state') {
        effectiveName = 'browser_run';
        if (!Array.isArray(effectiveInput.actions)) effectiveInput.actions = [];
        if (effectiveInput.actions.length === 0) {
            effectiveInput.actions.push({ type: 'ui_audit' });
        }
    }
    if (name === 'browser_snapshot') {
        effectiveName = 'browser_run';
        if (!Array.isArray(effectiveInput.actions)) effectiveInput.actions = [];
        if (effectiveInput.actions.length === 0) {
            effectiveInput.actions.push({ type: 'ui_audit' });
        }
    }
    if (name === 'web_search') {
        effectiveName = 'browser_run';
        const query = effectiveInput.query || effectiveInput.q || effectiveInput.input || '';
        if (!Array.isArray(effectiveInput.actions)) effectiveInput.actions = [];
        if (query) {
            effectiveInput.actions.unshift({ type: 'goto', url: `https://www.google.com/search?q=${encodeURIComponent(query)}` });
            effectiveInput.actions.push({ type: 'wait', ms: 2000 });
        } else {
            effectiveInput.actions.push({ type: 'goto', url: 'https://www.google.com' });
        }
    }

    // [FIX] Aliasing for commonly hallucinated tool names
    if (name === 'npm_install' || name === 'install_package') {
        effectiveName = 'npm_manager';
        if (!effectiveInput.command) effectiveInput.command = 'install';
    }
    if (name === 'npm_build') {
        effectiveName = 'npm_manager';
        effectiveInput.command = 'run';
        effectiveInput.script = 'build';
    }
    if (name === 'npm_run') {
        effectiveName = 'npm_manager';
        effectiveInput.command = 'run';
    }
    if (name === 'npm_start') {
        effectiveName = 'npm_manager';
        effectiveInput.command = 'run';
        effectiveInput.script = 'dev';
    }
    if (name === 'npm_test') {
        effectiveName = 'npm_manager';
        effectiveInput.command = 'run';
        effectiveInput.script = 'test';
    }
    if (name === 'command_execute' || name === 'run_command' || name === 'exec' || name === 'terminal') {
        effectiveName = 'shell_execute';
    }
    if (name === 'project_scaffold') {
        effectiveName = 'scaffold_project';
    }
    if (name === 'create_file' || name === 'write_file') {
        effectiveName = 'file_edit';
        effectiveInput.mode = 'create';
    }
    if (name === 'edit_file' || name === 'modify_file') {
        effectiveName = 'file_edit';
    }
    if (name === 'read_file' || name === 'view_file' || name === 'get_file') {
        effectiveName = 'file_read';
    }
    if (name === 'list_files' || name === 'list_directory' || name === 'dir') {
        effectiveName = 'ls';
    }
    if (name === 'search_code' || name === 'find_in_files') {
        effectiveName = 'grep';
    }
    if (name === 'browse' || name === 'open_browser' || name === 'web_browse') {
        effectiveName = 'browser_run';
    }
    if (name === 'git_commit' || name === 'commit') {
        effectiveName = 'git_operations';
        effectiveInput.operation = 'commit';
    }
    if (name === 'git_push' || name === 'push') {
        effectiveName = 'git_operations';
        effectiveInput.operation = 'push';
    }

    // Universal Session Injection
    if ((effectiveName === 'browser_run' || effectiveName === 'visual_qa' || effectiveName === 'codebase_navigator') && !effectiveInput.sessionId && contextSessionId) {
        effectiveInput.sessionId = contextSessionId;
    }

    // [NEW] Deep Memory Handlers
    if (name === 'recall_memory') {
        try {
            const results = await vectorDb.search(input.query, input.limit || 5);
            const output = results.map(r =>
                `[File: ${r.doc.metadata.filePath}]\nScore: ${r.score.toFixed(2)}\nContent:\n${r.doc.content}`
            ).join('\n---\n');
            return { ok: true, output: output || 'No relevant memory found.', logs };
        } catch (e: any) {
            return { ok: false, output: `Memory Recall Failed: ${e.message}`, logs };
        }
    }

    if (name === 'memorize_codebase') {
        try {
            const { workspaceService } = require('./WorkspaceService');
            const root = input.directory || workspaceService.getActiveRoot();
            const exts = input.extensions || ['ts', 'tsx', 'js', 'json', 'md', 'py', 'css', 'html'];
            const pattern = `**/*.{${exts.join(',')}}`;
            const files = await glob(pattern, { cwd: root, ignore: ['**/node_modules/**', '**/dist/**', '**/.git/**'] });
            console.log(`[Memory] Indexing ${files.length} files from ${root}...`);
            await vectorDb.clear();
            let count = 0;
            for (const file of files) {
                const fullPath = path.join(root, file);
                if (fs.statSync(fullPath).isDirectory()) continue;
                const content = fs.readFileSync(fullPath, 'utf-8');
                if (content.length > 50000) {
                    await vectorDb.addDocument(content.slice(0, 20000), { filePath: file });
                } else {
                    await vectorDb.addDocument(content, { filePath: file });
                }
                count++;
            }
            return { ok: true, output: `Successfully indexed ${count} files into Deep Memory.`, logs };
        } catch (e: any) {
            return { ok: false, output: `Memorization Failed: ${e.message}`, logs };
        }
    }

    logs.push(`[${new Date().toISOString()}] start ${effectiveName} (orig=${name})`);

    try {
        const tDef = tools.find(t => t.name === effectiveName);
        if (!tDef) {
            return { ok: false, error: 'unknown_tool', logs };
        }

        // Rate Limit Check
        const bucketKey = rateLimitBucketKey(effectiveName, effectiveInput);
        const rl = checkToolRateLimit(bucketKey, tDef.rateLimitPerMinute);
        if (!rl.allowed) {
            logs.push(`rate_limited=1 bucket=${bucketKey} retry_after_ms=${rl.retryAfterMs}`);
            return { ok: false, error: 'rate_limited', output: { retryAfterMs: rl.retryAfterMs }, logs };
        }

        // Execute
        // Genesis Wrapper Special Case Handling to avoid circular dependency issues in registry
        // If we want to move the Genesis wrapper logic HERE instead of in registry, we can.
        // But for now, we assume tDef has the handler.

        if (typeof (tDef as any).execute === 'function') {
            const res = await (tDef as any).execute(effectiveInput, context);
            const ok = !!res?.ok;
            const output = res?.output ?? null;
            const artifacts = Array.isArray(res?.artifacts) ? res.artifacts : undefined;
            const toolLogs = Array.isArray(res?.logs) ? res.logs : [];
            logs.push(...toolLogs);
            return { ok, output, logs, artifacts, error: res?.error };
        }

        return { ok: false, error: 'tool_implementation_missing', logs };

    } catch (e: any) {
        const duration = Date.now() - t0;
        logs.push(`exception=${e.message} duration=${duration}ms`);
        return { ok: false, error: `exception: ${e.message}`, logs };
    }
}

import { OpenAI } from 'openai';

interface QueuedTask {
    id: string;
    message: string;
    timestamp: Date;
    priority: 'high' | 'normal';
    relatedToCurrentTask: boolean;
    sessionId?: string;
}

interface ContextAnalysis {
    action: 'merge' | 'queue' | 'execute';
    isCorrection: boolean;
    confidence: number;
    reason: string;
}

class TaskQueueManager {
    private queue: Map<string, QueuedTask[]> = new Map(); // sessionId -> tasks
    private currentTasks: Map<string, string> = new Map(); // sessionId -> current task description
    private openai: OpenAI;

    constructor() {
        const envKey = typeof process.env.OPENAI_API_KEY === 'string' ? process.env.OPENAI_API_KEY.trim() : '';
        this.openai = new OpenAI({
            apiKey: envKey || 'sk-local-dev',
        });
    }

    /**
     * Analyze if a new message is a correction/clarification or a new task
     */
    async analyzeContext(
        newMessage: string,
        currentTaskDescription: string | null,
        sessionId: string
    ): Promise<ContextAnalysis> {
        // If no current task, always execute immediately
        if (!currentTaskDescription) {
            return {
                action: 'execute',
                isCorrection: false,
                confidence: 1.0,
                reason: 'No current task running',
            };
        }

        // Quick keyword-based detection for corrections
        const correctionKeywords = [
            'لا', 'خطأ', 'صحح', 'بدلاً', 'غير', 'عدل', 'ليس', 'توقف',
            'no', 'wrong', 'fix', 'instead', 'change', 'modify', 'not', 'stop',
            'actually', 'wait', 'correction', 'mistake'
        ];

        const messageLower = newMessage.toLowerCase();
        const hasCorrectionKeyword = correctionKeywords.some(kw =>
            messageLower.includes(kw)
        );

        // Use LLM for semantic analysis
        try {
            const prompt = `You are analyzing whether a new user message is a correction/clarification of the current task, or a completely new task.

Current Task: "${currentTaskDescription}"
New Message: "${newMessage}"

Analyze and respond in JSON format:
{
  "isCorrection": boolean,
  "confidence": number (0-1),
  "reason": "brief explanation"
}

Guidelines:
- isCorrection = true if the new message:
  * Corrects/modifies the current task
  * Adds clarification to the current task
  * Uses pronouns referring to current task (it, this, that)
  * Mentions same files/components as current task
- isCorrection = false if the new message:
  * Introduces a completely different topic
  * Asks about unrelated functionality
  * Requests a new feature unrelated to current work`;

            const response = await this.openai.chat.completions.create({
                model: 'gpt-4o-mini',
                messages: [{ role: 'user', content: prompt }],
                temperature: 0.3,
                max_tokens: 200,
            });

            const content = response.choices[0]?.message?.content;
            if (!content) {
                throw new Error('No response from LLM');
            }

            const analysis = JSON.parse(content);

            // Boost confidence if correction keywords are present
            if (hasCorrectionKeyword && analysis.isCorrection) {
                analysis.confidence = Math.min(1.0, analysis.confidence + 0.2);
            }

            return {
                action: analysis.isCorrection && analysis.confidence > 0.6 ? 'merge' : 'queue',
                isCorrection: analysis.isCorrection,
                confidence: analysis.confidence,
                reason: analysis.reason,
            };
        } catch (error) {
            console.error('Context analysis failed:', error);
            // Fallback to keyword-based detection
            return {
                action: hasCorrectionKeyword ? 'merge' : 'queue',
                isCorrection: hasCorrectionKeyword,
                confidence: 0.5,
                reason: 'Fallback to keyword detection due to LLM error',
            };
        }
    }

    /**
     * Add a task to the queue
     */
    addToQueue(task: Omit<QueuedTask, 'id' | 'timestamp'>): QueuedTask {
        const sessionId = task.sessionId || 'default';
        const newTask: QueuedTask = {
            ...task,
            id: `task_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
            timestamp: new Date(),
        };

        if (!this.queue.has(sessionId)) {
            this.queue.set(sessionId, []);
        }

        this.queue.get(sessionId)!.push(newTask);
        return newTask;
    }

    /**
     * Remove a task from the queue
     */
    removeFromQueue(taskId: string, sessionId: string): boolean {
        const tasks = this.queue.get(sessionId);
        if (!tasks) return false;

        const index = tasks.findIndex(t => t.id === taskId);
        if (index === -1) return false;

        tasks.splice(index, 1);
        return true;
    }

    /**
     * Get all queued tasks for a session
     */
    getQueue(sessionId: string): QueuedTask[] {
        return this.queue.get(sessionId) || [];
    }

    /**
     * Get the next task to execute
     */
    getNextTask(sessionId: string): QueuedTask | null {
        const tasks = this.queue.get(sessionId);
        if (!tasks || tasks.length === 0) return null;

        // Sort by priority (high first) then by timestamp (oldest first)
        tasks.sort((a, b) => {
            if (a.priority !== b.priority) {
                return a.priority === 'high' ? -1 : 1;
            }
            return a.timestamp.getTime() - b.timestamp.getTime();
        });

        return tasks[0];
    }

    /**
     * Mark a task as started (remove from queue)
     */
    startTask(taskId: string, sessionId: string): boolean {
        const task = this.queue.get(sessionId)?.find(t => t.id === taskId);
        if (!task) return false;

        this.currentTasks.set(sessionId, task.message);
        return this.removeFromQueue(taskId, sessionId);
    }

    /**
     * Set the current task description
     */
    setCurrentTask(sessionId: string, description: string): void {
        this.currentTasks.set(sessionId, description);
    }

    /**
     * Clear the current task
     */
    clearCurrentTask(sessionId: string): void {
        this.currentTasks.delete(sessionId);
    }

    /**
     * Get the current task description
     */
    getCurrentTask(sessionId: string): string | null {
        return this.currentTasks.get(sessionId) || null;
    }

    /**
     * Clear all tasks for a session
     */
    clearQueue(sessionId: string): void {
        this.queue.delete(sessionId);
        this.currentTasks.delete(sessionId);
    }
}

export const taskQueueManager = new TaskQueueManager();
export type { QueuedTask, ContextAnalysis };

import fs from 'fs';
import path from 'path';

const DB_PATH = path.join(process.cwd(), 'cortex.json');

export interface TaskState {
    id: string;
    goal: string;
    status: 'pending' | 'running' | 'completed' | 'failed' | 'paused';
    step: number;
    history: any[];
    rootDir: string;
    createdAt: number;
    updatedAt: number;
    metadata?: any;
}

export interface FinancialState {
    balance: number;
    totalUsage: number;
    transactions: {
        timestamp: number;
        amount: number;
        description: string;
        taskId?: string;
    }[];
}

interface CortexDB {
    tasks: Record<string, TaskState>;
    financials: FinancialState;
}

export class CortexState {
    private static instance: CortexState;
    private db: CortexDB;

    private constructor() {
        this.db = this.load();
    }

    public static getInstance(): CortexState {
        if (!CortexState.instance) {
            CortexState.instance = new CortexState();
        }
        return CortexState.instance;
    }

    private load(): CortexDB {
        if (!fs.existsSync(DB_PATH)) {
            return {
                tasks: {},
                financials: { balance: 100.0, totalUsage: 0, transactions: [] } // Start with $100 credit
            };
        }
        try {
            return JSON.parse(fs.readFileSync(DB_PATH, 'utf-8'));
        } catch (e) {
            console.error('Failed to load Cortex DB, resetting:', e);
            return { tasks: {}, financials: { balance: 100.0, totalUsage: 0, transactions: [] } };
        }
    }

    private save() {
        fs.writeFileSync(DB_PATH, JSON.stringify(this.db, null, 2));
    }

    // --- Task Management ---

    public saveTask(state: TaskState) {
        state.updatedAt = Date.now();
        this.db.tasks[state.id] = state;
        this.save();
    }

    public getTask(id: string): TaskState | undefined {
        return this.db.tasks[id];
    }

    public getAllTasks(): TaskState[] {
        return Object.values(this.db.tasks);
    }

    // --- Financial Management ---

    public recordTransaction(amount: number, description: string, taskId?: string): boolean {
        // Negative amount = cost, Positive = deposit
        if (this.db.financials.balance + amount < 0) {
            console.warn(`[Cortex] Financial Transaction Blocked: Insufficient Funds. Balance: ${this.db.financials.balance}, Req: ${amount}`);
            return false;
        }

        this.db.financials.balance += amount;
        if (amount < 0) {
            this.db.financials.totalUsage += Math.abs(amount);
        }

        this.db.financials.transactions.push({
            timestamp: Date.now(),
            amount,
            description,
            taskId
        });
        this.save();
        return true;
    }

    public getBalance(): number {
        return this.db.financials.balance;
    }
}

