 */
router.delete('/:sessionId/:taskId', requireAuth, async (req, res) => {
    try {
        const { sessionId, taskId } = req.params;
        const success = taskQueueManager.removeFromQueue(taskId, sessionId);

        if (!success) {
            return res.status(404).json({ error: 'Task not found' });
