      })),
      artifacts: artifacts.map(a => ({
        id: a._id,
        name: a.name,
        type: a.name.endsWith('.html') ? 'text/html' : 'image/png', // Simple heuristic
        createdAt: a.createdAt,
        category: 'artifact',
        url: a.href
      }))
