import * as fs from 'fs/promises';

import { broadcast } from '../ws';

export class SSHManager {
    private connections: Map<string, NodeSSH> = new Map();
    private shellStreams: Map<string, any> = new Map();
    private connectionStatus: Map<string, ServerConnectionStatus> = new Map();
    private readonly maxConnections = 10;

    /**
     * Connect to a server using SSH
     */
    async connect(serverConfig: ServerConfig): Promise<void> {
        // Check connection limit
        if (this.connections.size >= this.maxConnections) {
            throw new Error(`Maximum connections (${this.maxConnections}) reached`);
        }

        // Check if already connected
        if (this.connections.has(serverConfig.id)) {
            console.log(`[SSH] Already connected to ${serverConfig.name}`);
            return;
        }

        const ssh = new NodeSSH();

        try {
            const sshConfig: SSHConfig = {
                host: serverConfig.host,
                port: serverConfig.port,
                username: serverConfig.username,
            };

            // Add authentication
            if (serverConfig.authMethod === 'key' && serverConfig.keyPath) {
                const privateKey = await fs.readFile(serverConfig.keyPath, 'utf8');
                sshConfig.privateKey = privateKey;
            } else if (serverConfig.authMethod === 'password' && serverConfig.password) {
                sshConfig.password = serverConfig.password;
            } else {
                throw new Error('Invalid authentication configuration');
            }

            await ssh.connect(sshConfig);

            this.connections.set(serverConfig.id, ssh);
            this.connectionStatus.set(serverConfig.id, {
                serverId: serverConfig.id,
                isConnected: true,
                connectedAt: new Date(),
            });

            console.log(`[SSH] ✓ Connected to ${serverConfig.name} (${serverConfig.host})`);
        } catch (error: any) {
            this.connectionStatus.set(serverConfig.id, {
                serverId: serverConfig.id,
                isConnected: false,
                lastError: error.message,
            });

            console.error(`[SSH] ✗ Failed to connect to ${serverConfig.name}:`, error.message);
            throw error;
        }
    }

    /**
     * Request an interactive shell for the server
     */
    async requestShell(serverId: string, terminalId: string, options?: { cols: number, rows: number }): Promise<void> {
        const ssh = this.connections.get(serverId);
        if (!ssh) throw new Error(`Not connected to server ${serverId}`);

        // If already has a shell for this terminal, skip
        if (this.shellStreams.has(terminalId)) return;

        try {
            const stream = await ssh.requestShell({
                term: 'xterm-color',
                cols: options?.cols || 80,
                rows: options?.rows || 24,
            });

            this.shellStreams.set(terminalId, stream);

            stream.on('data', (data: any) => {
                broadcast({ type: 'terminal_output', id: terminalId, data: data.toString() });
            });

            stream.on('close', () => {
                this.shellStreams.delete(terminalId);
                broadcast({ type: 'terminal_output', id: terminalId, data: '\r\n[Remote Connection Closed]\r\n' });
            });

        } catch (error: any) {
            console.error(`[SSH] Failed to request shell:`, error.message);
            throw error;
        }
    }

    /**
     * Send input to interactive shell
     */
    sendInput(terminalId: string, data: string): void {
        const stream = this.shellStreams.get(terminalId);
        if (stream) {
            stream.write(data);
        }
    }

    /**
     * Resize interactive shell
     */
    resizeShell(terminalId: string, cols: number, rows: number): void {
        const stream = this.shellStreams.get(terminalId);
        if (stream && stream.setWindow) {
            stream.setWindow(rows, cols, 0, 0);
        }
    }

    /**
     * Execute command on remote server
     */
    async executeRemote(
        serverId: string,
        command: string,
        options?: { cwd?: string; timeout?: number }
    ): Promise<{ stdout: string; stderr: string; code: number }> {
        const ssh = this.connections.get(serverId);

        if (!ssh) {
            throw new Error(`Not connected to server ${serverId}`);
        }

        try {
            const result = await ssh.execCommand(command, {
                cwd: options?.cwd,
                onStdout: (chunk) => process.stdout.write(chunk.toString()),
                onStderr: (chunk) => process.stderr.write(chunk.toString()),
            });

            return {
                stdout: result.stdout,
                stderr: result.stderr,
                code: result.code || 0,
            };
        } catch (error: any) {
            console.error(`[SSH] Command execution failed:`, error.message);
            throw error;
        }
    }

    /**
     * Disconnect from server
     */
    async disconnect(serverId: string): Promise<void> {
        const ssh = this.connections.get(serverId);

        // Close any associated shell streams
        for (const [tid, stream] of this.shellStreams.entries()) {
            if (tid.includes(serverId)) { // Assuming terminalId might contain serverId for identification
                stream.end();
                this.shellStreams.delete(tid);
            }
        }

        if (ssh) {
            ssh.dispose();
            this.connections.delete(serverId);
            this.connectionStatus.set(serverId, {
                serverId,
                isConnected: false,
            });

            console.log(`[SSH] Disconnected from ${serverId}`);
        }
    }

    /**
     * Disconnect all connections
     */
    async disconnectAll(): Promise<void> {
        const serverIds = Array.from(this.connections.keys());
        await Promise.all(serverIds.map(id => this.disconnect(id)));
        console.log('[SSH] All connections closed');
    }

    /**
     * Get connection status
     */
    getStatus(serverId: string): ServerConnectionStatus | undefined {
        return this.connectionStatus.get(serverId);
    }

    /**
     * Check if connected to server
     */
    isConnected(serverId: string): boolean {
        return this.connections.has(serverId);
    }

    /**
     * Get all active connections
     */
    getActiveConnections(): string[] {
        return Array.from(this.connections.keys());
    }

    /**
     * Test server connection without keeping it open
     */
    async testConnection(serverConfig: ServerConfig): Promise<boolean> {
        const ssh = new NodeSSH();

        try {
            const sshConfig: SSHConfig = {
                host: serverConfig.host,
                port: serverConfig.port,
                username: serverConfig.username,
            };

            if (serverConfig.authMethod === 'key' && serverConfig.keyPath) {
                const privateKey = await fs.readFile(serverConfig.keyPath, 'utf8');
                sshConfig.privateKey = privateKey;
            } else if (serverConfig.authMethod === 'password' && serverConfig.password) {
                sshConfig.password = serverConfig.password;
            }

            await ssh.connect(sshConfig);
            ssh.dispose();

            return true;
        } catch (error) {
            return false;
        }
    }
}

// Singleton instance
export const sshManager = new SSHManager();

/**
 * Command Router
 * Routes commands to local or remote execution based on context
 */

import { exec } from 'child_process';
import { promisify } from 'util';
import { sshManager } from './ssh-manager';
import { CommandExecutionContext } from '../models/ServerConfig';

const execAsync = promisify(exec);

export interface CommandResult {
    stdout: string;
    stderr: string;
    code: number;
    executedOn: 'local' | 'remote';
    serverId?: string;
}

export class CommandRouter {
    /**
     * Execute command (local or remote based on context)
     */
    async execute(context: CommandExecutionContext): Promise<CommandResult> {
        if (context.serverId) {
            return this.executeRemote(context);
        } else {
            return this.executeLocal(context);
        }
    }

    /**
     * Execute command locally
     */
    private async executeLocal(context: CommandExecutionContext): Promise<CommandResult> {
        try {
            const { stdout, stderr } = await execAsync(context.command, {
                cwd: context.workingDirectory || process.cwd(),
                timeout: context.timeout || 30000, // 30s default
                maxBuffer: 10 * 1024 * 1024, // 10MB
            });

            return {
                stdout,
                stderr,
                code: 0,
                executedOn: 'local',
            };
        } catch (error: any) {
            return {
                stdout: error.stdout || '',
                stderr: error.stderr || error.message,
                code: error.code || 1,
                executedOn: 'local',
            };
        }
    }

    /**
     * Execute command on remote server via SSH
     */
    private async executeRemote(context: CommandExecutionContext): Promise<CommandResult> {
        if (!context.serverId) {
            throw new Error('Server ID required for remote execution');
        }

        // Check if connected
        if (!sshManager.isConnected(context.serverId)) {
            throw new Error(`Not connected to server ${context.serverId}`);
        }

        const result = await sshManager.executeRemote(
            context.serverId,
            context.command,
            {
                cwd: context.workingDirectory,
                timeout: context.timeout,
            }
        );

        return {
            ...result,
            executedOn: 'remote',
            serverId: context.serverId,
        };
    }

    /**
     * Smart routing: Detect if command should run locally or remotely
     */
    async smartExecute(
        command: string,
        activeServerId?: string,
        workingDirectory?: string
    ): Promise<CommandResult> {
        // If user has explicitly selected a server, use it
        if (activeServerId) {
            return this.execute({
                command,
                serverId: activeServerId,
                workingDirectory,
            });
        }

        // Otherwise, execute locally
        return this.execute({
            command,
            workingDirectory,
        });
    }
}

// Singleton instance
export const commandRouter = new CommandRouter();

import { LiveEvent } from '../ws';

type Id = string;

export interface MockRun {
  id: Id;
  sessionId?: Id;
  status: 'pending' | 'running' | 'done' | 'blocked' | 'failed';
  steps: Array<{ name: string; status: 'pending' | 'running' | 'done' | 'blocked' | 'failed'; why?: string }>;
}
export interface MockToolExec {
  id: Id;
  runId: Id;
  name: string;
  input: any;
  output?: any;
  ok: boolean;
  logs: string[];
  createdAt: number;
}
export interface MockArtifact {
  id: Id;
  runId: Id;
  name: string;
  href: string;
}
export interface MockApproval {
  id: Id;
  runId: Id;
  action: string;
  risk: string;
  status: 'pending' | 'approved' | 'denied';
  planName: string;
  planInput: any;
}

export interface MockFolder {
  _id: Id;
  name: string;
  createdAt: number;
  updatedAt: number;
}

const runs: MockRun[] = [];
const execs: MockToolExec[] = [];
const artifacts: MockArtifact[] = [];
const approvals: MockApproval[] = [];
const folders: MockFolder[] = [];
const sessions: Array<{ id: Id; title: string; mode: 'ADVISOR' | 'BUILDER' | 'SAFE' | 'OWNER'; kind?: 'chat' | 'agent'; lastSnippet?: string; lastUpdatedAt?: number }> = [];
const summaries: Array<{ sessionId: Id; content: string; ts: number }> = [];
const messages: Array<{ id: Id; sessionId: Id; role: 'user' | 'assistant' | 'system'; content: string; ts: number; runId?: Id }> = [];

function nextId(prefix: string, n: number) {
  return `${prefix}${n}`;
}

export const store = {
  createRun(sessionId?: Id): MockRun {
    const id = nextId('run_', runs.length + 1);
    const run: MockRun = { id, sessionId, status: 'running', steps: [] };
    runs.push(run);
    return run;
  },
  updateRun(id: Id, patch: Partial<MockRun>) {
    const r = runs.find(x => x.id === id);
    if (r) Object.assign(r, patch);
    return r;
  },
  addStep(runId: Id, name: string, status: MockRun['status'], why?: string) {
    const r = runs.find(x => x.id === runId);
    if (!r) return;
    r.steps.push({ name, status, why });
  },
  addExec(runId: Id, name: string, input: any, output: any, ok: boolean, logs: string[]) {
    const id = nextId('exec_', execs.length + 1);
    const e: MockToolExec = { id, runId, name, input, output, ok, logs, createdAt: Date.now() };
    execs.push(e);
    return e;
  },
  addArtifact(runId: Id, name: string, href: string) {
    const id = nextId('art_', artifacts.length + 1);
    const a: MockArtifact = { id, runId, name, href };
    artifacts.push(a);
    return a;
  },
  createApproval(runId: Id, action: string, risk: string, planName: string, planInput: any) {
    const id = nextId('appr_', approvals.length + 1);
    const ap: MockApproval = { id, runId, action, risk, status: 'pending', planName, planInput };
    approvals.push(ap);
    return ap;
  },
  updateApproval(id: Id, patch: Partial<MockApproval>) {
    const a = approvals.find(x => x.id === id);
    if (a) Object.assign(a, patch);
    return a;
  },
  getApproval(id: Id) {
    return approvals.find(x => x.id === id) || null;
  },
  listFolders() {
    return folders.slice().sort((a, b) => a.createdAt - b.createdAt);
  },
  createFolder(name: string) {
    const id = nextId('fold_', folders.length + 1);
    const now = Date.now();
    const f: MockFolder = { _id: id, name, createdAt: now, updatedAt: now };
    folders.push(f);
    return f;
  },
  updateFolder(id: Id, patch: Partial<Pick<MockFolder, 'name'>>) {
    const f = folders.find(x => x._id === id);
    if (!f) return null;
    if (typeof patch.name === 'string') f.name = patch.name;
    f.updatedAt = Date.now();
    return f;
  },
  deleteFolder(id: Id) {
    const idx = folders.findIndex(x => x._id === id);
    if (idx !== -1) folders.splice(idx, 1);
    return true;
  },
  listRuns(sessionId?: Id) { return runs.filter(r => !sessionId || r.sessionId === sessionId); },
  listExecs(runId?: Id) { return execs.filter(e => !runId || e.runId === runId); },
  listArtifacts(runId?: Id) { return artifacts.filter(a => !runId || a.runId === runId); },
  createSession(
    title: string,
    mode: 'ADVISOR' | 'BUILDER' | 'SAFE' | 'OWNER' = 'ADVISOR',
    kind: 'chat' | 'agent' = 'chat'
  ) {
    const existing = sessions.find(s => s.title === title && (s.kind || 'chat') === kind);
    if (existing) return existing;
    const id = nextId('sess_', sessions.length + 1);
    const s = { id, title, mode, kind };
    sessions.push(s);
    return s;
  },
  listSessions() { return sessions; },
  getSession(id: Id) {
    return sessions.find(s => s.id === id);
  },
  deleteSession(id: Id) {
    const idx = sessions.findIndex(s => s.id === id);
    if (idx !== -1) sessions.splice(idx, 1);
  },
  addMessage(sessionId: Id, role: 'user' | 'assistant' | 'system', content: string, runId?: Id) {
    const id = nextId('msg_', messages.length + 1);
    const m = { id, sessionId, role, content, runId, ts: Date.now() };
    messages.push(m);
    const s = sessions.find(s => s.id === sessionId);
    if (s) { s.lastSnippet = content.slice(0, 140); s.lastUpdatedAt = Date.now(); }
    return m;
  },
  listMessages(sessionId: Id) {
    return messages.filter(m => m.sessionId === sessionId);
  },
  getSummary(sessionId: Id) {
    return summaries.find(x => x.sessionId === sessionId) || null;
  },
  upsertSummary(sessionId: Id, content: string) {
    const existing = summaries.find(x => x.sessionId === sessionId);
    if (existing) {
      existing.content = content;
      existing.ts = Date.now();
      return existing;
    }
    const s = { sessionId, content, ts: Date.now() };
    summaries.push(s);
    return s;
  }
  ,
  mergeSessions(sourceId: Id, targetId: Id) {
    let movedMessages = 0;
    messages.forEach(m => {
      if (m.sessionId === sourceId) {
        m.sessionId = targetId;
        movedMessages++;
      }
    });
    runs.forEach(r => {
      if (r.sessionId === sourceId) {
        r.sessionId = targetId;
      }
    });
    const idx = sessions.findIndex(s => s.id === sourceId);
    if (idx >= 0) sessions.splice(idx, 1);
    return { movedMessages };
  }
};

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

type Role = 'OWNER' | 'ADMIN' | 'USER';
interface MockUser {
  id: string;
  email: string;
  passwordHash: string;
  role: Role;
  name?: string;
  picture?: string;
}

const dbPath = process.env.MOCK_DB_PATH || path.join(os.tmpdir(), 'joe-mock-db.json');

function normalizeEmail(email: string) {
  return String(email || '').trim().toLowerCase();
}

function safeParseJson<T>(raw: string): T | null {
  try {
    return JSON.parse(raw) as T;
  } catch {
    return null;
  }
}

let users: MockUser[] = [];

function loadFromDisk() {
  try {
    if (!fs.existsSync(dbPath)) return;
    const raw = fs.readFileSync(dbPath, 'utf8');
    const parsed = safeParseJson<{ users?: MockUser[] }>(raw);
    if (!parsed || !Array.isArray(parsed.users)) return;
    users = parsed.users
      .filter((u) => u && typeof u.id === 'string' && typeof u.email === 'string' && typeof u.passwordHash === 'string' && typeof u.role === 'string')
      .map((u) => ({ ...u, email: normalizeEmail(u.email) })) as MockUser[];
  } catch {
  }
}

function saveToDisk() {
  try {
    fs.writeFileSync(dbPath, JSON.stringify({ users }, null, 2), 'utf8');
  } catch {
  }
}

loadFromDisk();

export const mockDb = {
  findUserByEmail(email: string) {
    const e = normalizeEmail(email);
    return users.find(u => u.email === e) || null;
  },
  createUser(email: string, passwordHash: string, role: Role) {
    const id = String(users.length + 1);
    const u = { id, email: normalizeEmail(email), passwordHash, role };
    users.push(u);
    saveToDisk();
    return u;
  },
  countUsers() {
    return users.length;
  }
};

