  tenantId: Types.ObjectId; // Keeping for legacy, eventually replace with workspaceId
  workspaceId?: Types.ObjectId; // New Workspace Link
  projectId?: Types.ObjectId;
  userId: Types.ObjectId;
  title: string;
  mode: 'ADVISOR' | 'BUILDER' | 'SAFE' | 'OWNER';
  kind?: 'chat' | 'agent';
  isPinned?: boolean;
  lastSnippet?: string;
  lastUpdatedAt: Date;
