import { Request, Response, NextFunction } from 'express';
import { WorkspaceMember } from '../models/workspaceMember';
import { Workspace } from '../models/workspace';
import mongoose from 'mongoose';

export interface WorkspaceRequest extends Request {
    workspace?: any;
    workspaceMember?: any;
}

export async function requireWorkspace(req: WorkspaceRequest, res: Response, next: NextFunction) {
    const userId = (req as any).auth?.sub;
    if (!userId) return res.status(401).json({ error: 'Authentication required' });

    // 1. Resolve Workspace ID (Header > Query > Body)
    let workspaceId = req.headers['x-workspace-id'] as string;
    if (!workspaceId) {
        if (req.body && req.body.workspaceId) workspaceId = req.body.workspaceId;
        else if (req.query && req.query.workspaceId) workspaceId = req.query.workspaceId as string;
    }

    // 2. Fallback: If no ID, and User is Owner/Admin, maybe we can auto-select? 
    // For now, strict requirement: Client MUST send ID or we fail (unless it's a list operation)
    if (!workspaceId) {
        // Soft Fail: If route handles missing workspace, let it proceed. 
        // But for "requireWorkspace", we enforce it.
        return res.status(400).json({ error: 'Workspace ID required (x-workspace-id)' });
    }

    try {
        const wsId = new mongoose.Types.ObjectId(workspaceId);

        // 3. Verify Membership
        const member = await WorkspaceMember.findOne({
            workspaceId: wsId,
            userId: new mongoose.Types.ObjectId(userId)
        });

        if (!member) {
            return res.status(403).json({ error: 'Access denied to this workspace' });
        }

        // 4. Load Workspace Metadata
        const workspace = await Workspace.findById(wsId);
        if (!workspace || workspace.status === 'suspended') {
            return res.status(403).json({ error: 'Workspace unavailable' });
        }

        // 5. Inject Context
        req.workspace = workspace;
        req.workspaceMember = member;

        next();
    } catch (e) {
        console.error('Workspace Middleware Error', e);
        return res.status(400).json({ error: 'Invalid Workspace ID' });
    }
}

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { config } from '../config';

export interface AuthPayload {
  sub: string;
  role: 'OWNER' | 'ADMIN' | 'USER';
}

export function authenticate(req: Request, res: Response, next: NextFunction) {
  // FALLBACK: Only allow bypass if explicitly check env var, NO HARDCODED TOKENS.
  if (process.env.ENABLE_AUTH_BYPASS === 'true') {
    (req as any).auth = { sub: 'offline_admin', role: 'OWNER' };
    return next();
  }

  const header = req.headers.authorization;
  if (!header || !header.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  const token = header.slice('Bearer '.length);
  try {
    const payload = jwt.verify(token, config.jwtSecret) as AuthPayload;
    (req as any).auth = payload;
    return next();
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

export function authenticateOptional(req: Request, res: Response, next: NextFunction) {
  if (process.env.ENABLE_AUTH_BYPASS === 'true') {
    (req as any).auth = { sub: 'offline_admin', role: 'OWNER' };
    return next();
  }

  const header = req.headers.authorization;
  if (!header || !header.startsWith('Bearer ')) {
    return next();
  }
  const token = header.slice('Bearer '.length);
  try {
    const payload = jwt.verify(token, config.jwtSecret) as AuthPayload;
    (req as any).auth = payload;
    return next();
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

/**
 * Long-Term Memory System
 * Vector-based memory storage for conversation history and user preferences
 */

import fs from 'fs/promises';
import path from 'path';

export interface MemoryEntry {
    id: string;
    userId: string;
    type: 'conversation' | 'preference' | 'fact' | 'file' | 'code';
    content: string;
    metadata: Record<string, any>;
    embedding?: number[]; // Will be generated later when we add vector DB
    timestamp: number;
    importance: number; // 0-1, higher = more important
    accessCount: number;
    lastAccessed: number;
}

export interface UserProfile {
    userId: string;
    name?: string;
    preferences: {
        language?: 'ar' | 'en' | 'mixed';
        programmingLanguages?: string[];
        frameworks?: string[];
        codeStyle?: string;
        projectTypes?: string[];
    };
    facts: Map<string, any>; // Known facts about user
    conversationSummaries: string[];
    createdAt: number;
    updatedAt: number;
}

class LongTermMemory {
    private memoryStore: Map<string, MemoryEntry[]> = new Map(); // userId -> memories
    private profiles: Map<string, UserProfile> = new Map(); // userId -> profile
    private memoryDir: string;

    constructor(memoryDir: string = './data/memory') {
        this.memoryDir = memoryDir;
        this.initialize();
    }

    private async initialize() {
        try {
            await fs.mkdir(this.memoryDir, { recursive: true });
            await this.loadFromDisk();
        } catch (error) {
            console.error('[LongTermMemory] Initialization failed:', error);
        }
    }

    /**
     * Store a new memory
     */
    async remember(userId: string, entry: Omit<MemoryEntry, 'id' | 'userId' | 'timestamp' | 'accessCount' | 'lastAccessed'>): Promise<void> {
        const memory: MemoryEntry = {
            ...entry,
            id: `mem_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
            userId,
            timestamp: Date.now(),
            accessCount: 0,
            lastAccessed: Date.now()
        };

        if (!this.memoryStore.has(userId)) {
            this.memoryStore.set(userId, []);
        }

        const userMemories = this.memoryStore.get(userId)!;
        userMemories.push(memory);

        // Keep only last 1000 memories per user
        if (userMemories.length > 1000) {
            userMemories.shift();
        }

        await this.saveToDisk(userId);
    }

    /**
     * Recall memories relevant to a query
     */
    async recall(userId: string, query: string, limit: number = 10): Promise<MemoryEntry[]> {
        const userMemories = this.memoryStore.get(userId) || [];

        if (userMemories.length === 0) return [];

        // Simple keyword matching (will be replaced with vector similarity later)
        const queryLower = query.toLowerCase();
        const queryWords = queryLower.split(/\s+/).filter(w => w.length > 2);

        const scored = userMemories.map(memory => {
            const contentLower = memory.content.toLowerCase();

            // Calculate relevance score
            let score = 0;

            // Keyword matching
            for (const word of queryWords) {
                if (contentLower.includes(word)) {
                    score += 2;
                }
            }

            // Recency bonus (newer = better)
            const ageHours = (Date.now() - memory.timestamp) / (1000 * 60 * 60);
            score += Math.max(0, 1 - (ageHours / 168)); // Decay over 1 week

            // Importance bonus
            score += memory.importance * 3;

            // Access frequency bonus
            score += Math.min(memory.accessCount / 10, 1);

            return { memory, score };
        });

        // Sort by score and return top results
        const ranked = scored
            .filter(s => s.score > 0)
            .sort((a, b) => b.score - a.score)
            .slice(0, limit)
            .map(s => s.memory);

        // Update access counters
        for (const memory of ranked) {
            memory.accessCount++;
            memory.lastAccessed = Date.now();
        }

        return ranked;
    }

    /**
     * Get or create user profile
     */
    async getProfile(userId: string): Promise<UserProfile> {
        if (!this.profiles.has(userId)) {
            const profile: UserProfile = {
                userId,
                preferences: {} as UserProfile['preferences'],
                facts: new Map(),
                conversationSummaries: [],
                createdAt: Date.now(),
                updatedAt: Date.now()
            };
            this.profiles.set(userId, profile);
            await this.saveProfile(userId);
        }

        return this.profiles.get(userId)!;
    }

    /**
     * Update user profile
     */
    async updateProfile(userId: string, updates: Partial<UserProfile>): Promise<void> {
        const profile = await this.getProfile(userId);

        Object.assign(profile, updates);
        profile.updatedAt = Date.now();

        await this.saveProfile(userId);
    }

    /**
     * Learn from conversation
     */
    async learnFromConversation(userId: string, messages: any[]): Promise<void> {
        const profile = await this.getProfile(userId);

        // Extract learnings
        for (const msg of messages) {
            if (msg.role !== 'user') continue;

            const content = typeof msg.content === 'string' ? msg.content : JSON.stringify(msg.content);

            // Learn name
            const nameMatch = content.match(/(?:اسمي|انا|أنا|name is|i am|i'm)\s+([أ-يa-z]+)/i);
            if (nameMatch) {
                profile.name = nameMatch[1];
                profile.facts.set('name', nameMatch[1]);
            }

            // Learn programming preferences
            const progLangs = content.match(/\b(javascript|typescript|python|java|golang|rust|c\+\+|react|vue|angular)\b/gi);
            if (progLangs) {
                profile.preferences.programmingLanguages = [
                    ...(profile.preferences.programmingLanguages || []),
                    ...progLangs.map((l: string) => l.toLowerCase())
                ];
                // Remove duplicates
                profile.preferences.programmingLanguages = Array.from(new Set(profile.preferences.programmingLanguages));
            }

            // Learn project types
            if (/\b(website|web app|api|mobile app)\b/i.test(content)) {
                const type = content.match(/\b(website|web app|api|mobile app)\b/i)?.[0].toLowerCase();
                if (type) {
                    profile.preferences.projectTypes = [
                        ...(profile.preferences.projectTypes || []),
                        type
                    ];
                    profile.preferences.projectTypes = Array.from(new Set(profile.preferences.projectTypes));
                }
            }

            // Store important conversations
            if (content.length > 50) {
                await this.remember(userId, {
                    type: 'conversation',
                    content: content.substring(0, 500),
                    metadata: { timestamp: Date.now() },
                    importance: 0.5
                });
            }
        }

        await this.updateProfile(userId, profile);
    }

    /**
     * Get conversation summary for context
     */
    async getContextSummary(userId: string): Promise<string> {
        const profile = await this.getProfile(userId);
        const recentMemories = await this.recall(userId, '', 5);

        const parts: string[] = [];

        if (profile.name) {
            parts.push(`User name: ${profile.name}`);
        }

        if (profile.preferences.programmingLanguages?.length) {
            parts.push(`Prefers: ${profile.preferences.programmingLanguages.join(', ')}`);
        }

        if (recentMemories.length > 0) {
            parts.push(`Recent context: ${recentMemories.map(m => m.content.substring(0, 100)).join('; ')}`);
        }

        return parts.join(' | ');
    }

    /**
     * Save memories to disk
     */
    private async saveToDisk(userId: string): Promise<void> {
        try {
            const userMemories = this.memoryStore.get(userId) || [];
            const filePath = path.join(this.memoryDir, `${userId}.json`);
            await fs.writeFile(filePath, JSON.stringify(userMemories, null, 2));
        } catch (error) {
            console.error('[LongTermMemory] Save failed:', error);
        }
    }

    /**
     * Save profile to disk
     */
    private async saveProfile(userId: string): Promise<void> {
        try {
            const profile = this.profiles.get(userId);
            if (!profile) return;

            // Convert Map to Object for JSON
            const serializable = {
                ...profile,
                facts: Object.fromEntries(profile.facts)
            };

            const filePath = path.join(this.memoryDir, `${userId}_profile.json`);
            await fs.writeFile(filePath, JSON.stringify(serializable, null, 2));
        } catch (error) {
            console.error('[LongTermMemory] Profile save failed:', error);
        }
    }

    /**
     * Load memories from disk
     */
    private async loadFromDisk(): Promise<void> {
        try {
            const files = await fs.readdir(this.memoryDir);

            for (const file of files) {
                if (file.endsWith('_profile.json')) {
                    const userId = file.replace('_profile.json', '');
                    const content = await fs.readFile(path.join(this.memoryDir, file), 'utf-8');
                    if (!content || content.trim() === '') continue;
                    try {
                        const data = JSON.parse(content);
                        this.profiles.set(userId, {
                            ...data,
                            facts: new Map(Object.entries(data.facts || {}))
                        });
                    } catch (e) {
                        console.warn(`[LongTermMemory] Failed to parse profile: ${file}`, e);
                    }
                } else if (file.endsWith('.json')) {
                    const userId = file.replace('.json', '');
                    const content = await fs.readFile(path.join(this.memoryDir, file), 'utf-8');
                    if (!content || content.trim() === '') continue;
                    try {
                        const memories = JSON.parse(content);
                        this.memoryStore.set(userId, memories);
                    } catch (e) {
                        console.warn(`[LongTermMemory] Failed to parse memory file: ${file}`, e);
                    }
                }
            }

            console.info(`[LongTermMemory] Loaded ${this.profiles.size} profiles and ${this.memoryStore.size} memory stores`);
        } catch (error) {
            console.error('[LongTermMemory] Load failed:', error);
        }
    }
}

// Singleton instance
export const longTermMemory = new LongTermMemory();

export default longTermMemory;

import OpenAI from 'openai';
import path from 'path';
import fs from 'fs';

const OPENAI_API_KEY = process.env.OPENAI_API_KEY;
const MEMORY_DB_PATH = path.join(process.cwd(), 'data', 'lance_memory');

if (!fs.existsSync(path.dirname(MEMORY_DB_PATH))) {
    fs.mkdirSync(path.dirname(MEMORY_DB_PATH), { recursive: true });
}

interface MemoryRecord {
    id: string;
    vector: number[];
    text: string;
    metadata: string; // LanceDB handles complex types best if serialized or specific columns
    timestamp: number;
}

export class VectorMemory {
    private openai: OpenAI | null = null;
    private db: any = null;
    private table: any = null;
    private tableName = 'joe_memory';

    constructor() {
        if (OPENAI_API_KEY) {
            this.openai = new OpenAI({ apiKey: OPENAI_API_KEY });
        }
    }

    async init() {
        try {
            console.log('[VectorMemory] Attempting to load LanceDB...');
            const lancedb = require('@lancedb/lancedb');

            this.db = await lancedb.connect(MEMORY_DB_PATH);

            const existingTables = await this.db.tableNames();

            if (existingTables.includes(this.tableName)) {
                this.table = await this.db.openTable(this.tableName);
            } else {
                // Initial schema creation with a dummy row to define types, then delete it or keep it?
                // LanceDB usually infers from data. We can pass a schema but infer is easier for JS.
                // We'll lazy init on first add if not exists, OR create with empty data if possible.
                // For simplified flow: We won't create 'table' here if it doesn't exist.
                // We will handle it in `add`.
                console.log('[VectorMemory] Table does not exist yet. Will create on first add.');
            }

            console.log(`[VectorMemory] Connected to LanceDB at ${MEMORY_DB_PATH}`);
        } catch (e) {
            console.error('[VectorMemory] Failed to init LanceDB (Module might be missing or broken). Memory features disabled.', e);
        }
    }

    async createEmbedding(text: string): Promise<number[]> {
        if (!this.openai) {
            throw new Error('[VectorMemory] OpenAI API key not configured. Memory features unavailable.');
        }
        try {
            const response = await this.openai.embeddings.create({
                model: "text-embedding-3-small",
                input: text,
                encoding_format: "float",
            });
            return response.data[0].embedding;
        } catch (e) {
            console.error('[VectorMemory] Embedding failed:', e);
            throw new Error(`Failed to create embedding: ${e instanceof Error ? e.message : 'Unknown error'}`);
        }
    }

    async add(id: string, text: string, metadata: Record<string, any> = {}) {
        if (!this.db) await this.init();
        if (!this.db) {
            throw new Error('[VectorMemory] Database not available. Cannot add memory.');
        }

        const vector = await this.createEmbedding(text);
        const record = {
            id,
            vector,
            text,
            metadata: JSON.stringify(metadata),
            timestamp: Date.now()
        };

        if (!this.table) {
            const tables = await this.db.tableNames();
            if (tables.includes(this.tableName)) {
                this.table = await this.db.openTable(this.tableName);
            } else {
                this.table = await this.db.createTable(this.tableName, [record]);
                return; // Created with the record
            }
        }

        // Add to existing
        await this.table.add([record]);
    }

    async search(query: string, limit: number = 5) {
        if (!this.db) await this.init();
        if (!this.table || !this.db) {
            // Table doesn't exist = no memory
            return { ids: [[]], documents: [[]], distances: [[]] };
        }

        const queryVector = await this.createEmbedding(query);

        try {
            const results = await this.table.vectorSearch(queryVector)
                .limit(limit)
                .toArray();

            // Map to old API format for compatibility
            const ids = results.map((r: any) => r.id as string);
            const docs = results.map((r: any) => r.text as string);
            // LanceDB returns 'score' or '_distance' depending on version/config. 
            // Usually '_distance'. Lower is better (L2) or Higher (Cosine)? 
            // Default is usually L2. We need to check docs or observe.
            // Assuming Euclidean distance for now (lower is better).
            // We'll normalize or just pass it through.
            const dists = results.map((r: any) => (r._distance || 0) as number);

            return {
                ids: [ids],
                documents: [docs],
                distances: [dists] // Note: Metrics might differ from Cosine Sim
            };
        } catch (e) {
            console.error('[VectorMemory] Search failed:', e);
            return { ids: [[]], documents: [[]], distances: [[]] };
        }
    }
}

