    }

    /**
     * NEW: Build synonym map for keyword expansion
     */
    private buildSynonymMap() {
        this.synonymMap.set('bank', ['ledger', 'finance', 'transaction', 'payment', 'money']);
        this.synonymMap.set('بنك', ['معاملات', 'مالية', 'حساب', 'تحويل']);
