        const completion = await this.openai.chat.completions.create({
            model: "gpt-4o",
            messages: [{ role: 'system', content: systemPrompt }],
            temperature: 0.7,
        });

        return completion.choices[0].message.content || 'Failed to generate plan.';
    }
}

