      value: formatNumber(brainStats?.reflexCount || 0),

      icon: Brain,
      color: isLearning ? 'text-purple-500' : 'text-gray-500',
      bg: isLearning ? 'bg-purple-500/10' : 'bg-gray-500/10',
      suffix: isLearning ? ' (Learning)' : ' (Paused)'
