                description: 'Initial delay in ms (default: 1000)'
            },
            maxDelay: {
                type: 'number' as const,
                description: 'Maximum delay in ms (default: 30000)'
            },
            backoffMultiplier: {
                type: 'number' as const,
                description: 'Backoff multiplier (default: 2)'
            },
            operation: {
                type: 'object' as const,
                description: 'Operation to retry',
                properties: {
                    type: { type: 'string' as const },
                    params: { type: 'object' as const }
                }
            }
        },
        required: ['action']
    };

    outputSchema = {
        type: 'object' as const,
        properties: {
            success: { type: 'boolean' as const },
            attempts: { type: 'number' as const },
            result: { type: 'object' as const },
            stats: { type: 'object' as const }
        }
    };

    permissions = [];
    sideEffects = ['execute' as const];
    rateLimitPerMinute = 30;
    auditFields = ['action', 'operationId'];
    mockSupported = false;

    // In-memory retry configuration and stats
    private static configs = new Map<string, {
        maxAttempts: number;
        initialDelay: number;
        maxDelay: number;
        backoffMultiplier: number;
    }>();

    private static stats = new Map<string, {
        totalAttempts: number;
        successfulRetries: number;
        failedRetries: number;
        averageAttempts: number;
    }>();

    async execute(input: { action: string; operationId?: string; maxAttempts?: number; initialDelay?: number; maxDelay?: number; backoffMultiplier?: number; operation?: any }) {
        const { action, operationId, maxAttempts, initialDelay, maxDelay, backoffMultiplier, operation } = input;
        const logs: string[] = [];

        try {
            logs.push(`RetryManager: ${action}`);

            switch (action) {
                case 'configure':
                    return this.configureRetry(operationId || 'default', maxAttempts, initialDelay, maxDelay, backoffMultiplier, logs);

                case 'execute':
                    return this.executeWithRetry(operationId || 'default', operation, logs);

                case 'stats':
                    return this.getStats(operationId, logs);

                default:
                    throw new Error(`Unknown action: ${action}`);
            }

        } catch (error: any) {
            logs.push(`Error: ${error.message}`);
            return {
                ok: false,
                error: error.message,
                logs
            };
        }
    }

    private configureRetry(operationId: string, maxAttempts: number | undefined, initialDelay: number | undefined, maxDelay: number | undefined, backoffMultiplier: number | undefined, logs: string[]) {
        const config = {
            maxAttempts: maxAttempts || 3,
            initialDelay: initialDelay || 1000,
            maxDelay: maxDelay || 30000,
            backoffMultiplier: backoffMultiplier || 2
        };

        RetryManagerTool.configs.set(operationId, config);

        logs.push(`Configured retry for ${operationId}: ${config.maxAttempts} attempts, ${config.initialDelay}ms initial delay`);

        return {
            ok: true,
            output: {
                success: true,
                operationId,
                config,
                message: `Retry configuration set for ${operationId}`
            },
            logs
        };
    }

    private async executeWithRetry(operationId: string, operation: any, logs: string[]) {
        const config = RetryManagerTool.configs.get(operationId) || {
            maxAttempts: 3,
            initialDelay: 1000,
            maxDelay: 30000,
            backoffMultiplier: 2
        };

        let attempts = 0;
        let lastError: any = null;
        let delay = config.initialDelay;

        while (attempts < config.maxAttempts) {
            attempts++;
            logs.push(`Attempt ${attempts}/${config.maxAttempts}`);

            try {
                // Simulate operation execution
                // In production, this would call the actual operation
                const result = await this.simulateOperation(operation);

                // Update stats
                this.updateStats(operationId, attempts, true);

                logs.push(`Operation succeeded on attempt ${attempts}`);

                return {
                    ok: true,
                    output: {
                        success: true,
                        attempts,
                        result,
                        message: `Operation succeeded after ${attempts} attempt(s)`
                    },
                    logs
                };

            } catch (error: any) {
                lastError = error;
                logs.push(`Attempt ${attempts} failed: ${error.message}`);

                if (attempts < config.maxAttempts) {
                    logs.push(`Waiting ${delay}ms before retry...`);
                    await this.sleep(delay);
                    delay = Math.min(delay * config.backoffMultiplier, config.maxDelay);
                }
            }
        }

        // All attempts failed
        this.updateStats(operationId, attempts, false);

        logs.push(`All ${attempts} attempts failed`);

        return {
            ok: false,
            error: `Operation failed after ${attempts} attempts: ${lastError?.message || 'Unknown error'}`,
            output: {
                success: false,
                attempts,
                lastError: lastError?.message
            },
            logs
        };
    }

    private async simulateOperation(operation: any): Promise<any> {
        // Simulate operation with 70% success rate
        const random = Math.random();
        if (random > 0.7) {
            throw new Error('Simulated operation failure');
        }

        return {
            status: 'success',
            data: operation?.params || {},
            timestamp: new Date().toISOString()
        };
    }

    private sleep(ms: number): Promise<void> {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    private updateStats(operationId: string, attempts: number, success: boolean) {
        const stats = RetryManagerTool.stats.get(operationId) || {
            totalAttempts: 0,
            successfulRetries: 0,
            failedRetries: 0,
            averageAttempts: 0
        };

        stats.totalAttempts += attempts;
        if (success) {
            stats.successfulRetries++;
        } else {
            stats.failedRetries++;
        }

        const totalOperations = stats.successfulRetries + stats.failedRetries;
        stats.averageAttempts = stats.totalAttempts / totalOperations;

        RetryManagerTool.stats.set(operationId, stats);
    }

    private getStats(operationId: string | undefined, logs: string[]) {
        if (operationId) {
            const stats = RetryManagerTool.stats.get(operationId);
            if (!stats) {
                throw new Error(`No stats found for operation ${operationId}`);
            }

            logs.push(`Retrieved stats for ${operationId}`);

            return {
                ok: true,
                output: {
                    success: true,
                    operationId,
                    stats
                },
                logs
            };
        }

        // Return all stats
        const allStats = Object.fromEntries(RetryManagerTool.stats);

        logs.push(`Retrieved stats for ${Object.keys(allStats).length} operations`);

        return {
            ok: true,
            output: {
                success: true,
                stats: allStats
            },
            logs
        };
    }
}

import { ToolDefinition } from '../types';
import { callLLM } from '../../llm';

/**
 * RequestAnalyzerTool - Advanced request analysis using LLM
 * Analyzes complex build requests to extract requirements, modules, and complexity
 */
export class RequestAnalyzerTool implements ToolDefinition {
    name = 'request_analyzer';
    version = '1.0.0';
    description = 'Analyze complex build requests to extract requirements, modules, and estimate complexity';
    tags = ['analysis', 'planning', 'llm'];

    inputSchema = {
        type: 'object' as const,
        properties: {
            userRequest: {
                type: 'string' as const,
                description: 'The user\'s build request to analyze'
            },
            context: {
                type: 'object' as const,
                description: 'Optional context (session info, previous messages, etc.)',
                properties: {
                    sessionId: { type: 'string' as const },
                    previousMessages: {
                        type: 'array' as const,
                        items: { type: 'object' as const },
                        description: 'Previous conversation messages'
                    }
                }
            }
        },
        required: ['userRequest']
    };

    outputSchema = {
        type: 'object' as const,
        properties: {
            projectType: { type: 'string' as const },
            complexity: { type: 'string' as const },
            modules: { type: 'array' as const },
            estimatedFiles: { type: 'number' as const },
            techStack: { type: 'object' as const },
            requirements: { type: 'array' as const }
        }
    };

    permissions = [];
    sideEffects = [];
    rateLimitPerMinute = 10; // Limit LLM calls
    auditFields = ['userRequest'];
    mockSupported = false;

    async execute(input: { userRequest: string; context?: any }) {
        const { userRequest, context } = input;
        const logs: string[] = [];

        try {
            logs.push(`Analyzing request: "${userRequest.slice(0, 100)}..."`);

            // Construct analysis prompt
            const analysisPrompt = `You are an expert software architect. Analyze the following build request and provide a structured analysis.

USER REQUEST:
${userRequest}

Provide your analysis in the following JSON format:
{
  "projectType": "fullstack|api|website|dashboard|cms|ecommerce|mobile|other",
  "complexity": "simple|medium|complex|very_complex",
  "estimatedFiles": <number>,
  "modules": ["module1", "module2"],
  "techStack": {
    "frontend": "react|vue|angular|html|none",
    "backend": "node|python|java|none",
    "database": "mongodb|postgresql|mysql|none",
    "other": ["tool1", "tool2"]
  },
  "requirements": [
    {
      "category": "functional|technical|design",
      "description": "requirement description",
      "priority": "high|medium|low"
    }
  ],
  "phases": [
    {
      "name": "Phase name",
      "tasks": ["task1", "task2"],
      "estimatedTime": "X minutes"
    }
  ]
}

IMPORTANT: Return ONLY valid JSON, no markdown, no explanations.`;

            // Call LLM for analysis using correct signature
            const llmContext = [
                { role: 'system', content: 'You are a software architect that returns only valid JSON.' }
            ];

            const response = await callLLM(analysisPrompt, llmContext);

            logs.push(`LLM analysis completed`);

            // Parse LLM response
            let analysis;
            try {
                // Extract JSON from response (in case LLM adds markdown)
                const jsonMatch = response.match(/\{[\s\S]*\}/);
                const jsonStr = jsonMatch ? jsonMatch[0] : response;
                analysis = JSON.parse(jsonStr);
            } catch (parseError) {
                logs.push(`JSON parse error: ${parseError}`);
                // Fallback to basic analysis
                analysis = this.fallbackAnalysis(userRequest);
            }

            // Validate and enrich analysis
            analysis = this.validateAnalysis(analysis, userRequest);

            logs.push(`Analysis complete: ${analysis.projectType}, ${analysis.complexity}, ${analysis.modules.length} modules`);

            return {
                ok: true,
                output: analysis,
                logs
            };

        } catch (error: any) {
            logs.push(`Error: ${error.message}`);
            return {
                ok: false,
                error: error.message,
                output: this.fallbackAnalysis(userRequest),
                logs
            };
        }
    }

    /**
     * Fallback analysis when LLM fails
     */
    private fallbackAnalysis(userRequest: string): any {
        const text = userRequest.toLowerCase();

        // Simple keyword-based detection
        const hasAuth = /auth|login|register|signup/i.test(text);
        const hasDatabase = /database|mongodb|postgres|sql|data/i.test(text);
        const hasUI = /ui|interface|dashboard|page|component/i.test(text);
        const hasAPI = /api|endpoint|rest|graphql/i.test(text);

        const modules: string[] = [];
        if (hasAuth) modules.push('authentication');
        if (hasDatabase) modules.push('database');
        if (hasUI) modules.push('ui');
        if (hasAPI) modules.push('api');

        // Estimate complexity based on keywords
        const complexityScore = modules.length +
            (text.split('module').length - 1) +
            (text.split('feature').length - 1);

        const complexity = complexityScore < 3 ? 'simple' :
            complexityScore < 6 ? 'medium' :
                complexityScore < 10 ? 'complex' : 'very_complex';

        return {
            projectType: hasUI && hasAPI ? 'fullstack' : hasAPI ? 'api' : 'website',
            complexity,
            modules,
            estimatedFiles: modules.length * 5,
            techStack: {
                frontend: hasUI ? 'react' : 'none',
                backend: hasAPI ? 'node' : 'none',
                database: hasDatabase ? 'mongodb' : 'none',
                other: []
            },
            requirements: [],
            phases: [],
            fallback: true
        };
    }

    /**
     * Validate and ensure analysis has required fields
     */
    private validateAnalysis(analysis: any, userRequest: string): any {
        return {
            projectType: analysis.projectType || 'other',
            complexity: analysis.complexity || 'medium',
            modules: Array.isArray(analysis.modules) ? analysis.modules : [],
            estimatedFiles: typeof analysis.estimatedFiles === 'number' ? analysis.estimatedFiles : 10,
            techStack: analysis.techStack || { frontend: 'none', backend: 'none', database: 'none', other: [] },
            requirements: Array.isArray(analysis.requirements) ? analysis.requirements : [],
            phases: Array.isArray(analysis.phases) ? analysis.phases : [],
            originalRequest: userRequest.slice(0, 200)
        };
    }
}

import { BaseTool } from '../base';
import { ToolPermission } from '../types';
import { exec } from 'child_process';
import { promisify } from 'util';

const execAsync = promisify(exec);

export class SonarAnalysisTool extends BaseTool {
    name = 'sonar_analysis';
    description = 'Run Static Code Analysis using SonarScanner (or mock if missing).';
    version = '1.0.0';
    tags = ['quality', 'security', 'static-analysis'];
    inputSchema = {
        type: 'object' as const,
        properties: {
            projectKey: { type: 'string' },
            sources: { type: 'string', default: '.' }
        },
        required: ['projectKey']
    };
    outputSchema = { type: 'object' as const, properties: { summary: { type: 'string' } } };
    permissions: ToolPermission[] = ['execute', 'internet'];
    sideEffects: ToolPermission[] = ['execute'];

    async execute(input: any) {
        // Check if sonar-scanner exists
        try {
            const key = input.projectKey;
            // Assume sonar-scanner is in path or use npx sonar-scanner
            // For now, we'll try to run it, if it fails, we report that it needs installation
            const cmd = `npx sonar-scanner -Dsonar.projectKey=${key} -Dsonar.sources=${input.sources}`;
            const { stdout } = await execAsync(cmd);
            return { ok: true, output: { summary: stdout.slice(0, 2000) }, logs: ['sonar scan complete'] };
        } catch (e: any) {
            if (String(e.message).includes('command not found') || String(e.message).includes('ENOENT')) {
                return { ok: false, error: 'sonar-scanner/npx not available. Please install dependencies.', logs: [] };
            }
            return { ok: false, error: `Sonar failed: ${e.message}`, logs: [] };
        }
    }
}

export class DependencyAuditorTool extends BaseTool {
    name = 'dependency_auditor';
    description = 'Check project dependencies for known security vulnerabilities.';
    version = '1.0.0';
    tags = ['security', 'dependencies'];
    inputSchema = {
        type: 'object' as const,
        properties: {
            packageManager: { type: 'string', enum: ['npm', 'yarn', 'pnpm'], default: 'npm' }
        }
