import { ToolDefinition } from '../types';

/**
 * LoggerTool - Structured logging with levels and rotation
 * Provides comprehensive logging capabilities for production systems
 */
export class LoggerTool implements ToolDefinition {
    name = 'logger';
    version = '1.0.0';
    description = 'Structured logging system with log levels, rotation, and filtering';
    tags = ['logging', 'monitoring', 'debugging'];

    inputSchema = {
        type: 'object' as const,
        properties: {
            action: {
                type: 'string' as const,
                enum: ['log', 'query', 'clear', 'stats'],
                description: 'Action to perform'
            },
            level: {
                type: 'string' as const,
                enum: ['debug', 'info', 'warn', 'error', 'fatal'],
                description: 'Log level'
            },
            message: {
                type: 'string' as const,
                description: 'Log message'
            },
            metadata: {
                type: 'object' as const,
                description: 'Additional metadata to log'
            },
            filter: {
                type: 'object' as const,
                description: 'Filter criteria for querying logs',
                properties: {
                    level: { type: 'string' as const },
                    startTime: { type: 'string' as const },
                    endTime: { type: 'string' as const },
                    limit: { type: 'number' as const }
                }
            }
        },
        required: ['action']
    };

    outputSchema = {
        type: 'object' as const,
        properties: {
            success: { type: 'boolean' as const },
            logId: { type: 'string' as const },
            logs: { type: 'array' as const },
            stats: { type: 'object' as const }
        }
    };

    permissions = [];
    sideEffects = ['write' as const];
    rateLimitPerMinute = 100;
    auditFields = ['action', 'level'];
    mockSupported = false;

    // In-memory log storage (in production, use database or log aggregation service)
    private static logs: Array<{
        id: string;
        level: string;
        message: string;
        metadata: any;
        timestamp: string;
    }> = [];

    private static maxLogs = 10000; // Maximum logs to keep in memory
    private static levelPriority = {
        debug: 0,
        info: 1,
        warn: 2,
        error: 3,
        fatal: 4
    };

    async execute(input: { action: string; level?: string; message?: string; metadata?: any; filter?: any }) {
        const { action, level, message, metadata, filter } = input;
        const logs: string[] = [];

        try {
            logs.push(`Logger: ${action}`);

            switch (action) {
                case 'log':
                    return this.logMessage(level || 'info', message || '', metadata, logs);

                case 'query':
                    return this.queryLogs(filter, logs);

                case 'clear':
                    return this.clearLogs(logs);

                case 'stats':
                    return this.getStats(logs);

                default:
                    throw new Error(`Unknown action: ${action}`);
            }

        } catch (error: any) {
            logs.push(`Error: ${error.message}`);
            return {
                ok: false,
                error: error.message,
                logs
            };
        }
    }

    private logMessage(level: string, message: string, metadata: any, logs: string[]) {
        const logId = `log_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
        const timestamp = new Date().toISOString();

        const logEntry = {
            id: logId,
            level,
            message,
            metadata: metadata || {},
            timestamp
        };

        LoggerTool.logs.push(logEntry);

        // Rotate logs if exceeding max
        if (LoggerTool.logs.length > LoggerTool.maxLogs) {
            LoggerTool.logs = LoggerTool.logs.slice(-LoggerTool.maxLogs);
            logs.push('Log rotation performed');
        }

        logs.push(`Logged [${level.toUpperCase()}]: ${message}`);

        return {
            ok: true,
            output: {
                success: true,
                logId,
                level,
                message,
                timestamp
            },
            logs
        };
    }

    private queryLogs(filter: any, logs: string[]) {
        let filteredLogs = [...LoggerTool.logs];

        if (filter) {
            if (filter.level) {
                filteredLogs = filteredLogs.filter(log => log.level === filter.level);
            }

            if (filter.startTime) {
                const startTime = new Date(filter.startTime).getTime();
                filteredLogs = filteredLogs.filter(log => new Date(log.timestamp).getTime() >= startTime);
            }

            if (filter.endTime) {
                const endTime = new Date(filter.endTime).getTime();
                filteredLogs = filteredLogs.filter(log => new Date(log.timestamp).getTime() <= endTime);
            }

            if (filter.limit && filter.limit > 0) {
                filteredLogs = filteredLogs.slice(-filter.limit);
            }
        }

        logs.push(`Query returned ${filteredLogs.length} logs`);

        return {
            ok: true,
            output: {
                success: true,
                logs: filteredLogs,
                count: filteredLogs.length
            },
            logs
        };
    }

    private clearLogs(logs: string[]) {
        const count = LoggerTool.logs.length;
        LoggerTool.logs = [];

        logs.push(`Cleared ${count} logs`);

        return {
            ok: true,
            output: {
                success: true,
                clearedCount: count,
                message: `Cleared ${count} logs`
            },
            logs
        };
    }

    private getStats(logs: string[]) {
        const stats = {
            totalLogs: LoggerTool.logs.length,
            byLevel: {} as Record<string, number>,
            oldestLog: LoggerTool.logs[0]?.timestamp || null,
            newestLog: LoggerTool.logs[LoggerTool.logs.length - 1]?.timestamp || null
        };

        // Count logs by level
        LoggerTool.logs.forEach(log => {
            stats.byLevel[log.level] = (stats.byLevel[log.level] || 0) + 1;
        });

        logs.push(`Stats: ${stats.totalLogs} total logs`);

        return {
            ok: true,
            output: {
                success: true,
                stats
            },
            logs
        };
    }
}

import { ToolDefinition } from '../types';
import crypto from 'crypto';

/**
 * LLMCacheTool - Cache for LLM responses
 * Reduces LLM costs by caching responses for identical prompts
 */
export class LLMCacheTool implements ToolDefinition {
    name = 'llm_cache';
    version = '1.0.0';
    description = 'Cache LLM responses to reduce costs and improve speed';
    tags = ['cache', 'llm', 'optimization', 'cost-reduction'];

    inputSchema = {
        type: 'object' as const,
        properties: {
            action: {
                type: 'string' as const,
                enum: ['get', 'set', 'stats', 'clear'],
                description: 'Cache action'
            },
            prompt: {
                type: 'string' as const,
                description: 'LLM prompt (for get/set)'
            },
            response: {
                type: 'string' as const,
                description: 'LLM response (for set)'
            },
            model: {
                type: 'string' as const,
                description: 'Model name (optional, for better cache key)'
            }
        },
        required: ['action']
    };

    outputSchema = {
        type: 'object' as const,
        properties: {
            success: { type: 'boolean' as const },
            cached: { type: 'boolean' as const },
            response: { type: 'string' as const }
        }
    };

    permissions = [];
    sideEffects = [];
    rateLimitPerMinute = 200;
    auditFields = ['action'];
    mockSupported = false;

    // LLM-specific cache
    private static cache = new Map<string, { response: string; timestamp: number; hits: number }>();
    private static stats = {
        hits: 0,
        misses: 0,
        sets: 0,
        totalSaved: 0, // Estimated tokens saved
        costSaved: 0   // Estimated cost saved ($)
    };

    async execute(input: { action: string; prompt?: string; response?: string; model?: string }) {
        const { action, prompt, response, model } = input;
        const logs: string[] = [];

        try {
            switch (action) {
                case 'get':
                    return this.getCached(prompt!, model, logs);

                case 'set':
                    return this.setCached(prompt!, response!, model, logs);

                case 'stats':
                    return this.getStats(logs);

                case 'clear':
                    return this.clearCache(logs);

                default:
                    throw new Error(`Unknown action: ${action}`);
            }

        } catch (error: any) {
            logs.push(`Error: ${error.message}`);
            return {
                ok: false,
                error: error.message,
                logs
            };
        }
    }

    private generateCacheKey(prompt: string, model?: string): string {
        const content = model ? `${model}:${prompt}` : prompt;
        return crypto.createHash('sha256').update(content).digest('hex');
    }

    private getCached(prompt: string, model: string | undefined, logs: string[]) {
        const key = this.generateCacheKey(prompt, model);
        const entry = LLMCacheTool.cache.get(key);

        if (!entry) {
            LLMCacheTool.stats.misses++;
            logs.push(`LLM cache miss`);
            return {
                ok: true,
                output: { success: true, cached: false, hit: false },
                logs
            };
        }

        // Update hit count
        entry.hits++;
        LLMCacheTool.stats.hits++;

        // Estimate tokens saved (rough: ~4 chars per token)
        const tokensSaved = Math.ceil(entry.response.length / 4);
        LLMCacheTool.stats.totalSaved += tokensSaved;

        // Estimate cost saved (rough: $0.002 per 1K tokens for GPT-3.5)
        const costSaved = (tokensSaved / 1000) * 0.002;
        LLMCacheTool.stats.costSaved += costSaved;

        logs.push(`LLM cache hit (saved ~${tokensSaved} tokens, ~$${costSaved.toFixed(4)})`);

        return {
            ok: true,
            output: {
                success: true,
                cached: true,
                hit: true,
                response: entry.response,
                hits: entry.hits,
                tokensSaved,
                costSaved: costSaved.toFixed(4)
            },
            logs
        };
    }

    private setCached(prompt: string, response: string, model: string | undefined, logs: string[]) {
        const key = this.generateCacheKey(prompt, model);

        LLMCacheTool.cache.set(key, {
            response,
            timestamp: Date.now(),
            hits: 0
        });

        LLMCacheTool.stats.sets++;
        logs.push(`LLM response cached (${response.length} chars)`);

        return {
            ok: true,
            output: { success: true, cached: true, key: key.substring(0, 8) },
            logs
        };
    }

    private getStats(logs: string[]) {
        const total = LLMCacheTool.stats.hits + LLMCacheTool.stats.misses;
        const hitRate = total > 0 ? (LLMCacheTool.stats.hits / total * 100).toFixed(2) : '0.00';

        const stats = {
            ...LLMCacheTool.stats,
            total,
            hitRate: `${hitRate}%`,
            cacheSize: LLMCacheTool.cache.size,
            estimatedCostSaved: `$${LLMCacheTool.stats.costSaved.toFixed(2)}`
        };

        logs.push(`LLM cache: ${hitRate}% hit rate, $${stats.costSaved.toFixed(2)} saved`);

        return {
            ok: true,
            output: { success: true, stats },
            logs
        };
    }

    private clearCache(logs: string[]) {
        const size = LLMCacheTool.cache.size;
        LLMCacheTool.cache.clear();

        logs.push(`LLM cache cleared: ${size} entries`);

        return {
            ok: true,
            output: { success: true, cleared: size },
            logs
        };
    }

    // Helper method to be used by llm.ts
    static async checkCache(prompt: string, model?: string): Promise<string | null> {
        const tool = new LLMCacheTool();
        const result = await tool.getCached(prompt, model, []);
        return result.output?.response || null;
    }

    static async saveToCache(prompt: string, response: string, model?: string): Promise<void> {
        const tool = new LLMCacheTool();
        await tool.setCached(prompt, response, model, []);
    }
}

