```typescript
const io = new Server(server);
io.on('connection', (socket) => {
  socket.on('join-room', (roomId) => {
    socket.join(roomId);
    socket.emit('joined', { timestamp: Date.now() });
  });

  socket.on('broadcast-action', (data) => {
    socket.to(data.roomId).emit('action-performed', data.payload);
  });
});
```

