                )}
            </AnimatePresence>
        </div>
    );
};

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    GitBranch, Plus, Minus, FileCode, Copy, Check,
    ChevronDown, ChevronUp
} from 'lucide-react';

export interface DiffLine {
    type: 'add' | 'remove' | 'context';
    content: string;
    lineNumber?: number;
}

export interface FileDiff {
    path: string;
    additions: number;
    deletions: number;
    lines: DiffLine[];
}

interface DiffViewerProps {
    diffs: FileDiff[];
    expanded: boolean;
    onToggle: () => void;
}

const DiffLineComponent: React.FC<{ line: DiffLine }> = ({ line }) => {
    const getBgColor = () => {
        switch (line.type) {
            case 'add': return 'bg-green-500/10';
            case 'remove': return 'bg-red-500/10';
            default: return 'bg-transparent';
        }
    };

    const getTextColor = () => {
        switch (line.type) {
            case 'add': return 'text-green-400';
            case 'remove': return 'text-red-400';
            default: return 'text-gray-400';
        }
    };

    const getIcon = () => {
        switch (line.type) {
            case 'add': return <Plus size={12} className="text-green-500" />;
            case 'remove': return <Minus size={12} className="text-red-500" />;
            default: return <span className="w-3" />;
        }
    };

    return (
        <div className={`flex font-mono text-xs leading-relaxed ${getBgColor()}`}>
            <div className="w-12 flex items-center justify-center flex-shrink-0 text-gray-600 border-r border-white/5">
                {line.lineNumber}
            </div>
            <div className="w-6 flex items-center justify-center flex-shrink-0">
                {getIcon()}
            </div>
            <div className={`flex py-0.5 pr-4 overflow-x-auto ${getTextColor()}`}>
                <pre className="whitespace-pre">{line.content || ' '}</pre>
            </div>
        </div>
    );
};

export const DiffViewer: React.FC<DiffViewerProps> = ({
    diffs,
    expanded,
    onToggle
}) => {
    const [copiedPath, setCopiedPath] = useState<string | null>(null);

    const copyPath = (path: string) => {
        navigator.clipboard.writeText(path);
        setCopiedPath(path);
        setTimeout(() => setCopiedPath(null), 2000);
    };

    const totalAdditions = diffs.reduce((sum, d) => sum + d.additions, 0);
    const totalDeletions = diffs.reduce((sum, d) => sum + d.deletions, 0);

    return (
        <div className="bg-black/40 backdrop-blur-xl border border-white/10 rounded-2xl overflow-hidden">
            <button
                onClick={onToggle}
                className="w-full p-4 flex items-center justify-between hover:bg-white/5 transition-all"
            >
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-green-500 to-emerald-500 flex items-center justify-center">
                        <GitBranch size={20} className="text-white" />
                    </div>
                    <div className="text-right">
                        <h3 className="text-sm font-bold text-white">التغييرات</h3>
                        <p className="text-xs text-gray-500">Visual Diff Viewer</p>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    <div className="flex items-center gap-2 text-xs">
                        <span className="text-green-400 flex items-center gap-1">
                            <Plus size={12} /> {totalAdditions}
                        </span>
                        <span className="text-red-400 flex items-center gap-1">
                            <Minus size={12} /> {totalDeletions}
                        </span>
                    </div>
                    {expanded ? <ChevronUp size={16} className="text-gray-500" /> : <ChevronDown size={16} className="text-gray-500" />}
                </div>
            </button>

            <AnimatePresence>
                {expanded && (
                    <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: 'auto', opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        className="border-t border-white/5"
                    >
                        {diffs.length === 0 ? (
                            <div className="p-8 text-center text-gray-500">
                                <GitBranch size={32} className="mx-auto mb-2 opacity-30" />
                                <p className="text-sm">لا توجد تغييرات بعد</p>
                            </div>
                        ) : (
                            <div className="divide-y divide-white/5">
                                {diffs.map((diff, idx) => (
                                    <div key={idx} className="bg-black/20">
                                        <div className="flex items-center justify-between p-3 border-b border-white/5 bg-gray-900/50">
                                            <div className="flex items-center gap-2">
                                                <FileCode size={14} className="text-cyan-400" />
                                                <span className="text-sm text-gray-300 font-mono">{diff.path.split('/').pop()}</span>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                <span className="text-xs text-green-400">+{diff.additions}</span>
                                                <span className="text-xs text-red-400">-{diff.deletions}</span>
                                                <button
                                                    onClick={() => copyPath(diff.path)}
                                                    className="p-1 rounded hover:bg-white/10 text-gray-500 hover:text-white transition-colors"
                                                >
                                                    {copiedPath === diff.path ? <Check size={12} className="text-green-400" /> : <Copy size={12} />}
                                                </button>
                                            </div>
                                        </div>

                                        <div className="max-h-60 overflow-y-auto">
                                            {diff.lines.map((line, lineIdx) => (
                                                <DiffLineComponent key={lineIdx} line={line} />
                                            ))}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

export default DiffViewer;

import React, { useState, useEffect } from 'react';
import { Image as ImageIcon, Sparkles, Loader, Download } from 'lucide-react';
import { useAgent } from '../hooks/useAgent';

export const CreativeStudio = () => {
    const { messages, status, sendMessage } = useAgent();
    const [prompt, setPrompt] = useState('');
    const [gallery, setGallery] = useState<string[]>([]);
    const [isGenerating, setIsGenerating] = useState(false);

    // Watch for new image URLs in messages
    useEffect(() => {
        const lastMsg = messages[messages.length - 1];
        if (lastMsg && lastMsg.role === 'assistant') {
            // Regex to find image urls (http/https ... .png/jpg/webp or from markdown)
            // Or just check if the message contains a URL and we just requested generation.

            // Allow loose matching for now
            const urlMatch = lastMsg.content.match(/https?:\/\/[^\s)]+/);
            if (urlMatch) {
                const url = urlMatch[0];
                // Avoid duplicates
                setGallery(prev => prev.includes(url) ? prev : [url, ...prev]);
                setIsGenerating(false);
            } else if (status === 'idle' && isGenerating) {
                // Agent finished but maybe didn't return a URL?
                setIsGenerating(false);
            }
        }
    }, [messages, status]);

    const handleGenerate = (e: React.FormEvent) => {
        e.preventDefault();
        if (!prompt.trim()) return;

        setIsGenerating(true);
        // Explicit instruction to use the tool
        sendMessage(`Generate a high-quality futuristic image based on this prompt: "${prompt}". Return just the URL.`);
    };

    return (
        <div className="glass-panel p-6 col-span-1 row-span-2 flex flex-col">
            <div className="flex items-center gap-2 mb-6">
                <ImageIcon className="text-pink-400" />
                <h2 className="font-bold text-lg neon-text text-pink-300">CREATIVE STUDIO</h2>
            </div>

            {/* Generator Input */}
            <form onSubmit={handleGenerate} className="mb-8">
                <label className="text-xs text-gray-400 uppercase tracking-wider mb-2 block">Prompt Engineering</label>
                <div className="relative">
                    <textarea
                        value={prompt}
                        onChange={(e) => setPrompt(e.target.value)}
                        placeholder="Describe the asset..."
                        className="w-full bg-black/40 border border-white/10 rounded-lg p-3 text-sm focus:border-pink-500/50 outline-none resize-none h-24"
                    />
                    <button
                        type="submit"
                        disabled={isGenerating || !prompt.trim()}
                        className="absolute bottom-2 right-2 bg-pink-600 hover:bg-pink-500 text-white p-2 rounded-md disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                    >
                        {isGenerating ? <Loader className="animate-spin" size={16} /> : <Sparkles size={16} />}
                    </button>
                </div>
            </form>

            {/* Gallery / Preview */}
            <div className="flex-1 overflow-y-auto pr-2">
                <h3 className="text-xs text-gray-400 uppercase tracking-wider mb-4">Recent Assets</h3>
                <div className="grid grid-cols-1 gap-4">
                    {gallery.length === 0 && !isGenerating && (
                        <div className="border border-dashed border-white/10 rounded-xl h-32 flex items-center justify-center text-gray-600 text-xs">
                            NO ASSETS GENERATED
                        </div>
                    )}

                    {gallery.map((url, idx) => (
                        <div key={idx} className="group relative rounded-xl overflow-hidden border border-white/10 aspect-video bg-black/50">
                            <img src={url} alt={`Generated ${idx}`} className="w-full h-full object-cover" />
                            <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
                                <a href={url} target="_blank" rel="noopener noreferrer" className="p-2 bg-white/10 hover:bg-white/20 rounded-full text-white">
                                    <Download size={16} />
                                </a>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    CheckCircle, AlertCircle, ChevronRight,
    Zap, Code, TestTube, Rocket, Sparkles
} from 'lucide-react';

export interface PipelineStage {
    id: string;
    name: string;
    nameAr: string;
    icon: React.ReactNode;
    status: 'pending' | 'running' | 'success' | 'error' | 'skipped';
    duration?: number;
    details?: string;
}

interface BuildPipelineProps {
    stages: PipelineStage[];
    currentStage?: string;
}

const defaultStages: PipelineStage[] = [
    { id: 'plan', name: 'Planning', nameAr: 'التخطيط', icon: <Sparkles size={16} />, status: 'pending' },
    { id: 'code', name: 'Coding', nameAr: 'البرمجة', icon: <Code size={16} />, status: 'pending' },
    { id: 'test', name: 'Testing', nameAr: 'الفحص', icon: <TestTube size={16} />, status: 'pending' },
    { id: 'deploy', name: 'Deploy', nameAr: 'النشر', icon: <Rocket size={16} />, status: 'pending' },
];

export const BuildPipeline: React.FC<BuildPipelineProps> = ({
    stages = defaultStages,
    currentStage: _currentStage
}) => {
    const getStatusColor = (status: string) => {
        switch (status) {
            case 'running': return 'from-cyan-500 to-blue-500';
            case 'success': return 'from-green-500 to-emerald-500';
            case 'error': return 'from-red-500 to-rose-500';
            case 'skipped': return 'from-gray-500 to-gray-600';
            default: return 'from-gray-700 to-gray-800';
        }
    };

    const activeIndex = stages.findIndex(s => s.status === 'running');
    const progress = activeIndex >= 0
        ? ((activeIndex + 0.5) / stages.length) * 100
        : stages.every(s => s.status === 'success') ? 100 : 0;

    return (
        <div className="bg-black/40 backdrop-blur-xl border border-white/10 rounded-2xl p-4 overflow-hidden">
            {/* Header */}
            <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-2">
                    <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-purple-500 to-pink-500 flex items-center justify-center">
                        <Zap size={16} className="text-white" />
                    </div>
                    <div>
                        <h3 className="text-sm font-bold text-white">خط البناء</h3>
                        <p className="text-xs text-gray-500">Build Pipeline</p>
                    </div>
                </div>
                <div className="text-xs text-gray-400">
                    {Math.round(progress)}% مكتمل
                </div>
            </div>

            {/* Progress Bar */}
            <div className="h-1.5 bg-gray-800 rounded-full mb-6 overflow-hidden">
                <motion.div
                    className="h-full bg-gradient-to-r from-cyan-500 via-purple-500 to-pink-500"
                    initial={{ width: 0 }}
                    animate={{ width: `${progress}%` }}
                    transition={{ duration: 0.5, ease: 'easeOut' }}
                />
            </div>

            {/* Stages */}
            <div className="flex items-center justify-between relative">
                {/* Connection Line */}
                <div className="absolute top-1/2 left-0 right-0 h-0.5 bg-gray-800 -translate-y-1/2 z-0" />

                {stages.map((stage, index) => (
                    <React.Fragment key={stage.id}>
                        <motion.div
                            className="relative z-10 flex flex-col items-center"
                            initial={{ scale: 0.8, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            transition={{ delay: index * 0.1 }}
                        >
                            {/* Stage Circle */}
                            <motion.div
                                className={`w-12 h-12 rounded-xl bg-gradient-to-br ${getStatusColor(stage.status)} 
                  flex items-center justify-center shadow-lg border-2 
                  ${stage.status === 'running' ? 'border-cyan-400 shadow-cyan-500/30' : 'border-transparent'}
                  transition-all duration-300`}
                                animate={stage.status === 'running' ? {
                                    boxShadow: ['0 0 20px rgba(6, 182, 212, 0.3)', '0 0 40px rgba(6, 182, 212, 0.5)', '0 0 20px rgba(6, 182, 212, 0.3)']
                                } : {}}
                                transition={{ duration: 1.5, repeat: Infinity }}
                            >
                                <div className="text-white">
                                    {stage.status === 'running' ? (
                                        <motion.div
                                            animate={{ rotate: 360 }}
                                            transition={{ duration: 2, repeat: Infinity, ease: 'linear' }}
                                        >
                                            {stage.icon}
                                        </motion.div>
                                    ) : stage.status === 'success' ? (
                                        <CheckCircle size={20} />
                                    ) : stage.status === 'error' ? (
                                        <AlertCircle size={20} />
                                    ) : (
                                        stage.icon
                                    )}
                                </div>
                            </motion.div>

                            {/* Stage Label */}
                            <div className="mt-2 text-center">
                                <p className={`text-xs font-medium ${stage.status === 'running' ? 'text-cyan-400' :
                                    stage.status === 'success' ? 'text-green-400' :
                                        stage.status === 'error' ? 'text-red-400' :
                                            'text-gray-500'
                                    }`}>
                                    {stage.nameAr}
                                </p>
                                {stage.duration && (
                                    <p className="text-[10px] text-gray-600 mt-0.5">
                                        {stage.duration.toFixed(1)}s
                                    </p>
                                )}
                            </div>

                            {/* Running Indicator */}
                            {stage.status === 'running' && (
                                <motion.div
                                    className="absolute -top-1 -right-1 w-3 h-3 bg-cyan-400 rounded-full"
                                    animate={{ scale: [1, 1.3, 1] }}
                                    transition={{ duration: 1, repeat: Infinity }}
                                />
                            )}
                        </motion.div>

                        {/* Connector Arrow */}
                        {index < stages.length - 1 && (
                            <div className="relative z-10 px-2">
                                <ChevronRight
                                    size={16}
                                    className={`${stages[index + 1].status !== 'pending' ? 'text-cyan-500' : 'text-gray-700'
                                        } transition-colors duration-300`}
                                />
                            </div>
                        )}
                    </React.Fragment>
                ))}
            </div>

            {/* Active Stage Details */}
            <AnimatePresence>
                {stages.find(s => s.status === 'running')?.details && (
                    <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: 'auto' }}
                        exit={{ opacity: 0, height: 0 }}
                        className="mt-4 p-3 bg-cyan-500/10 border border-cyan-500/20 rounded-lg"
                    >
                        <p className="text-xs text-cyan-300 font-mono">
                            {stages.find(s => s.status === 'running')?.details}
                        </p>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

export default BuildPipeline;

import React, { useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Cpu, CheckCircle, Clock, AlertCircle, ChevronDown, ChevronUp } from 'lucide-react';

export interface AgentStep {
    key: string;
    name: string;
    status: 'pending' | 'running' | 'done' | 'failed';
    error?: string;
    duration?: number;
}

export interface AgentActivityProps {
    status: 'idle' | 'thinking' | 'executing' | 'error';
    steps?: AgentStep[];
    logs?: string[];
    expanded?: boolean;
    onToggle?: () => void;
    runId?: string | null;
}

export const AgentActivity: React.FC<AgentActivityProps> = ({
    status,
    steps = [],
    logs: _logs = [],
    expanded = true,
    onToggle,
    runId: _runId
}) => {
    // We only show if status is NOT idle/done (unless we want to show result for a bit)
    // But per user request: "disappear and show answer". 
    // So if status is 'idle' (done), we ideally hide or show a collapsed "Done" state.
    // Let's hide completely if idle and no active steps? 
    // Actually, 'idle' usually means "waiting for user" or "done".

    if (status === 'idle') return null;

    const currentStep = useMemo(() => steps.find(s => s.status === 'running') || steps[steps.length - 1], [steps]);

    // Auto-scroll logs
    // (Omitted for brevity as logs might be empty)

    return (
        <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95 }}
            className="rounded-xl overflow-hidden glass-panel border border-white/10 bg-black/40 mb-4"
        >
            {/* Header / Summary */}
            <div
                className="p-3 flex items-center justify-between cursor-pointer hover:bg-white/5 transition-colors"
                onClick={onToggle}
            >
                <div className="flex items-center gap-3">
                    {/* Orb Animation */}
                    <div className="relative w-8 h-8 flex items-center justify-center">
                        <div className={`absolute inset-0 rounded-full blur-md transition-colors duration-500
                            ${status === 'error' ? 'bg-red-500/50' :
                                status === 'thinking' ? 'bg-purple-500/50' : 'bg-cyan-500/50'} 
                            animate-pulse`}
                        />
                        <div className={`relative z-10 w-6 h-6 rounded-full flex items-center justify-center border
                            ${status === 'error' ? 'bg-red-900/80 border-red-500' :
                                status === 'thinking' ? 'bg-purple-900/80 border-purple-500' : 'bg-cyan-900/80 border-cyan-500'}`}
                        >
                            {status === 'error' ? <AlertCircle size={14} className="text-red-200" /> :
                                <Cpu size={14} className={`text-white ${status === 'thinking' || status === 'executing' ? 'animate-spin-slow' : ''}`} />}
                        </div>
                    </div>

                    {/* Text Status */}
                    <div className="flex flex-col">
                        <span className="text-sm font-medium text-gray-200 flex items-center gap-2">
                            {status === 'thinking' ? 'Thinking...' :
                                status === 'executing' ? (currentStep?.name || 'Processing...') :
                                    'System Active'}
                        </span>
                        {steps.length > 0 && (
                            <span className="text-xs text-gray-500">
                                {steps.filter(s => s.status === 'done').length} / {steps.length} steps
                            </span>
                        )}
                    </div>
                </div>

                <div className="text-gray-500">
                    {expanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                </div>
            </div>

            {/* Expanded Content */}
            <AnimatePresence>
                {expanded && (
                    <motion.div
                        initial={{ height: 0 }}
                        animate={{ height: 'auto' }}
                        exit={{ height: 0 }}
                        className="overflow-hidden"
                    >
                        <div className="p-3 pt-0 border-t border-white/5 space-y-2 bg-black/20">
                            {steps.map((step) => (
                                <div key={step.key} className="flex items-center gap-3 text-xs">
                                    <div className="w-4 flex justify-center">
                                        {step.status === 'running' ? (
                                            <div className="w-2 h-2 bg-cyan-400 rounded-full animate-ping" />
                                        ) : step.status === 'done' ? (
                                            <CheckCircle size={12} className="text-green-400" />
                                        ) : step.status === 'failed' ? (
                                            <AlertCircle size={12} className="text-red-400" />
                                        ) : (
                                            <div className="w-2 h-2 bg-gray-600 rounded-full" />
                                        )}
                                    </div>
                                    <span className={`${step.status === 'running' ? 'text-cyan-200 font-medium' :
                                        step.status === 'done' ? 'text-gray-400' : 'text-gray-500'
                                        }`}>
                                        {step.name}
                                    </span>
                                    {step.duration && (
                                        <span className="ml-auto text-[10px] text-gray-600 flex items-center gap-1">
                                            <Clock size={8} /> {step.duration.toFixed(1)}s
                                        </span>
                                    )}
                                </div>
                            ))}

                            {steps.length === 0 && (
                                <div className="text-center text-xs text-gray-600 py-2 italic">
                                    Formulating plan...
                                </div>
                            )}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </motion.div>
    );
};
